@functools.lru_cache(maxsize=1)
def game_start_sender_sites() -> tuple[tuple[str, str], ...]:
    """Find canonical game-start construction sites without entering caches."""
    sites: list[tuple[str, str]] = []
    source_root = REPOSITORY_ROOT / "src"
    patterns = {
        kind: re.compile(rf"\b{kind}\s*<\s*event_type::game_start\s*>")
        for kind in ("send", "make")
    }
    # Proof requires the whole sender set, even when game.cpp still contains
    # the canonical sender.  Scan the flat engine sources once per process;
    # the cache above avoids repeating this work for every migrated EOC.
    for suffix in ("*.cpp", "*.h"):
        for path in sorted(source_root.glob(suffix)):
            text = path.read_text(encoding="utf-8")
            relative = path.relative_to(REPOSITORY_ROOT).as_posix()
            for kind, pattern in patterns.items():
                count = len(pattern.findall(text))
                sites.extend((relative, kind) for _ in range(count))
    return tuple(sorted(sites))


@functools.lru_cache(maxsize=1)
def event_character_actor_fields() -> dict[str, str]:
    """Read the authoritative event-spec character field for each event.

    Event payloads may identify the primary Character as ``character``,
    ``attacker``, or ``killer``.  The native event contract in ``src/event.h``
    is the source of truth; deriving this map avoids adding an ambient avatar
    fallback when an event has a concrete but non-avatar actor.
    """
    path = REPOSITORY_ROOT / "src" / "event.h"
    try:
        text = path.read_text(encoding="utf-8")
    except OSError:
        return {}
    result: dict[str, str] = {}
    blocks = re.finditer(
        r"template<>\s*struct event_spec<event_type::([A-Za-z0-9_]+)>"
        r"(.*?)(?=\n\s*template<>|\Z)",
        text,
        re.DOTALL,
    )
    for match in blocks:
        event_name, block = match.groups()
        if "event_spec_character_item" in block or "event_spec_character" in block:
            result[event_name] = "character"
            continue
        character_field = re.search(
            r'\{\s*"([A-Za-z0-9_]+)"\s*,\s*cata_variant_type::character_id',
            block,
        )
        if character_field is not None:
            result[event_name] = character_field.group(1)
    return result


def game_start_avatar_actor_is_proven(
    game_start_event_emitted_by_eoc: bool,
) -> bool:
    """Require the reviewed native sender set and no in-corpus JSON replay.

    This static corpus gate cannot observe trusted Lua calling
    ``services.native_events.emit("game_start", ...)``.  It proves only that
    no JSON-authored trigger can re-enter a game_start handler with another
    dialogue actor.
    """
    return (
        not game_start_event_emitted_by_eoc and
        game_start_sender_sites() == EXPECTED_GAME_START_SENDER_SITES
    )


def native_eoc_required_event(value: dict[str, Any]) -> str | None:
    """Return the trigger that the native loader actually registers."""
    if value.get("eoc_type") != "EVENT":
        return None
    event = value.get("required_event")
    return event if isinstance(event, str) and event else None


def render_static_item_fault_effect(
    effect: dict[str, Any],
    key: str,
) -> list[str] | None:
    """Render the bounded item-event form of a native fault mutation.

    The legacy handler receives the item through the item-event actor and the
    owning Character through the same event's character actor.  Only literal
    fault/type strings and literal force/message flags are safe to lower; all
    variable-backed shapes remain explicit migration TODOs.
    """
    if set(effect) - {key, "force", "message"}:
        return None
    raw_value = effect.get(key)
    if (
        not isinstance(raw_value, str) or
        not safe_platform_id(raw_value) or
        not bounded_utf8_string(raw_value, PLATFORM_ID_MAX_BYTES)
    ):
        return None
    force = effect.get("force", False)
    message = effect.get("message", True)
    if not isinstance(force, bool) or not isinstance(message, bool):
        return None
    options: list[str] = ["holder = actor"]
    if force:
        options.append("force = true")
    if not message:
        options.append("message = false")
        options = [option for option in options if option != "holder = actor"]
    return [
        "    if context.actors.item ~= nil then",
        f"        services.items.{'set_fault' if key in {'npc_set_fault', 'u_set_fault'} else 'set_random_fault'}(",
        "            context.actors.item,",
        f"            {lua_quote(raw_value)}," if key in {"npc_set_random_fault_of_type", "u_set_random_fault_of_type"} else
        "            services.types.id(\"fault\", " + lua_quote(raw_value) + "),",
        "            { " + ", ".join(options) + " })" if options else
        "            {})",
        "    end",
    ]


def render_static_item_activation_effect(
    effect: dict[str, Any],
    key: str,
) -> list[str] | None:
    """Render an explicit item use method for a proven item event.

    The native EOC handler may resolve a method from dialogue/context
    variables and may open an interactive picker when the method is empty.
    Platform callbacks are deliberately non-interactive, so only a bounded
    literal method with no dynamic target is lowered here.
    """
    if set(effect) != {key}:
        return None
    method = effect.get(key)
    if not isinstance(method, str) or not safe_platform_id(method):
        return None
    if not bounded_utf8_string(method, PLATFORM_ID_MAX_BYTES):
        return None
    return [
        "    if context.actors.item ~= nil and actor ~= nil then",
        "        services.items.activate(",
        "            context.actors.item, actor, " + lua_quote(method) + ", {",
        "                target = service_value(services.characters.snapshot(actor)).creature.position,",
        "            })",
        "    end",
    ]


def render_dynamic_item_activation_effect(
    effect: dict[str, Any], key: str, actor_expression: str | None,
    avatar_actor_proven: bool = False,
    npc_actor_proven: bool = False,
) -> list[str] | None:
    """Render an item activation whose method comes from a typed variable."""
    if (
        actor_expression is None or key not in effect or
        set(effect) != {key}
    ):
        return None
    method = render_eoc_string_expression(effect[key], actor_expression)
    if method is None:
        return None
    return [
        "    if context.actors.item ~= nil and " + actor_expression + " ~= nil then",
        "        service_value(services.items.activate(",
        "            context.actors.item, " + actor_expression + ", " + method + ", {",
        "                target = service_value(services.characters.snapshot(" +
        actor_expression + ")).creature.position,",
        "            }))",
        "    end",
    ]


def render_dynamic_item_fault_effect(
    effect: dict[str, Any], key: str,
) -> list[str] | None:
    """Render literal or variable-backed item fault mutations."""
    if key not in effect or set(effect) - {key, "force", "message"}:
        return None
    if not isinstance(effect[key], str) or not bounded_platform_id(effect[key]):
        return None
    raw = lua_quote(effect[key])
    force = effect.get("force", False)
    message = effect.get("message", True)
    if not isinstance(force, bool) or not isinstance(message, bool):
        return None
    options = ["holder = actor"]
    if force:
        options.append("force = true")
    if not message:
        options = [option for option in options if option != "holder = actor"]
        options.append("message = false")
    function = "set_fault" if key in {"u_set_fault", "npc_set_fault"} else "set_random_fault"
    argument = (
        f'services.types.id("fault", {raw})'
        if function == "set_fault" else raw
    )
    return [
        "    if context.actors.item ~= nil then",
        f"        service_value(services.items.{function}(",
        "            context.actors.item,",
        f"            {argument}, {{ {', '.join(options)} }}))",
        "    end",
    ]


def render_dynamic_item_transform_effect(
    effect: dict[str, Any], actor_expression: str | None,
) -> list[str] | None:
    """Render dynamic item transforms while preserving active/browsed flags."""
    if actor_expression is None or "transform_item" not in effect:
        return None
    if set(effect) - {"transform_item", "active", "browsed"}:
        return None
    target = _dynamic_id_expression(
        effect["transform_item"], "item", actor_expression
    )
    if target is None:
        return None
    active = effect.get("active", False)
    browsed = effect.get("browsed")
    if not isinstance(active, bool) or (browsed is not None and not isinstance(browsed, bool)):
        return None
    options = ["carrier = " + actor_expression, f"active = {lua_boolean(active)}"]
    if browsed is not None:
        options.append(f"browsed = {lua_boolean(browsed)}")
    return [
        "    if context.actors.item ~= nil then",
        "        service_value(services.items.transform(",
        "            context.actors.item,",
        f"            {target}, {{ {', '.join(options)} }}))",
        "    end",
    ]


def native_int_literal(value: Any) -> int | None:
    """Truncate a finite literal as the native double-to-int conversion does."""
    if isinstance(value, int) and not isinstance(value, bool):
        return value if NATIVE_INT_MIN <= value <= NATIVE_INT_MAX else None
    if not isinstance(value, float) or not math.isfinite(value):
        return None
    # C++ truncates toward zero before checking whether the result fits int.
    if value <= NATIVE_INT_MIN - 1 or value >= NATIVE_INT_MAX + 1:
        return None
    converted = math.trunc(value)
    return converted if NATIVE_INT_MIN <= converted <= NATIVE_INT_MAX else None


def render_static_light_override(effect: dict[str, Any]) -> list[str] | None:
    """Render a literal custom-light event with the native append semantics."""
    if set(effect) - {"custom_light_level", "length", "key"}:
        return None
    level = native_int_literal(effect.get("custom_light_level"))
    if level is None:
        return None
    duration = parse_turns(effect.get("length", 0))
    if duration is None or not NATIVE_INT_MIN <= duration <= NATIVE_INT_MAX:
        return None
    key = effect.get("key", "")
    if not isinstance(key, str):
        return None
    call = [
        "    service_value(services.weather.append_light_event(",
        f"        {level}, services.time.duration({duration}, \"turn\")",
    ]
    if key:
        call[-1] += f", {lua_quote(key)}))"
    else:
        call[-1] += "))"
    return call


def lua_boolean(value: bool) -> str:
    return "true" if value else "false"


def content_submit_expression() -> str:
    return "content.replace(definition)" if EMIT_REPLACE_CONTENT else \
        "content.add(definition)"


def lua_quote(value: str) -> str:
    escapes = {
        "\\": "\\\\",
        '"': '\\"',
        "\a": "\\a",
        "\b": "\\b",
        "\f": "\\f",
        "\n": "\\n",
        "\r": "\\r",
        "\t": "\\t",
        "\v": "\\v",
    }
    escaped: list[str] = []
    for character in value:
        if character in escapes:
            escaped.append(escapes[character])
        elif ord(character) < 32 or ord(character) == 127:
            escaped.append(f"\\{ord(character):03d}")
        else:
            escaped.append(character)
    return '"' + "".join(escaped) + '"'


def lua_number(value: int | float) -> str:
    if isinstance(value, int):
        return str(value)
    return format(value, ".17g")


def finite_number_literal(value: Any) -> int | float | None:
    if not isinstance(value, (int, float)) or isinstance(value, bool):
        return None
    try:
        if math.isfinite(float(value)):
            return value
    except (OverflowError, ValueError):
        pass
    return None


def positive_native_float_literal(value: Any) -> int | float | None:
    """Return a literal that remains positive after the native float cast."""
    literal = finite_number_literal(value)
    if literal is None:
        return None
    converted = float(literal)
    if converted <= 0.0 or converted > NATIVE_FLOAT_MAX:
        return None
    try:
        native = struct.unpack("=f", struct.pack("=f", converted))[0]
    except (OverflowError, struct.error):
        return None
    return literal if math.isfinite(native) and native > 0.0 else None


def display_text(value: Any, fallback: str = "") -> str:
    if isinstance(value, str):
        return value
    if isinstance(value, dict):
        text = value.get("str")
        if isinstance(text, str):
            return text
    return fallback


def parse_integral_unit(value: Any, units: dict[str, float]) -> int | None:
    if isinstance(value, int) and not isinstance(value, bool):
        return value
    if not isinstance(value, str):
        return None
    # Cataclysm accepts compound unit strings such as ``1 hours 30
    # minutes``.  The old single-token parser silently rejected those common
    # activity/delay durations and produced a migration TODO even though the
    # native value is an exact integral turn count.
    matches = re.findall(
        r"([+-]?\d+(?:\.\d+)?)\s*([A-Za-z]+)", value
    )
    if not matches or re.fullmatch(
        r"\s*(?:[+-]?\d+(?:\.\d+)?\s*[A-Za-z]+\s*)+", value
    ) is None or any(unit.lower() not in units for _, unit in matches):
        return None
    converted = sum(
        float(number) * units[unit.lower()]
        for number, unit in matches
    )
    return int(converted) if converted.is_integer() else None


def parse_moves(value: Any) -> int | None:
    return parse_integral_unit(
        value,
        {
            "move": 1,
            "moves": 1,
            "s": 100,
            "sec": 100,
            "second": 100,
            "seconds": 100,
            "m": 6000,
            "min": 6000,
            "minute": 6000,
            "minutes": 6000,
            "h": 360000,
            "hour": 360000,
            "hours": 360000,
        },
    )


def parse_seconds(value: Any) -> int | None:
    return parse_integral_unit(
        value,
        {
            "s": 1,
            "sec": 1,
            "second": 1,
            "seconds": 1,
            "m": 60,
            "min": 60,
            "minute": 60,
            "minutes": 60,
            "h": 3600,
            "hour": 3600,
            "hours": 3600,
        },
    )


def parse_turns(value: Any) -> int | None:
    return parse_integral_unit(
        value,
        {
            "turn": 1,
            "turns": 1,
            "s": 1,
            "sec": 1,
            "second": 1,
            "seconds": 1,
            "m": 60,
            "min": 60,
            "minute": 60,
            "minutes": 60,
            "h": 3600,
            "hour": 3600,
            "hours": 3600,
            "d": 86400,
            "day": 86400,
            "days": 86400,
        },
    )


def parse_turn_cost_adjustment(value: Any) -> int | None:
    """Convert a native literal duration within the Platform move-adjustment bound."""
    turns = parse_native_duration_turns(value)
    if turns is None:
        return None
    moves = turns * 100
    if not NATIVE_INT_MIN <= moves <= NATIVE_INT_MAX:
        return None
    adjustment = -moves
    if not (
        -PLATFORM_CHARACTER_ADJUSTMENT_LIMIT <= adjustment <=
        PLATFORM_CHARACTER_ADJUSTMENT_LIMIT
    ):
        return None
    return adjustment


def parse_native_duration_turns(value: Any) -> int | None:
    """Parse only the integer syntax and units accepted by native time_duration."""
    if isinstance(value, int) and not isinstance(value, bool):
        return value if NATIVE_INT_MIN <= value <= NATIVE_INT_MAX else None
    if not isinstance(value, str):
        return None
    # Keep this list aligned with time_duration::units; parse_turns also accepts
    # legacy spellings that the native JSON duration parser rejects.
    units = {
        "turns": 1,
        "turn": 1,
        "t": 1,
        "seconds": 1,
        "second": 1,
        "s": 1,
        "minutes": 60,
        "minute": 60,
        "m": 60,
        "hours": 3600,
        "hour": 3600,
        "h": 3600,
        "days": 86400,
        "day": 86400,
        "d": 86400,
    }
    unit_pattern = "|".join(
        re.escape(unit) for unit in sorted(units, key=len, reverse=True)
    )
    token_pattern = rf"[+-]?[0-9]+ *({unit_pattern})"
    if re.fullmatch(rf" *(?:{token_pattern} *)+", value) is None:
        return None
    total = 0
    for number, unit in re.findall(
        rf"([+-]?[0-9]+) *({unit_pattern})", value
    ):
        component = int(number) * units[unit]
        if not NATIVE_INT_MIN <= component <= NATIVE_INT_MAX:
            return None
        total += component
        if not NATIVE_INT_MIN <= total <= NATIVE_INT_MAX:
            return None
    return total


def parse_vitamin_micrograms(value: Any) -> int | None:
    if not isinstance(value, str):
        return None
    tokens = re.findall(r"([+-]?\d+(?:\.\d+)?)\s*(ug|μg|mcg|mg|g)", value)
    if not tokens:
        return None
    without_tokens = re.sub(
        r"([+-]?\d+(?:\.\d+)?)\s*(ug|μg|mcg|mg|g)", "", value
    )
    if without_tokens.strip():
        return None
    scales = {"ug": 1.0, "μg": 1.0, "mcg": 1.0, "mg": 1000.0, "g": 1000000.0}
    total = sum(float(amount) * scales[unit] for amount, unit in tokens)
    return int(total) if total.is_integer() else None


def stable_id(value: dict[str, Any], fallback: str) -> str:
    for key in ("id", "abstract", "result"):
        candidate = value.get(key)
        if isinstance(candidate, str) and candidate:
            return candidate
    return fallback


def safe_platform_id(value: Any) -> bool:
    return (
        isinstance(value, str) and
        bool(value) and
        "#" not in value and
        "\0" not in value
    )


def safe_native_martial_art_id(value: Any) -> bool:
    if not safe_platform_id(value):
        return False
    try:
        encoded_length = len(value.encode("utf-8"))
    except UnicodeEncodeError:
        return False
    return (
        encoded_length <= 256 and
        not any(ord(character) < 0x20 or ord(character) == 0x7f for character in value)
    )


def safe_native_recipe_id(value: Any) -> bool:
    """Bound a static recipe id literal; registry membership remains a source precondition."""
    if not safe_platform_id(value):
        return False
    try:
        encoded_length = len(value.encode("utf-8"))
    except UnicodeEncodeError:
        return False
    return (
        encoded_length <= 256 and
        not any(ord(character) < 0x20 or ord(character) == 0x7f for character in value)
    )


def safe_native_proficiency_id_literal(value: Any) -> bool:
    """Preserve raw native proficiency text without requiring a registered ID."""
    return lua_quotable_native_variable_string(value)


def render_proficiency_id_expression(
    value: Any, *, alpha_owner: str | None = None,
    beta_owner: str | None = None,
) -> str | None:
    """Keep native ID text and resolve each variable from its proven talker."""
    if safe_native_proficiency_id_literal(value):
        return lua_quote(value)
    if not isinstance(value, dict):
        return None
    scopes = {"global_val", "context_val", "u_val", "npc_val"} & set(value)
    if len(scopes) != 1 or set(value) - scopes - {"default"}:
        return None
    scope = next(iter(scopes))
    name = value[scope]
    fallback = value.get("default", "")
    if not (lua_quotable_native_variable_string(name) and
            lua_quotable_native_variable_string(fallback)):
        return None
    if scope == "context_val":
        read = (
            'service_value(services.variables.get_context_string('
            'context and context.data, ' + lua_quote(name) + '))'
        )
    elif scope == "global_val":
        read = (
            'service_value(services.variables.get_global_string(' +
            lua_quote(name) + '))'
        )
    else:
        owner = alpha_owner if scope == "u_val" else beta_owner
        if owner is None:
            return None
        read = (
            'service_value(services.variables.get_string(' + owner + ', ' +
            lua_quote(name) + '))'
        )
    return (
        '(function(result) if result.exists == false then return ' + lua_quote(fallback) +
        ' end; return type(result.value) == "string" and result.value or "" end)'
        '(' + read + ')'
    )


def bounded_utf8_string(
    value: Any, maximum: int, *, allow_empty: bool = False
) -> bool:
    if (
        not isinstance(value, str) or
        (not allow_empty and not value) or
        "\0" in value
    ):
        return False
    try:
        length = len(value.encode("utf-8"))
    except UnicodeEncodeError:
        return False
    return (allow_empty or length > 0) and length <= maximum


def lua_quotable_native_variable_string(value: Any) -> bool:
    """Accept any native variable string that can be embedded in generated Lua."""
    if not isinstance(value, str):
        return False
    try:
        value.encode("utf-8")
    except UnicodeEncodeError:
        return False
    return True


def bounded_platform_context_variable_key(value: Any) -> bool:
    """Match the context/var key contract used by the Platform variable service."""
    return lua_quotable_native_variable_string(value)


def bounded_platform_id(value: Any) -> bool:
    return (
        safe_platform_id(value) and
        bounded_utf8_string(value, PLATFORM_ID_MAX_BYTES)
    )


def bounded_overmap_condition_id(value: Any) -> bool:
    """Match the terrain text accepted by native-condition query services."""
    return (
        bounded_platform_id(value) and
        not any(ord(character) < 0x20 or ord(character) == 0x7F for character in value)
    )


def bounded_platform_body_part_id(value: Any) -> bool:
    # `NULL` is not a body-part ID (the registered null ID is `bp_null`).
    # Platform typed IDs reject it while native bodypart conversion falls
    # back to the null part, so do not emit a service call for this shape.
    return bounded_platform_id(value) and value != "NULL"


def lua_function_name(identifier: str) -> str:
    """Return a deterministic private Lua function name for a legacy id."""
    pieces: list[str] = []
    for character in unicodedata.normalize("NFKC", identifier):
        if character.isascii() and (character.isalnum() or character == "_"):
            pieces.append(character)
        else:
            pieces.append(f"_{ord(character):x}_")
    value = "".join(pieces).strip("_") or "anonymous"
    if value[0].isdigit():
        value = "_" + value
    return "migrated_eoc_" + value


# These members contain EOC descriptors in addition to the historical string
# references.  The migrator normalises descriptor objects into private local
# functions before rendering the owning EOC.  Keeping this list closed is
# important: an arbitrary JSON object must never become executable Lua merely
# because it happens to contain an ``effect`` member.
INLINE_EOC_MEMBERS = frozenset({
    "run_eocs", "true_eocs", "false_eocs",
    "weighted_list_eocs",
    "result_eocs",
    "eocs", "onhit_eocs", "ondamage_eocs", "onkill_eocs",
    "ongethit_eocs", "onmove_eocs", "ondodge_eocs",
    "onblock_eocs", "onpause_eocs",
    # Item ticks and mutation/bionic hooks are ordinary EOC reference arrays,
    # but they also carry a concrete actor lifetime.  Mark them here so the
    # referenced function is emitted as an item/character callback rather than
    # an unbound top-level handler.
    "effect_on_conditions", "activated_eocs", "processed_eocs",
    "deactivated_eocs",
    "u_run_npc_eocs", "npc_run_npc_eocs",
    "u_run_monster_eocs", "npc_run_monster_eocs",
    "u_run_vehicle_eocs", "npc_run_vehicle_eocs",
    "u_run_fixed_zone_eocs", "npc_run_fixed_zone_eocs",
    "u_map_run_eocs", "npc_map_run_eocs",
    "u_map_run_item_eocs", "npc_map_run_item_eocs",
})


def _inline_actor_kind(member: str) -> str:
    if member == "weighted_list_eocs":
        return "character"
    if member in {
        "result_eocs", "eocs", "onhit_eocs", "ondamage_eocs",
        "onkill_eocs", "ongethit_eocs", "onmove_eocs",
        "ondodge_eocs", "onblock_eocs", "onpause_eocs",
    }:
        return "character"
    if member == "effect_on_conditions":
        return "item"
    if member in {"activated_eocs", "processed_eocs", "deactivated_eocs"}:
        return "character"
    if "npc" in member and "monster" not in member:
        return "character"
    if "monster" in member:
        return "creature"
    if "vehicle" in member:
        return "vehicle"
    if "zone" in member:
        return "zone"
    if "item" in member or member in {"run_inv_eocs", "true_eocs", "false_eocs"}:
        return "item"
    if "map_run_eocs" in member:
        return "coordinate"
    return "inherit"


def normalize_inline_eocs(
    objects: list[SourceObject],
    game_start_event_emitted_by_eoc: bool,
) -> tuple[
    list[SourceObject], frozenset[str], frozenset[str], frozenset[str], frozenset[str]
]:
    """Replace inline EOC descriptors with deterministic private references.

    Native ``load_inline_eoc`` accepts an object anywhere a named EOC is
    accepted.  Platform has no EOC runner, so the equivalent is a normal Lua
    local function.  This pass gives every inline descriptor a collision-free
    id and records which named functions can receive a Character override from
    an NPC traversal.  The returned objects are deep copies; callers that use
    the source list for diagnostics therefore retain the original JSON shape.
    """
    known_ids = {
        stable_id(source.value, f"anonymous_{source.index}")
        for source in objects
        if source.value.get("type") in EOC_TYPES
    }
    character_override_ids: set[str] = set()
    item_override_ids: set[str] = set()
    creature_override_ids: set[str] = set()
    vehicle_override_ids: set[str] = set()
    synthetic: list[SourceObject] = []
    counter = 0

    def unique_id(parent: str, member: str, index: int) -> str:
        nonlocal counter
        candidate = parent + "__" + member + "__" + str(index)
        if not safe_platform_id(candidate) or len(candidate.encode("utf-8")) > PLATFORM_ID_MAX_BYTES:
            candidate = f"__inline_eoc_{counter}"
        while candidate in known_ids:
            counter += 1
            candidate = f"__inline_eoc_{counter}"
        known_ids.add(candidate)
        counter += 1
        return candidate

    def actor_kind_for(node: Any) -> str:
        # Item/talker provenance is more specific than the generic character
        # scan.  A conditional such as `if: has_alpha` often also contains
        # u_/npc_ effects, but its inline callbacks still need the item
        # context and must not lose the topic item handle.
        if _node_has_item_actor(node):
            return "item"
        if _node_mentions_actor(node):
            return "character"
        return "inherit"

    def lower_descriptor(
        entry: dict[str, Any], parent: str, member: str, index: int,
        source: SourceObject, actor_kind: str,
    ) -> str:
        child = copy.deepcopy(entry)
        child_id = child.get("id")
        if not isinstance(child_id, str) or not child_id:
            child_id = unique_id(parent, member, index)
        elif child_id in known_ids:
            child_id = unique_id(parent, member, index)
        else:
            known_ids.add(child_id)
        child["type"] = "effect_on_condition"
        child["id"] = child_id
        child["__inline_eoc"] = True
        child["__inline_actor_kind"] = actor_kind
        child_source = SourceObject(
            source.path, source.index * 100000 + counter, child
        )
        # Branches inside an inline callback inherit the callback's actor
        # lifetime.  This matters for item traversals: legacy item EOCs often
        # use ``npc_*`` flag selectors even though the active actor is the
        # selected item/talker, not an NPC Character.
        child = walk(child, child_id, child_source, actor_kind)
        child_source = SourceObject(child_source.path, child_source.index, child)
        synthetic.append(child_source)
        if actor_kind == "character":
            character_override_ids.add(child_id)
        elif actor_kind == "item":
            item_override_ids.add(child_id)
        elif actor_kind == "creature":
            creature_override_ids.add(child_id)
        elif actor_kind == "vehicle":
            vehicle_override_ids.add(child_id)
        return child_id

    def walk(
        node: Any,
        parent: str,
        source: SourceObject,
        inherited_actor_kind: str = "inherit",
    ) -> Any:
        if isinstance(node, list):
            return [
                walk(entry, parent, source, inherited_actor_kind)
                for entry in node
            ]
        if not isinstance(node, dict):
            return node
        result = copy.deepcopy(node)

        # Effect nodes carry the selector/branches as sibling members (the
        # ``switch`` member is only the selector expression).  Normalize those
        # nodes before walking their children so each branch becomes a private
        # callback rather than an opaque legacy object.  Native ``f_switch``
        # has no action-level default branch, so leave that whole switch intact
        # for the renderer to report as a manual rewrite.
        if "switch" in result and isinstance(result.get("cases"), list):
            if "default" not in result:
                switch_cases = result.get("cases")
                actor_kind = (
                    inherited_actor_kind
                    if inherited_actor_kind != "inherit"
                    else actor_kind_for(result)
                )
                for case_index, case in enumerate(switch_cases):
                    if not isinstance(case, dict) or "effect" not in case:
                        continue
                    descriptor = {
                        "type": "effect_on_condition",
                        "effect": case.get("effect"),
                    }
                    child_id = lower_descriptor(
                        descriptor, parent, "switch", case_index,
                        source, actor_kind,
                    )
                    case["effect"] = {"run_eocs": child_id}

        if "if" in result and "then" in result:
            actor_kind = (
                inherited_actor_kind
                if inherited_actor_kind != "inherit"
                else actor_kind_for(result)
            )
            for branch_name in ("then", "else"):
                if branch_name not in result:
                    continue
                descriptor = {
                    "type": "effect_on_condition",
                    "effect": result.get(branch_name),
                }
                child_id = lower_descriptor(
                    descriptor, parent, f"if_{branch_name}", 0,
                    source, actor_kind,
                )
                result[branch_name] = {"run_eocs": child_id}

        roll_vector_actor_kind: str | None = None
        if (
            "u_roll_remainder" in result and
            "npc_roll_remainder" not in result and
            not _node_has_item_actor(result)
        ):
            # f_roll_remainder runs its vectors through run_eoc_vector(d),
            # preserving the original dialogue alpha.  Its u_ form can pass
            # that same Character alpha to callbacks only when this owner's
            # source/inherited shape is Character-capable; it is not a global
            # avatar lookup.  Leave item-shaped, unproven, and beta-oriented
            # calls on the ordinary conservative member mapping.
            owner_actor_kind = (
                inherited_actor_kind
                if inherited_actor_kind != "inherit"
                else actor_kind_for(result)
            )
            if owner_actor_kind in {"avatar", "character"}:
                roll_vector_actor_kind = "character"

        for member, raw in list(result.items()):
            # ``switch`` and nested ``if`` branches are effect containers, not
            # ordinary data tables.  Lower each branch to a private callback
            # before the owning EOC is rendered.  This keeps the generated
            # source in normal Lua control flow while reusing the same typed
            # effect renderer for arbitrarily nested branches.
            if member == "switch" and isinstance(raw, dict):
                switch = copy.deepcopy(raw)
                switch_cases = switch.get("cases")
                actor_kind = (
                    inherited_actor_kind
                    if inherited_actor_kind != "inherit"
                    else actor_kind_for(switch)
                )
                # This non-canonical nested form is not a native switch
                # branch container.  In particular, never reinterpret its
                # ``default`` member as an executable fallback callback.
                if isinstance(switch_cases, list) and "default" not in switch:
                    for case_index, case in enumerate(switch_cases):
                        if not isinstance(case, dict) or "effect" not in case:
                            continue
                        branch = case.get("effect")
                        descriptor = {
                            "type": "effect_on_condition",
                            "effect": branch,
                        }
                        child_id = lower_descriptor(
                            descriptor, parent, "switch", case_index,
                            source, actor_kind,
                        )
                        case["effect"] = {"run_eocs": child_id}
                    switch["cases"] = switch_cases
                result[member] = switch
                continue
            if member == "if" and isinstance(raw, dict) and "then" in raw:
                conditional = copy.deepcopy(raw)
                actor_kind = (
                    inherited_actor_kind
                    if inherited_actor_kind != "inherit"
                    else actor_kind_for(conditional)
                )
                for branch_name in ("then", "else"):
                    if branch_name not in conditional:
                        continue
                    branch = conditional.get(branch_name)
                    descriptor = {
                        "type": "effect_on_condition",
                        "effect": branch,
                    }
                    child_id = lower_descriptor(
                        descriptor, parent, f"if_{branch_name}", 0,
                        source, actor_kind,
                    )
                    conditional[branch_name] = {"run_eocs": child_id}
                result[member] = conditional
                continue
            if member not in INLINE_EOC_MEMBERS:
                result[member] = walk(
                    raw, parent, source, inherited_actor_kind
                )
                continue
            single_descriptor = isinstance(raw, dict)
            scalar_member = member in {
                "run_eocs", "u_map_run_eocs", "npc_map_run_eocs",
            }
            if single_descriptor:
                raw = [raw]
            if not isinstance(raw, list):
                result[member] = walk(
                    raw, parent, source, inherited_actor_kind
                )
                continue
            replacement: list[Any] = []
            actor_kind = (
                roll_vector_actor_kind
                if member in {"true_eocs", "false_eocs"} and
                roll_vector_actor_kind is not None else
                _inline_actor_kind(member)
            )
            if inherited_actor_kind == "unproven":
                actor_kind = "unproven"
            elif actor_kind == "inherit":
                actor_kind = inherited_actor_kind
            for index, entry in enumerate(raw):
                if (
                    member == "weighted_list_eocs" and
                    isinstance(entry, list) and len(entry) == 2
                ):
                    pair = copy.deepcopy(entry)
                    if isinstance(pair[0], dict) and (
                        "effect" in pair[0] or "condition" in pair[0] or
                        "false_effect" in pair[0]
                    ):
                        pair[0] = lower_descriptor(
                            pair[0], parent, member, index, source, actor_kind
                        )
                    elif isinstance(pair[0], str) and actor_kind == "character":
                        character_override_ids.add(pair[0])
                    elif isinstance(pair[0], str) and actor_kind == "vehicle":
                        vehicle_override_ids.add(pair[0])
                    replacement.append(pair)
                    continue
                if isinstance(entry, dict) and (
                    "effect" in entry or "condition" in entry or
                    "false_effect" in entry
                ):
                    replacement.append(
                        lower_descriptor(entry, parent, member, index, source, actor_kind)
                    )
                else:
                    if isinstance(entry, str) and actor_kind == "character":
                        character_override_ids.add(entry)
                    elif isinstance(entry, str) and actor_kind == "item":
                        item_override_ids.add(entry)
                    elif isinstance(entry, str) and actor_kind == "creature":
                        creature_override_ids.add(entry)
                    elif isinstance(entry, str) and actor_kind == "vehicle":
                        vehicle_override_ids.add(entry)
                    replacement.append(copy.deepcopy(entry))
            result[member] = (
                replacement[0] if single_descriptor and scalar_member and replacement
                else replacement
            )
        return result

    normalized: list[SourceObject] = []
    for source in objects:
        required_event = native_eoc_required_event(source.value)
        inherited_actor_kind = "inherit"
        if (
            required_event == "game_start" and
            not game_start_avatar_actor_is_proven(
                game_start_event_emitted_by_eoc
            )
        ):
            # Do not let nested actor-shape inference recreate the source
            # proof rejected by the corpus-level replay gate.
            inherited_actor_kind = "unproven"
        elif isinstance(required_event, str) and (
            required_event in AVATAR_ACTOR_EVENTS or
            required_event == "game_start"
        ):
            inherited_actor_kind = "avatar"
        value = walk(
            source.value,
            stable_id(source.value, f"anonymous_{source.index}"),
            source,
            inherited_actor_kind,
        )
        normalized.append(SourceObject(source.path, source.index, value))
    normalized.extend(synthetic)
    # A shared EOC may be reached from both a roll-remainder dialogue and an
    # item/creature/vehicle traversal.  The roll edge alone cannot globally
    # change that callback's actor contract; keep the concrete non-Character
    # source and let its Character-only effects fail closed.
    character_override_ids.difference_update(
        item_override_ids | creature_override_ids | vehicle_override_ids
    )
    return (
        normalized,
        frozenset(character_override_ids),
        frozenset(item_override_ids),
        frozenset(creature_override_ids),
        frozenset(vehicle_override_ids),
    )


def _node_mentions_actor(node: Any) -> bool:
    """Return whether a normalized EOC shape depends on a native actor.

    This conservative scan is used only at a persistent-task boundary.  A
    false positive produces an explicit migration TODO; a false negative
    would invoke a callback after save/load with a missing borrowed handle.
    """
    if isinstance(node, str):
        return bool(re.search(r"\b(?:u|npc)_[A-Za-z][A-Za-z0-9_]*", node))
    if isinstance(node, list):
        return any(_node_mentions_actor(entry) for entry in node)
    if not isinstance(node, dict):
        return False
    if "map_spawn_item" in node and "loc" not in node:
        return True
    for key, value in node.items():
        if key in {"alpha_talker", "beta_talker"}:
            return True
        if (
            isinstance(key, str) and key.startswith(("u_", "npc_")) and
            key not in {"npc_travel_radius", "npc_travel_filter"}
        ):
            return True
        if key in {
            "condition", "effect", "false_effect", "then", "else",
            "run_eocs", "true_eocs", "false_eocs", "weighted_list_eocs",
        } and _node_mentions_actor(value):
            return True
        if key == "math" and _node_mentions_actor(value):
            return True
        if isinstance(value, (dict, list)) and _node_mentions_actor(value):
            return True
    return False


def _condition_has_actor_prefix(value: Any, prefix: str) -> bool:
    """Recognize actor selectors nested under condition combinators."""
    non_actor_keys = {"npc_allies", "npc_allies_global"}
    if isinstance(value, str):
        return value.startswith(prefix)
    if isinstance(value, list):
        return any(_condition_has_actor_prefix(entry, prefix) for entry in value)
    if not isinstance(value, dict):
        return False
    for condition_key, condition_value in value.items():
        if (
            isinstance(condition_key, str) and
            condition_key.startswith(prefix) and
            condition_key not in non_actor_keys
        ):
            return True
        if condition_key == "math":
            parts = condition_value if isinstance(condition_value, list) else [condition_value]
            marker = prefix.rstrip("_") + "_"
            if any(
                isinstance(part, str) and re.search(
                    rf"\b{re.escape(marker)}[A-Za-z][A-Za-z0-9_]*", part
                )
                for part in parts
            ):
                return True
        elif _condition_has_actor_prefix(condition_value, prefix):
            return True
    return False


def _node_has_actor_prefix(node: Any, prefix: str) -> bool:
    """Return whether a normalized EOC shape contains one actor namespace.

    ``npc_travel_radius`` and ``npc_travel_filter`` are options on the
    avatar's dimension-travel effect; they do not introduce an NPC actor.
    The old recursive string scan also treated arbitrary variable/id values
    such as ``u_destination`` as actor evidence.  Only selector keys and
    selector-shaped strings under control-flow/effect containers are actor
    evidence, which keeps actor lifetime inference fail-closed without
    downgrading ordinary avatar EOCs to mixed-character callbacks.
    """
    if isinstance(node, str):
        return False
    if isinstance(node, list):
        return any(_node_has_actor_prefix(entry, prefix) for entry in node)
    if not isinstance(node, dict):
        return False
    actor_option_keys = {
        "npc_travel_radius", "npc_travel_filter",
        # Global NPC queries do not bind the legacy ``npc`` talker.  Treating
        # them as actor evidence turns otherwise valid mixed EOCs (for
        # example, ``npc_allies`` followed by ``u_cast_spell``) into a
        # false mixed-lifetime callback.
        "npc_allies", "npc_allies_global",
    }
    actor_containers = {
        "condition", "effect", "false_effect", "then", "else",
        "run_eocs", "true_eocs", "false_eocs", "weighted_list_eocs",
    }
    for key, value in node.items():
        if not isinstance(key, str):
            continue
        if key == "condition" and _condition_has_actor_prefix(value, prefix):
            return True
        if key.startswith(prefix) and key not in actor_option_keys:
            return True
        if key == "math":
            parts = value if isinstance(value, list) else [value]
            marker = prefix.rstrip("_") + "_"
            if any(
                isinstance(part, str) and re.search(
                    rf"\b{re.escape(marker)}[A-Za-z][A-Za-z0-9_]*", part
                )
                for part in parts
            ):
                return True
        if key not in actor_containers:
            if isinstance(value, (dict, list)) and _node_has_actor_prefix(value, prefix):
                return True
            continue
        if isinstance(value, str):
            if value.startswith(prefix):
                return True
        elif isinstance(value, list):
            if any((key in {"effect", "false_effect", "then", "else"} and
                    isinstance(entry, str) and entry.startswith(prefix)) or
                   _node_has_actor_prefix(entry, prefix) for entry in value):
                return True
        elif _node_has_actor_prefix(value, prefix):
            return True
    return False


def _node_has_item_actor(node: Any) -> bool:
    """Return whether an EOC shape requires the legacy item/talker actor.

    Item EOCs expose their variables with the ``n_`` namespace and use
    ``has_alpha``/``transform_item`` even when the enclosing item JSON is not
    part of a focused EOC-only audit.  Recognizing that closed shape locally
    keeps the migrator's generated callback equivalent without requiring every
    caller to load the entire JSON corpus just to establish provenance.
    """
    if isinstance(node, str):
        return bool(re.search(r"\bn_[A-Za-z][A-Za-z0-9_]*", node)) or node == "has_alpha"
    if isinstance(node, list):
        return any(_node_has_item_actor(entry) for entry in node)
    if not isinstance(node, dict):
        return False
    for key, value in node.items():
        if key == "has_alpha" or key == "transform_item":
            return True
        if key in {"if", "condition"} and value == "has_alpha":
            return True
        if key == "math":
            parts = value if isinstance(value, list) else [value]
            if any(
                isinstance(part, str) and
                re.search(r"\bn_[A-Za-z][A-Za-z0-9_]*", part)
                for part in parts
            ):
                return True
        if isinstance(value, (dict, list)) and _node_has_item_actor(value):
            return True
    return False


GENERIC_TALKER_TYPE_CONDITIONS = frozenset({
    "u_is_avatar", "u_is_npc", "u_is_character", "u_is_monster",
    "u_is_item", "u_is_vehicle",
})


def _node_has_generic_talker_type_condition(node: Any) -> bool:
    """Recognize conditions that intentionally introspect any talker kind."""
    if isinstance(node, str):
        return node in GENERIC_TALKER_TYPE_CONDITIONS
    if isinstance(node, list):
        return any(_node_has_generic_talker_type_condition(entry) for entry in node)
    if not isinstance(node, dict):
        return False
    return any(
        _node_has_generic_talker_type_condition(value)
        for value in node.values()
    )


def _node_contains_string(node: Any, target: str) -> bool:
    if isinstance(node, str):
        return node == target
    if isinstance(node, list):
        return any(_node_contains_string(entry, target) for entry in node)
    if isinstance(node, dict):
        return any(_node_contains_string(value, target) for value in node.values())
    return False


def _node_has_key(node: Any, target: str) -> bool:
    if isinstance(node, list):
        return any(_node_has_key(entry, target) for entry in node)
    if not isinstance(node, dict):
        return False
    return target in node or any(
        _node_has_key(value, target) for value in node.values()
    )


def _eoc_actor_requirements(
    objects: Iterable[SourceObject],
    character_override_ids: frozenset[str],
    item_override_ids: frozenset[str],
    creature_override_ids: frozenset[str],
    vehicle_override_ids: frozenset[str],
    game_start_event_emitted_by_eoc: bool = False,
) -> dict[str, str]:
    """Classify the actor lifetime required by each normalized EOC."""
    result: dict[str, str] = {}
    event_fields = event_character_actor_fields()
    for source in objects:
        if source.value.get("type") not in EOC_TYPES:
            continue
        identifier = stable_id(source.value, f"anonymous_{source.index}")
        event = native_eoc_required_event(source.value)
        if (
            source.value.get("__inline_actor_kind") == "unproven" or
            (
                event == "game_start" and
                not game_start_avatar_actor_is_proven(
                    game_start_event_emitted_by_eoc
                )
            )
        ):
            # A JSON replay can invoke a named start handler through run_eocs,
            # traversal, or a delayed task with a different alpha. Keep that
            # uncertainty explicit instead of inferring avatar from the event
            # name or an actor-shaped predicate.
            requirement = "unproven"
        elif (
            not event and source.value.get("__inline_eoc") is not True and
            _node_has_key(source.value, "u_message")
        ):
            # A named avatar-only callback cannot be made safe merely by a
            # traversal or run_eocs edge that happens to refer to it.
            requirement = "exact_avatar"
        elif (
            _node_has_key(source.value, "get_condition") or
            _node_has_key(source.value, "set_condition")
        ):
            # A stored native conditional is invoked with the dialogue at the
            # point of evaluation.  Generated closures likewise query their
            # callback actor, so any statically referenced getter needs a
            # caller that can provide a Character alpha.
            requirement = "character"
        elif identifier in item_override_ids:
            requirement = "item"
        elif identifier in creature_override_ids:
            requirement = "creature"
        elif identifier in vehicle_override_ids:
            requirement = "vehicle"
        elif source.value.get("__inline_actor_kind") == "avatar":
            requirement = "avatar"
        elif identifier in character_override_ids:
            requirement = "character"
        else:
            if isinstance(event, str) and event in AVATAR_ACTOR_EVENTS:
                requirement = "avatar"
            elif isinstance(event, str) and event in CREATURE_ACTOR_EVENTS:
                requirement = "creature"
            elif isinstance(event, str) and (
                event in PROVEN_NPC_ACTOR_EVENTS or event in event_fields
            ):
                requirement = "character"
            elif _node_mentions_actor(source.value):
                requirement = (
                    "avatar"
                    if _node_has_actor_prefix(source.value, "u_") and
                    not _node_has_actor_prefix(source.value, "npc_")
                    else "character"
                )
            else:
                requirement = "none"
        result[identifier] = requirement

    # Native reuses the current dialogue for ``test_eoc``. An unproven
    # dependency therefore overrides even a wrapper's own u_/npc_ shape;
    # other actor requirements retain the existing propagation rules.
    condition_references: dict[str, set[str]] = {}

    def collect_test_eocs(node: Any, found: set[str]) -> None:
        if isinstance(node, list):
            for entry in node:
                collect_test_eocs(entry, found)
            return
        if not isinstance(node, dict):
            return
        referenced = node.get("test_eoc")
        if isinstance(referenced, str) and referenced in result:
            found.add(referenced)
        for entry in node.values():
            collect_test_eocs(entry, found)

    for source in objects:
        if source.value.get("type") not in EOC_TYPES:
            continue
        identifier = stable_id(source.value, f"anonymous_{source.index}")
        found: set[str] = set()
        collect_test_eocs(source.value, found)
        condition_references[identifier] = found

    changed = True
    while changed:
        changed = False
        for identifier, references in condition_references.items():
            inherited = {result.get(reference, "none") for reference in references}
            if "unproven" in inherited:
                if result.get(identifier) != "unproven":
                    result[identifier] = "unproven"
                    changed = True
                continue
            if result.get(identifier) != "none":
                continue
            inherited.discard("none")
            if not inherited:
                continue
            if "item" in inherited:
                requirement = "item"
            elif "vehicle" in inherited:
                requirement = "vehicle"
            elif "creature" in inherited:
                requirement = "creature"
            elif "character" in inherited:
                requirement = "character"
            else:
                requirement = "avatar"
            result[identifier] = requirement
            changed = True
    return result


EOC_REFERENCE_FIELDS = frozenset({
    "test_eoc", "run_eocs", "true_eocs", "false_eocs",
    "weighted_list_eocs", "run_eoc_selector",
    "effect_on_conditions", "activated_eocs", "processed_eocs",
    "deactivated_eocs",
    "effect_str", "effect_on_condition", "eoc",
    "debug_cause_eoc", "debug_leave_eoc", "completion_eoc",
    "activatable_eoc", "entry_eoc", "do_turn_eoc",
    "u_run_npc_eocs", "npc_run_npc_eocs",
    "u_run_inv_eocs", "npc_run_inv_eocs",
    "u_run_monster_eocs", "npc_run_monster_eocs",
    "u_run_vehicle_eocs", "npc_run_vehicle_eocs",
    "u_run_fixed_zone_eocs", "npc_run_fixed_zone_eocs",
    "u_map_run_eocs", "npc_map_run_eocs",
    "u_map_run_item_eocs", "npc_map_run_item_eocs",
    "result_eocs", "eocs", "onhit_eocs", "ondamage_eocs",
    "onkill_eocs", "ongethit_eocs", "onmove_eocs",
    "ondodge_eocs", "onblock_eocs", "onpause_eocs",
    "consumption_effect_on_conditions",
    "failure_eocs", "death_eocs", "death_function", "caster_condition",
    "eoc_on_plant", "eoc_on_grow", "eoc_on_mature",
    "eoc_on_harvest", "eoc_on_overgrow", "eoc_on_fertilize",
    "eoc_on_water",
})


def _collect_eoc_references(
    objects: Iterable[SourceObject], known_ids: set[str],
) -> frozenset[str]:
    """Collect named EOCs reached from a loaded JSON corpus.

    Referenced EOCs are callable Lua functions, not standalone event
    handlers.  Keeping this graph in the migration pass prevents an
    untriggered nested EOC from being reported as a missing Platform event
    while preserving a real handler for delayed task callbacks.
    """
    references: set[str] = set()

    def collect(value: Any) -> None:
        if isinstance(value, str):
            if value in known_ids:
                references.add(value)
            return
        if isinstance(value, list):
            for entry in value:
                collect(entry)
            return
        if not isinstance(value, dict):
            return
        identifier = value.get("id")
        if isinstance(identifier, str) and identifier in known_ids:
            references.add(identifier)
        for entry in value.values():
            collect(entry)

    def walk(value: Any) -> None:
        if isinstance(value, dict):
            variable_name = None
            if isinstance(value.get("u_add_var"), str):
                variable_name = value["u_add_var"]
            elif isinstance(value.get("npc_add_var"), str):
                variable_name = value["npc_add_var"]
            elif "set_string_var" in value:
                target = _static_string_variable_descriptor(
                    value.get("target_var")
                )
                variable_name = target[1] if target is not None else None
            if (
                isinstance(variable_name, str) and
                "eoc" in variable_name.lower()
            ):
                collect(
                    value.get("set_string_var", value.get("value"))
                )
            for key, entry in value.items():
                if key in EOC_REFERENCE_FIELDS:
                    collect(entry)
                walk(entry)
        elif isinstance(value, list):
            for entry in value:
                walk(entry)

    for source in objects:
        walk(source.value)
    return frozenset(references)


def _has_dynamic_eoc_dispatch(objects: Iterable[SourceObject]) -> bool:
    """Fail closed when EOC dispatch does not have a fixed target set.

    Static references are collected separately.  A variable-backed EOC id can
    name any generated function, so an event EOC may also be called as a child
    with a different native actor than its event participant.  This covers
    both immediate EOC calls and interactive selectors.
    """
    def fixed_reference(value: Any) -> bool:
        if isinstance(value, str):
            return True
        if not isinstance(value, dict):
            return False
        if set(value) == {"id"} and isinstance(value.get("id"), str):
            return True
        return (
            "str" in value and set(value) <= {"str", "i18n", "//~"} and
            bounded_utf8_string(value.get("str"), 8192, allow_empty=True) and
            value.get("i18n") is not True and
            ("i18n" not in value or isinstance(value["i18n"], bool)) and
            ("//~" not in value or isinstance(value["//~"], str))
        )

    def walk(value: Any) -> bool:
        if isinstance(value, list):
            return any(walk(entry) for entry in value)
        if not isinstance(value, dict):
            return False
        for effect_key in ("run_eocs", "run_eoc_selector"):
            if effect_key not in value:
                continue
            raw = value[effect_key]
            references = [raw] if isinstance(raw, (str, dict)) else raw
            if not isinstance(references, list) or any(
                not fixed_reference(entry) for entry in references
            ):
                return True
        return any(walk(entry) for entry in value.values())

    return any(walk(source.value) for source in objects)


def _has_static_event_emission(
    objects: Iterable[SourceObject], event_name: str,
) -> bool:
    """Find any JSON-authored static trigger for a source-only event.

    This guards same-corpus EOC lowering against static re-entry.  It cannot
    observe trusted Lua that emits an event through the Platform native-event
    service, so live-actor proofs using this gate remain bounded source claims.
    """
    def walk(value: Any) -> bool:
        if isinstance(value, list):
            return any(walk(entry) for entry in value)
        if not isinstance(value, dict):
            return False
        if value.get("trigger_event") == event_name:
            return True
        return any(walk(entry) for entry in value.values())
    return any(walk(source.value) for source in objects)


def _content_callback_actor_provenance(
    objects: Iterable[SourceObject],
) -> tuple[frozenset[str], frozenset[str], frozenset[str]]:
    """Return EOCs with a proven Creature alpha and alpha/beta dialogue.

    Spell ``effect_on_condition`` and monster-attack ``eoc`` callbacks create
    their dialogue in native code.  This is stronger evidence than an EOC's
    selector spelling: the primary actor is alpha and, when a target is
    required, beta is the caster/attack target.  Propagate that lifetime
    through ordinary EOC references so inline visibility predicates keep the
    same real talkers without relying on content IDs.
    """
    materialized = list(objects)
    known_ids = {
        stable_id(source.value, f"anonymous_{source.index}")
        for source in materialized
        if source.value.get("type") in EOC_TYPES
    }

    def collect(node: Any, found: set[str]) -> None:
        if isinstance(node, str):
            if node in known_ids:
                found.add(node)
            return
        if isinstance(node, list):
            for entry in node:
                collect(entry, found)
            return
        if not isinstance(node, dict):
            return
        identifier = node.get("id")
        if isinstance(identifier, str) and identifier in known_ids:
            found.add(identifier)
        for entry in node.values():
            collect(entry, found)

    graph: dict[str, set[str]] = {}

    def collect_reference_fields(node: Any, found: set[str]) -> None:
        if isinstance(node, list):
            for entry in node:
                collect_reference_fields(entry, found)
            return
        if not isinstance(node, dict):
            return
        for key, entry in node.items():
            if key in EOC_REFERENCE_FIELDS:
                collect(entry, found)
            collect_reference_fields(entry, found)

    creature_seeds: set[str] = set()
    character_seeds: set[str] = set()
    pair_seeds: set[str] = set()
    creature_spell_targets = {"ally", "hostile", "self"}
    for source in materialized:
        value = source.value
        kind = value.get("type")
        if kind in EOC_TYPES:
            identifier = stable_id(value, f"anonymous_{source.index}")
            found: set[str] = set()
            collect_reference_fields(value, found)
            found.discard(identifier)
            graph[identifier] = found
            continue
        if kind == "monster_attack" and "eoc" in value:
            found = set()
            collect(value.get("eoc"), found)
            creature_seeds.update(found)
            if value.get("allow_no_target") is not True:
                pair_seeds.update(found)
            continue
        if kind == "talk_topic":
            found = set()
            collect_reference_fields(value, found)
            character_seeds.update(found)
            pair_seeds.update(found)
            continue
        if kind == "mission_definition":
            # Mission start/end/fail effects execute in the active mission
            # dialogue and retain the avatar/NPC alpha-beta pair.  Treat the
            # referenced EOCs like talk-topic callbacks instead of ambient
            # functions with an invented provider.
            found = set()
            for member in ("start", "end", "fail"):
                collect_reference_fields(value.get(member), found)
            character_seeds.update(found)
            pair_seeds.update(found)
            continue
        if kind == "SPELL" and value.get("effect") == "effect_on_condition":
            targets = value.get("valid_targets")
            if not (
                isinstance(targets, list) and targets and
                all(target in creature_spell_targets for target in targets)
            ):
                continue
            found = set()
            collect(value.get("effect_str"), found)
            creature_seeds.update(found)
            pair_seeds.update(found)

    def closure(seeds: set[str]) -> frozenset[str]:
        reached = set(seeds)
        pending = list(seeds)
        while pending:
            identifier = pending.pop()
            for referenced in graph.get(identifier, set()):
                if referenced in reached:
                    continue
                reached.add(referenced)
                pending.append(referenced)
        return frozenset(reached)

    return (
        closure(creature_seeds), closure(character_seeds), closure(pair_seeds)
    )


def _npc_dialogue_mission_pair_provenance(
    objects: Iterable[SourceObject],
) -> frozenset[str]:
    """Prove direct talk-topic callbacks have native dialogue mission state.

    Generic alpha/beta provenance includes spell and monster callbacks, and
    EOC reference closure can cross delayed or actor-rebinding edges.  Only
    direct ``true_eocs``/``false_eocs`` callbacks from talk topics qualify;
    every known alternate call site and independent trigger removes that
    proof.
    """
    materialized = list(objects)
    known_ids = {
        stable_id(source.value, f"anonymous_{source.index}")
        for source in materialized
        if source.value.get("type") in EOC_TYPES
    }
    talk_topic_seeds: set[str] = set()
    other_source_references: set[str] = set()
    independent_eoc_triggers = {
        "required_event", "eoc_type", "recurrence", "global"
    }
    unsafe_topic_edges = {
        "delay", "time_in_future", "actor", "actor_override",
        "alpha", "beta", "speaker", "interlocutor",
        "run_eocs", "u_run_npc_eocs", "npc_run_npc_eocs",
    }
    unsafe_topic_references: set[str] = set()

    def collect_topic_callbacks(
        source: SourceObject, node: Any, unsafe: bool = False,
    ) -> None:
        if isinstance(node, list):
            for entry in node:
                collect_topic_callbacks(source, entry, unsafe)
            return
        if not isinstance(node, dict):
            return
        unsafe = unsafe or bool(unsafe_topic_edges.intersection(node))
        for key, entry in node.items():
            if key in EOC_REFERENCE_FIELDS:
                references = _collect_eoc_references(
                    [SourceObject(source.path, source.index, {key: entry})],
                    known_ids,
                )
                if (
                    key in {"true_eocs", "false_eocs"} and not unsafe
                ):
                    talk_topic_seeds.update(references)
                else:
                    unsafe_topic_references.update(references)
            else:
                collect_topic_callbacks(source, entry, unsafe)

    for source in materialized:
        kind = source.value.get("type")
        references = set(_collect_eoc_references([source], known_ids))
        if kind in EOC_TYPES:
            identifier = stable_id(source.value, f"anonymous_{source.index}")
            other_source_references.update(references - {identifier})
            if any(key in source.value for key in independent_eoc_triggers):
                other_source_references.add(identifier)
        elif kind == "talk_topic":
            collect_topic_callbacks(source, source.value)
        else:
            other_source_references.update(references)

    # Do not propagate through EOC-to-EOC edges: the nested callback may be
    # delayed, rebinding actors, or invoked by another non-dialogue caller.
    other_source_references.update(unsafe_topic_references)
    return frozenset(talk_topic_seeds - other_source_references)


@dataclass(frozen=True)
class SourceObject:
    path: Path
    index: int
    value: dict[str, Any]

    @property
    def location(self) -> str:
        return f"{self.path.as_posix()}#{self.index}"


@dataclass(frozen=True)
class ItemUseActionPlan:
    eoc_id: str | None
    todo_category: TodoCategory | None = None
    todo_message: str | None = None
    handler_id: str | None = None
    menu_text: str | None = None
    message: str | None = None
    message_type: str | None = None

    @property
    def migrated(self) -> bool:
        return self.handler_id is not None


def _item_use_comments(value: dict[str, Any]) -> set[str]:
    return {
        key for key in value
        if isinstance(key, str) and key.startswith("//")
    }


def _item_use_has_other_eoc_reference(
    objects: list[SourceObject], eoc_id: str, owner: SourceObject,
) -> bool:
    other_sources = [
        source for source in objects
        if (source.path, source.index) != (owner.path, owner.index) and not (
            source.value.get("type") in EOC_TYPES and
            source.value.get("__inline_eoc") is True and
            stable_id(source.value, f"anonymous_{source.index}") == eoc_id
        )
    ]
    # The owner can also reference the inline EOC outside its use action.
    # Exclude only the attachment being classified, not the whole item.
    owner_without_attachment = {
        key: value for key, value in owner.value.items() if key != "use_action"
    }
    action = owner.value.get("use_action")
    if isinstance(action, dict):
        remaining_action = {
            key: value for key, value in action.items()
            if key != "effect_on_conditions"
        }
        if remaining_action:
            owner_without_attachment["use_action"] = remaining_action
    other_sources.append(
        SourceObject(owner.path, owner.index, owner_without_attachment)
    )
    return eoc_id in _collect_eoc_references(other_sources, {eoc_id})


def _location_variable_target_params(value: Any) -> list[Any]:
    if isinstance(value, list):
        return [
            target
            for entry in value
            for target in _location_variable_target_params(entry)
        ]
    if not isinstance(value, dict):
        return []
    targets = []
    if "u_location_variable" in value or "npc_location_variable" in value:
        targets.append(value.get("target_params"))
    targets.extend(
        target
        for entry in value.values()
        for target in _location_variable_target_params(entry)
    )
    return targets


def classify_item_use_actions(
    objects: list[SourceObject],
    eoc_definition_counts: Counter[str],
) -> dict[tuple[Path, int], ItemUseActionPlan]:
    """Classify only source-proven direct item EOCs for typed item callbacks."""
    inline_eocs = {
        stable_id(source.value, f"anonymous_{source.index}"): source
        for source in objects
        if source.value.get("type") in EOC_TYPES and
        source.value.get("__inline_eoc") is True
    }
    item_id_counts = Counter(
        source.value.get("id") for source in objects
        if source.value.get("type") in ITEM_TYPES and
        isinstance(source.value.get("id"), str)
    )
    plans: dict[tuple[Path, int], ItemUseActionPlan] = {}

    def unsupported(
        source: SourceObject, item_id: str, eoc_id: str | None,
        reason: str,
        category: TodoCategory = "manual_rewrite",
    ) -> ItemUseActionPlan:
        return ItemUseActionPlan(
            eoc_id,
            category,
            f"{source.location}: item {item_id} use_action needs manual review: {reason}",
        )

    for source in objects:
        value = source.value
        if value.get("type") not in ITEM_TYPES or "use_action" not in value:
            continue
        item_id = stable_id(value, f"todo_item_{source.index}")
        action = value.get("use_action")
        action_fields = (
            set(action) - _item_use_comments(action)
            if isinstance(action, dict) else set()
        )
        eoc_ids = (
            action.get("effect_on_conditions")
            if isinstance(action, dict) else None
        )
        eoc_id = (
            eoc_ids[0] if isinstance(eoc_ids, list) and len(eoc_ids) == 1 and
            isinstance(eoc_ids[0], str) else None
        )
        if not isinstance(action, dict) or action.get("type") != "effect_on_conditions":
            plan = unsupported(
                source, item_id, None,
                "this batch only covers effect_on_conditions use actions",
            )
        elif eoc_id is None or eoc_id not in inline_eocs:
            plan = unsupported(
                source, item_id, None,
                "the action must own exactly one inline EOC definition; named/reused EOCs stay ordinary manual rewrites",
            )
        else:
            eoc = inline_eocs[eoc_id].value
            effect = eoc.get("effect")
            eoc_keys = _nested_object_keys(eoc)
            route_keys = {"u_location_variable", "reveal_map", "reveal_route"} & eoc_keys
            has_condition_or_false_branch = (
                "condition" in eoc or "false_effect" in eoc
            )
            if route_keys and has_condition_or_false_branch:
                flow_keys = sorted(eoc_keys & (route_keys | {"u_message"}))
                target_params = _location_variable_target_params(eoc.get("effect"))
                omits_origin_npc = bool(target_params) and all(
                    isinstance(params, dict) and "origin_npc" not in params
                    for params in target_params
                )
                condition_flow = sorted(
                    _nested_object_keys(eoc.get("condition"))
                )
                origin_note = (
                    f"Every location-variable target_params entry ({len(target_params)}) "
                    "omits origin_npc, so "
                    "parse_mission_om_target leaves origin_u enabled and "
                    "mission_util::get_om_terrain_pos searches from the player Avatar "
                    "while EOC alpha remains the actual using Character. "
                    if omits_origin_npc else
                    "The target origin and fallback still need source-specific review "
                    "against mission_util::get_om_terrain_pos while EOC alpha remains "
                    "the actual using Character. "
                )
                plan = unsupported(
                    source, item_id, eoc_id,
                    f"inline EOC {eoc_id} branches through conditions/false_effect and "
                    f"uses {', '.join(flow_keys)} "
                    f"with condition fields {', '.join(condition_flow)}. "
                    "Native alpha is the actual using Character (possibly an NPC) and beta is this item. "
                    "A null Character still executes the native EOC, while Platform ItemUseContext fails closed before Lua. "
                    "For non-null calls the typed callback preserves the actual Character and exact item. " + origin_note +
                    "The migration still lacks ordered context writes, search-miss status/debug behavior, and distant-map loading. "
                    "Keep this as a platform_gap TODO; do not replace alpha with services.characters.avatar().",
                    "platform_gap",
                )
            else:
                descriptor_fields = set(eoc) - _item_use_comments(eoc)
                effect_fields = set(effect) - _item_use_comments(effect) if isinstance(effect, dict) else set()
                message = effect.get("u_message") if isinstance(effect, dict) else None
                message_type = effect.get("type") if isinstance(effect, dict) else None
                valid_message = (
                    bounded_utf8_string(message, 512) and bool(message.strip()) and
                    not any(character in message for character in ("%", "<", ">", "\0"))
                )
                menu_text = action.get("menu_text")
                raw_id = value.get("id")
                handler_id = (
                    f"migrated.item_use.{raw_id}"
                    if isinstance(raw_id, str) else ""
                )
                valid_label = (
                    isinstance(menu_text, str) and
                    bounded_utf8_string(menu_text, 256) and bool(menu_text.strip())
                )
                simple_message = (
                    value.get("type") in {"ITEM", "GENERIC"} and
                    isinstance(raw_id, str) and bounded_platform_id(raw_id) and
                    item_id_counts[raw_id] == 1 and
                    bounded_utf8_string(handler_id, PLATFORM_ID_MAX_BYTES) and
                    "copy-from" not in value and "abstract" not in value and
                    "comestible" not in value and
                    action_fields == {"type", "menu_text", "effect_on_conditions"} and
                    valid_label and
                    descriptor_fields <= {
                        "type", "id", "effect", "eoc_type", "__inline_eoc", "__inline_actor_kind",
                    } and
                    eoc.get("__inline_actor_kind") == "item" and
                    eoc.get("__inline_eoc") is True and
                    eoc.get("eoc_type", "ACTIVATION") == "ACTIVATION" and
                    "condition" not in eoc and "false_effect" not in eoc and
                    eoc_definition_counts.get(eoc_id, 0) == 1 and
                    isinstance(effect, dict) and
                    effect_fields in ({"u_message"}, {"u_message", "type"}) and
                    valid_message and message_type in {
                        None, "neutral", "good", "bad", "mixed", "warning", "info",
                        "debug", "headshot", "critical", "grazing",
                    }
                )
                if simple_message:
                    plan = ItemUseActionPlan(
                        eoc_id=eoc_id,
                        handler_id=handler_id,
                        menu_text=menu_text,
                        message=message,
                        message_type=message_type or "neutral",
                    )
                else:
                    plan = unsupported(
                        source, item_id, eoc_id,
                        f"inline EOC {eoc_id} needs manual review; this batch does not migrate non-message or branched item actions",
                    )
        plans[(source.path, source.index)] = plan
    return plans


def _nested_object_keys(value: Any) -> set[str]:
    if isinstance(value, list):
        return set().union(*(_nested_object_keys(entry) for entry in value)) if value else set()
    if isinstance(value, dict):
        result = {key for key in value if isinstance(key, str)}
        for entry in value.values():
            result.update(_nested_object_keys(entry))
        return result
    return set()


@dataclass(frozen=True)
class LuaRaw:
    """A deliberately bounded Lua expression emitted by the migrator.

    JSON literals are rendered through ``_lua_literal``.  A small number of
    Platform descriptors also need callbacks; keeping callback source in an
    explicit wrapper prevents arbitrary legacy JSON strings from becoming Lua
    code.
    """

    source: str


@dataclass
class MigrationResult:
    files: dict[Path, str] = field(default_factory=dict)
    converted: list[str] = field(default_factory=list)
    partial: list[str] = field(default_factory=list)
    todos: list[MigrationTodo] = field(default_factory=list)
    boundaries: list[MigrationBoundary] = field(default_factory=list)

    def __post_init__(self) -> None:
        if any(not isinstance(todo, MigrationTodo) for todo in self.todos):
            raise TypeError("migration result TODOs must be MigrationTodo records")
        if any(
            not isinstance(boundary, MigrationBoundary)
            for boundary in self.boundaries
        ):
            raise TypeError(
                "migration result boundaries must be MigrationBoundary records"
            )

    def add_todo(self, category: TodoCategory, rendered: str) -> None:
        """Append one explicitly classified TODO from legacy report text.

        ``rendered`` remains accepted at the producer boundary so the large
        family of existing renderers can keep their precise source wording.
        Classification is required by the caller and is never inferred from
        that wording.
        """
        validate_todo_category(category)
        self.todos.append(MigrationTodo.from_rendered(category, rendered))


def render_mod_definition(
    source: SourceObject, result: MigrationResult, mod_id: str
) -> str:
    value = source.value
    complete = True
    raw_id = value.get("id")
    if (
        not safe_platform_id(raw_id) or
        len(raw_id.encode("utf-8")) > 256 or
        raw_id != mod_id
    ):
        complete = False
        result.add_todo(
            "semantic_choice",
            f"{source.location}: MOD_INFO id {raw_id!r} does not match the resolved Platform id {mod_id!r}"
        )

    lines = [
        'local ccb = require("ccb")',
        "",
        "return ccb.ModDefinition {",
        f"    id = {lua_quote(mod_id)},",
    ]

    if "name" in value:
        name = value["name"]
        if (
            isinstance(name, str) and
            0 < len(name.encode("utf-8")) <= 512 and
            "\0" not in name
        ):
            lines.append(f"    name = {lua_quote(name)},")
        else:
            complete = False
            result.add_todo(
                "semantic_choice",
                f"{source.location}: MOD_INFO name needs a bounded plain-string conversion"
            )
    else:
        complete = False
        result.add_todo(
            "semantic_choice",
            f"{source.location}: MOD_INFO without a plain name has different legacy fallback presentation"
        )

    if "version" in value:
        version = value["version"]
        if (
            isinstance(version, str) and
            0 < len(version.encode("utf-8")) <= 128 and
            "\0" not in version
        ):
            lines.append(f"    version = {lua_quote(version)},")
        else:
            complete = False
            result.add_todo(
                "semantic_choice",
                f"{source.location}: MOD_INFO version needs a bounded string conversion"
            )

    if "dependencies" in value:
        dependencies = value["dependencies"]
        valid_dependencies = (
            isinstance(dependencies, list) and
            len(dependencies) <= 256 and
            all(
                safe_platform_id(dependency) and
                len(dependency.encode("utf-8")) <= 256
                for dependency in dependencies
            ) and
            len(set(dependencies)) == len(dependencies) and
            mod_id not in dependencies
        )
        if valid_dependencies:
            rendered = ", ".join(lua_quote(value) for value in dependencies)
            lines.append(f"    dependencies = {{ {rendered} }},")
        else:
            complete = False
            result.add_todo(
                "semantic_choice",
                f"{source.location}: MOD_INFO dependencies need a unique bounded string-array conversion"
            )

    if "core" in value:
        core = value["core"]
        if isinstance(core, bool):
            lines.append(f"    core = {'true' if core else 'false'},")
        else:
            complete = False
            result.add_todo(
                "semantic_choice",
                f"{source.location}: MOD_INFO core must be a boolean"
            )

    unresolved = sorted(
        set(value) - {"type", "id", "name", "version", "dependencies", "core"}
    )
    if unresolved:
        complete = False
        result.add_todo(
            "semantic_choice",
            f"{source.location}: MOD_INFO unresolved fields: {', '.join(unresolved)}"
        )

    label = f"{source.location}: MOD_INFO {raw_id or '<invalid id>'}"
    if complete:
        result.converted.append(label)
    else:
        result.partial.append(label)
    lines.extend(("}", ""))
    return "\n".join(lines)


def iter_json_files(inputs: Iterable[Path]) -> list[Path]:
    files: set[Path] = set()
    ignored_directories = {".git", ".gradle", "build", "obj-lua"}
    for requested in inputs:
        path = requested.resolve()
        if path.is_dir():
            for directory, children, names in os.walk(path, followlinks=False):
                children[:] = sorted(
                    child
                    for child in children
                    if child not in ignored_directories
                )
                base = Path(directory)
                files.update(
                    base / name for name in names if name.endswith(".json")
                )
        elif path.is_file():
            files.add(path)
        else:
            raise ValueError(f"input does not exist: {requested}")
    return sorted(files)


def load_objects(inputs: Iterable[Path]) -> list[SourceObject]:
    objects: list[SourceObject] = []
    for path in iter_json_files(inputs):
        try:
            document = json.loads(
                strip_trailing_commas(
                    strip_jsonc_comments(path.read_text(encoding="utf-8"))
                )
            )
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise ValueError(f"cannot read {path}: {error}") from error
        values = document if isinstance(document, list) else [document]
        for index, value in enumerate(values):
            if not isinstance(value, dict):
                raise ValueError(f"{path}#{index} is not an object")
            objects.append(SourceObject(path, index, value))
    return objects


@functools.lru_cache(maxsize=1)
def core_mutation_catalog_ids() -> tuple[frozenset[str], frozenset[str]]:
    """Read direct, concrete core mutation/category IDs from source data."""
    source_root = REPOSITORY_ROOT / "data" / "json" / "mutations"
    try:
        objects = load_objects([source_root])
    except ValueError:
        # A missing or unreadable source catalog proves no IDs; callers then
        # leave every mutation selector as a migration TODO.
        return frozenset(), frozenset()
    mutation_ids: set[str] = set()
    category_ids: set[str] = set()
    deleted_mutation_ids: set[str] = set()
    deleted_category_ids: set[str] = set()
    for source in objects:
        value = source.value
        kind = value.get("type")
        identifier = value.get("id")
        if (
            kind not in {"mutation", "mutation_category"} or
            not safe_platform_id(identifier)
        ):
            continue
        if "delete" in value:
            if kind == "mutation":
                deleted_mutation_ids.add(identifier)
            else:
                deleted_category_ids.add(identifier)
            continue
        if (
            "abstract" in value or
            any(key in value for key in ("copy-from", "extend"))
        ):
            continue
        if kind == "mutation":
            mutation_ids.add(identifier)
        else:
            category_ids.add(identifier)
    return (
        frozenset(mutation_ids - deleted_mutation_ids),
        frozenset(category_ids - deleted_category_ids),
    )


@functools.lru_cache(maxsize=1)
def core_body_part_catalog_ids() -> frozenset[str]:
    """Read concrete core body-part IDs used by native wound effects."""
    source_paths = [
        REPOSITORY_ROOT / "data" / "json" / "body_parts.json",
        REPOSITORY_ROOT / "data" / "json" / "mutations",
    ]
    try:
        objects = load_objects(source_paths)
    except ValueError:
        return frozenset()
    identifiers = {
        source.value["id"] for source in objects
        if source.value.get("type") == "body_part" and
        isinstance(source.value.get("id"), str) and
        safe_platform_id(source.value["id"]) and
        source.value.get("abstract") is not True and
        "copy-from" not in source.value
    }
    return frozenset(identifiers)


def _morale_type_catalog_parts(
    objects: Iterable[SourceObject],
) -> tuple[frozenset[str], frozenset[str]]:
    identifiers: set[str] = set()
    deleted: set[str] = set()
    for source in objects:
        value = source.value
        identifier = value.get("id")
        if value.get("type") != "morale_type" or not safe_platform_id(identifier):
            continue
        if "delete" in value:
            deleted.add(identifier)
        elif "abstract" not in value:
            identifiers.add(identifier)
    return frozenset(identifiers), frozenset(deleted)


@functools.lru_cache(maxsize=1)
def core_morale_type_catalog_ids() -> frozenset[str]:
    """Read core registered morale IDs from the known core definition files."""
    source_paths = (
        REPOSITORY_ROOT / "data" / "json" / "morale_types.json",
        REPOSITORY_ROOT / "data" / "json" / "effects_on_condition" /
        "misc_effect_on_condition.json",
        REPOSITORY_ROOT / "data" / "json" / "effects_on_condition" /
        "nether_eocs" / "vitrification_effect_on_condition.json",
    )
    try:
        objects = load_objects(source_paths)
    except ValueError:
        return frozenset()
    identifiers, deleted = _morale_type_catalog_parts(objects)
    return frozenset(identifiers - deleted)


def known_morale_type_catalog_ids(
    objects: Iterable[SourceObject],
) -> frozenset[str]:
    """Combine core and loaded morale types, honoring source deletions."""
    source_ids, deleted = _morale_type_catalog_parts(objects)
    return frozenset(
        (core_morale_type_catalog_ids() | source_ids) - deleted
    )


def source_recipe_catalog_ids(objects: Iterable[SourceObject]) -> frozenset[str]:
    """Collect only directly identifiable recipe IDs from loaded JSON sources."""
    identifiers: set[str] = set()
    for source in objects:
        value = source.value
        kind = value.get("type")
        if (
            kind not in {"recipe", "practice"} or
            value.get("abstract") is True or
            "abstract" in value or "copy-from" in value or "extend" in value or
            value.get("obsolete") is True
        ):
            continue
        if kind == "practice":
            identifier = value.get("id")
        else:
            # Native recipe::load appends variant/id_suffix to the result ID;
            # keep these shapes out until that exact construction is modeled.
            if "variant" in value or "id_suffix" in value:
                continue
            identifier = value.get("result")
        if safe_native_recipe_id(identifier):
            identifiers.add(identifier)
    return frozenset(identifiers)


@functools.lru_cache(maxsize=1)
def core_recipe_catalog_ids() -> frozenset[str]:
    """Read concrete core recipe IDs for registry-checked EOC selectors."""
    source_root = REPOSITORY_ROOT / "data" / "json" / "recipes"
    try:
        objects = load_objects([source_root])
    except ValueError:
        return frozenset()
    return source_recipe_catalog_ids(objects)


def source_wound_catalog_ids(objects: Iterable[SourceObject]) -> frozenset[str]:
    """Accept only self-contained wound definitions from the input corpus."""
    required = {"name", "description", "damage_types", "damage_required"}
    identifiers: set[str] = set()
    for source in objects:
        value = source.value
        identifier = value.get("id")
        name = display_text(value.get("name"))
        description = display_text(value.get("description"))
        damage_types = string_ids(value.get("damage_types"))
        damage_required = value.get("damage_required")
        if (
            value.get("type") == "wound" and
            bounded_platform_id(identifier) and
            value.get("abstract") is not True and "copy-from" not in value and
            required <= value.keys() and
            bounded_utf8_string(name, WOUND_NAME_MAX_BYTES) and
            bounded_utf8_string(description, WOUND_DESCRIPTION_MAX_BYTES) and
            damage_types and
            all(bounded_platform_id(damage_type) for damage_type in damage_types) and
            len(set(damage_types)) == len(damage_types) and
            isinstance(damage_required, list) and len(damage_required) == 2 and
            (minimum := native_integer(damage_required[0])) is not None and
            (maximum := native_integer(damage_required[1])) is not None and
            maximum >= minimum
        ):
            identifiers.add(identifier)
    return frozenset(identifiers)


def render_materials(
    lines: list[str], raw: Any,
    add_todo: Callable[[TodoCategory, str], None],
    location: str,
) -> None:
    values = raw if isinstance(raw, list) else [raw]
    for entry in values:
        if isinstance(entry, str) and entry:
            lines.append(f"definition:material({lua_quote(entry)}, 1)")
        elif (
            isinstance(entry, list) and
            len(entry) == 2 and
            isinstance(entry[0], str) and
            bool(entry[0]) and
            isinstance(entry[1], int) and
            not isinstance(entry[1], bool) and
            entry[1] > 0 and
            entry[1] <= NATIVE_INT_MAX
        ):
            lines.append(f"definition:material({lua_quote(entry[0])}, {entry[1]})")
        else:
            add_todo(
                "manual_rewrite",
                f"{location}: item material entry needs manual conversion",
            )


def render_pairs(
    lines: list[str], raw: Any, method: str,
    add_todo: Callable[[TodoCategory, str], None],
    location: str,
) -> None:
    if not isinstance(raw, list):
        add_todo(
            "manual_rewrite", f"{location}: {method} must be reviewed manually"
        )
        return
    for entry in raw:
        if (
            isinstance(entry, list) and
            len(entry) >= 2 and
            isinstance(entry[0], str) and
            bool(entry[0]) and
            isinstance(entry[1], int) and
            not isinstance(entry[1], bool) and
            0 < entry[1] <= NATIVE_INT_MAX
        ):
            lines.append(f"definition:{method}({lua_quote(entry[0])}, {entry[1]})")
        else:
            add_todo(
                "manual_rewrite",
                f"{location}: malformed {method} entry needs manual conversion",
            )


def render_item(
    source: SourceObject,
    result: MigrationResult,
    item_use_plan: ItemUseActionPlan | None = None,
) -> str | None:
    value = source.value
    item_id = stable_id(value, f"todo_item_{source.index}")
    if not isinstance(value.get("id"), str) or not value["id"]:
        result.partial.append(f"{source.location}: item {item_id}")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: item {item_id} has no concrete stable id"
        )
        if "copy-from" in value or "abstract" in value:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: item {item_id} inheritance must become a Lua constructor/composition function"
            )
        return None
    if not safe_platform_id(value["id"]):
        result.partial.append(f"{source.location}: item {item_id}")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: item {item_id} is not a safe native Platform id"
        )
        return None
    todo_count = len(result.todos)
    item_kind = value.get("type")
    forced_partial = False
    if item_kind not in {"ITEM", "GENERIC"}:
        # The typed Item builder exists, but this subtype needs an explicit
        # content-owner decision about whether a new authoring registrar is
        # warranted; it is not a Platform backlog input by itself.
        result.add_todo(
            "semantic_choice",
            f"{source.location}: item {item_id} keeps only shared fields; "
            f"the {item_kind} subtype needs a native Platform registrar"
        )
        forced_partial = True
    if "copy-from" in value or "abstract" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: item {item_id} inheritance must become a Lua constructor/composition function"
        )
        forced_partial = True
        if "id" not in value:
            return None
    name = display_text(value.get("name"), item_id)
    description = display_text(value.get("description"), "")
    symbol = value.get("symbol") if isinstance(value.get("symbol"), str) else "?"
    if not name:
        name = item_id
        result.add_todo(
            "semantic_choice",
            f"{source.location}: item {item_id} name cannot be empty"
        )
    if not symbol:
        symbol = "?"
        result.add_todo(
            "semantic_choice",
            f"{source.location}: item {item_id} symbol cannot be empty"
        )
    for field_name in ("name", "description"):
        raw_text = value.get(field_name)
        if isinstance(raw_text, dict) and (
            set(raw_text) != {"str"} or not isinstance(raw_text.get("str"), str)
        ):
            result.add_todo(
                "semantic_choice",
                f"{source.location}: item {item_id} {field_name} translation metadata needs review"
            )
        elif field_name in value and not isinstance(raw_text, (str, dict)):
            result.add_todo(
                "semantic_choice",
                f"{source.location}: item {item_id} {field_name} needs review"
            )
    if "symbol" in value and not isinstance(value["symbol"], str):
        result.add_todo(
            "semantic_choice",
            f"{source.location}: item {item_id} symbol needs review"
        )
    lines = [
        "local definition = content.Item {",
        f"    id = {lua_quote(item_id)},",
        f"    name = {lua_quote(name)},",
        f"    description = {lua_quote(description)},",
        f"    symbol = {lua_quote(symbol)},",
        "}",
    ]
    weight = parse_integral_unit(value.get("weight"), {"mg": 0.001, "g": 1, "kg": 1000})
    if "weight" in value:
        if weight is None or not 0 <= weight <= NATIVE_MASS_GRAMS_MAX:
            result.add_todo("semantic_choice", f"{source.location}: item {item_id} weight needs unit review")
        else:
            lines.append(f"definition:mass_grams({weight})")
    volume = parse_integral_unit(value.get("volume"), {"ml": 1, "l": 1000})
    if "volume" in value:
        if volume is None or not 0 <= volume <= NATIVE_INT_MAX:
            result.add_todo("semantic_choice", f"{source.location}: item {item_id} volume needs unit review")
        else:
            lines.append(f"definition:volume_ml({volume})")
    price = value.get("price")
    if (
        isinstance(price, int) and
        not isinstance(price, bool) and
        0 <= price <= NATIVE_INT_MAX
    ):
        lines.append(f"definition:price_cents({price})")
    elif "price" in value:
        result.add_todo("semantic_choice", f"{source.location}: item {item_id} price needs unit review")
    if "material" in value:
        render_materials(lines, value["material"], result.add_todo, source.location)
    if "qualities" in value:
        render_pairs(lines, value["qualities"], "quality", result.add_todo, source.location)
    flags = value.get("flags", [])
    if isinstance(flags, list) and all(
        isinstance(entry, str) and bool(entry) for entry in flags
    ):
        for flag_name in flags:
            lines.append(f"definition:flag({lua_quote(flag_name)})")
    elif "flags" in value:
        result.add_todo("manual_rewrite", f"{source.location}: item {item_id} flags need manual conversion")
    if "use_action" in value:
        if item_use_plan is None:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: item {item_id} use_action is outside the bounded typed item-use migration pass",
            )
        elif item_use_plan.migrated:
            lines.append(
                f"definition:on_use({lua_quote(item_use_plan.handler_id)}, "
                f"content.text({lua_quote(item_use_plan.menu_text)}))"
            )
        else:
            result.add_todo(
                item_use_plan.todo_category,
                item_use_plan.todo_message,
            )
    unresolved = sorted(set(value) - COMMON_ITEM_FIELDS)
    if unresolved or forced_partial or len(result.todos) != todo_count:
        result.partial.append(f"{source.location}: item {item_id}")
        if unresolved:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: item {item_id} unresolved fields: {', '.join(unresolved)}"
            )
    else:
        result.converted.append(f"{source.location}: item {item_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


def render_item_use_handler(plan: ItemUseActionPlan) -> str:
    """Render the bounded literal-message item callback after native early returns."""
    if (
        not plan.migrated or plan.handler_id is None or
        plan.message is None or plan.message_type is None
    ):
        raise ValueError("item-use callback plan is incomplete")
    return "\n".join((
        f"runtime.handler({lua_quote(plan.handler_id)}, function(context)",
        "    local actor = context.character",
        '    if actor == nil or actor.subtype == "npc" then',
        "        return 0",
        "    end",
        "    context:message(",
        f"        services.translate({lua_quote(plan.message)}),",
        f"        {lua_quote(plan.message_type)})",
        "    return 0",
        "end)",
        "",
    ))


def requirement_choices(raw: Any, *, tools: bool = False) -> list[tuple[str, int]] | None:
    if not isinstance(raw, list):
        return None
    result: list[tuple[str, int]] = []
    for entry in raw:
        if (
            not isinstance(entry, list) or
            len(entry) < 2 or
            not isinstance(entry[0], str) or
            not entry[0] or
            not isinstance(entry[1], int) or
            isinstance(entry[1], bool) or
            entry[1] == 0 or
            abs(entry[1]) > NATIVE_INT_MAX or
            (entry[1] < 0 and not tools)
        ):
            return None
        result.append((entry[0], entry[1]))
    return result or None


def render_requirement_groups(
    lines: list[str], raw: Any, singular: str, alternatives: str,
    add_todo: Callable[[TodoCategory, str], None], location: str,
    *, tools: bool = False, owner: str = "recipe"
) -> None:
    if not isinstance(raw, list):
        add_todo(
            "manual_rewrite",
            f"{location}: {owner} {singular} requirements need manual conversion",
        )
        return
    for group in raw:
        choices = requirement_choices(group, tools=tools)
        if choices is None:
            add_todo(
                "manual_rewrite",
                f"{location}: {owner} {singular} group needs manual conversion",
            )
        elif len(choices) == 1:
            item_id, count = choices[0]
            if tools and count > 0:
                lines.append(f"definition:tool_charges({lua_quote(item_id)}, {count})")
            else:
                lines.append(
                    f"definition:{singular}({lua_quote(item_id)}, {abs(count)})"
                )
        else:
            rendered = ", ".join(
                (
                    f"{{ id = {lua_quote(item_id)}, charges = {count} }}"
                    if tools and count > 0
                    else f"{{ id = {lua_quote(item_id)}, count = {abs(count)} }}"
                )
                for item_id, count in choices
            )
            lines.append(f"definition:{alternatives} {{ {rendered} }}")


def render_recipe(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    recipe_id = stable_id(value, f"todo_recipe_{source.index}")
    todo_count = len(result.todos)
    forced_partial = False
    if "copy-from" in value or "abstract" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} inheritance must become a Lua constructor/composition function"
        )
        forced_partial = True
    product = value.get("result")
    if not safe_platform_id(product):
        result.add_todo("manual_rewrite", f"{source.location}: recipe {recipe_id} has no stable result")
        result.partial.append(f"{source.location}: recipe {recipe_id}")
        return None
    if not safe_platform_id(recipe_id):
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} is not a safe native Platform id"
        )
        result.partial.append(f"{source.location}: recipe {recipe_id}")
        return None
    if value.get("type") == "uncraft":
        # The native disassembly path is bounded; whether this recipe should
        # use that interpretation remains a content-owner choice.
        result.add_todo(
            "semantic_choice",
            f"{source.location}: uncraft {recipe_id} native disassembly registration is bounded"
        )
    category = value.get("category", "CC_MISC")
    subcategory = value.get("subcategory", "CSC_MISC")
    if (
        not isinstance(category, str) or
        not category or
        not isinstance(subcategory, str) or
        not subcategory
    ):
        result.add_todo(
            "semantic_choice",
            f"{source.location}: recipe {recipe_id} category ids need review"
        )
        category = "CC_MISC"
        subcategory = "CSC_MISC"
    lines = [
        "local definition = content.Recipe {",
        f"    id = {lua_quote(recipe_id)},",
        f"    result = {lua_quote(product)},",
        f"    category = {lua_quote(category)},",
        f"    subcategory = {lua_quote(subcategory)},",
    ]
    if value.get("type") == "practice":
        lines.append("    practice = true,")
        for member in ("practice_data", "book_learn", "proficiencies"):
            if member in value:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: practice {recipe_id} {member} needs review"
                )
    elif value.get("type") == "uncraft":
        lines.append("    uncraft = true,")
    skill = value.get("skill_used")
    if isinstance(skill, str) and skill:
        lines.append(f"    skill = {lua_quote(skill)},")
    elif "skill_used" in value and skill not in (None, ""):
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} primary skill needs review"
        )
    difficulty = value.get("difficulty", 0)
    if (
        isinstance(difficulty, int) and
        not isinstance(difficulty, bool) and
        0 <= difficulty <= NATIVE_MAX_SKILL
    ):
        lines.append(f"    difficulty = {difficulty},")
    else:
        lines.append("    difficulty = 0,")
        result.add_todo("manual_rewrite", f"{source.location}: recipe {recipe_id} difficulty needs review")
    duration = parse_moves(value.get("time", 100))
    if duration is None or not 0 < duration <= NATIVE_INT64_MAX:
        duration = 100
        result.add_todo("manual_rewrite", f"{source.location}: recipe {recipe_id} time needs unit review")
    lines.append(f"    duration_moves = {duration},")
    autolearn = value.get("autolearn", True)
    if isinstance(autolearn, bool):
        lines.append(f"    autolearn = {'true' if autolearn else 'false'},")
    else:
        lines.append("    autolearn = false,")
        result.add_todo("manual_rewrite", f"{source.location}: recipe {recipe_id} conditional autolearn needs Lua logic")
    reversible = value.get("reversible", False)
    if not isinstance(reversible, bool):
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} reversible flag needs review"
        )
        reversible = False
    lines.extend((f"    reversible = {'true' if reversible else 'false'},", "}"))
    render_requirement_groups(
        lines, value.get("components", []), "component", "component_any",
        result.add_todo, source.location
    )
    render_requirement_groups(
        lines, value.get("tools", []), "tool", "tool_any",
        result.add_todo, source.location, tools=True
    )
    skills = value.get("skills_required", [])
    if isinstance(skills, list):
        for entry in skills:
            if (
                isinstance(entry, list) and
                len(entry) >= 2 and
                isinstance(entry[0], str) and
                bool(entry[0]) and
                isinstance(entry[1], int) and
                not isinstance(entry[1], bool) and
                0 <= entry[1] <= NATIVE_MAX_SKILL
            ):
                lines.append(f"definition:requires_skill({lua_quote(entry[0])}, {entry[1]})")
            else:
                result.add_todo("manual_rewrite", f"{source.location}: recipe {recipe_id} required skill needs review")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} required skills need review"
        )
    external = value.get("using", [])
    if isinstance(external, list):
        for entry in external:
            if (
                isinstance(entry, list) and
                len(entry) == 2 and
                safe_platform_id(entry[0]) and
                isinstance(entry[1], int) and
                not isinstance(entry[1], bool) and
                0 < entry[1] <= NATIVE_INT_MAX
            ):
                lines.append(
                    f"definition:requirement({lua_quote(entry[0])}, {entry[1]})"
                )
            else:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: recipe {recipe_id} external requirement needs review"
                )
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: recipe {recipe_id} external requirements need review"
        )
    unresolved = sorted(set(value) - COMMON_RECIPE_FIELDS)
    if unresolved or forced_partial or len(result.todos) != todo_count:
        result.partial.append(f"{source.location}: recipe {recipe_id}")
        if unresolved:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: recipe {recipe_id} unresolved fields: {', '.join(unresolved)}"
            )
    else:
        result.converted.append(f"{source.location}: recipe {recipe_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


def unresolved_fields(value: dict[str, Any], supported: set[str]) -> list[str]:
    return sorted(
        key for key in set(value) - supported if not key.startswith("//")
    )


def finish_catalog(
    source: SourceObject,
    result: MigrationResult,
    label: str,
    object_id: str,
    lines: list[str],
    supported: set[str],
    todo_count: int,
) -> str:
    unresolved = unresolved_fields(source.value, supported)
    if unresolved:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: {label} {object_id} unresolved fields: " +
            ", ".join(unresolved)
        )
    status = result.partial if unresolved or len(result.todos) != todo_count else result.converted
    status.append(f"{source.location}: {label} {object_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


def render_requirement(source: SourceObject, result: MigrationResult) -> str | None:
    # This catalog family already has typed builders.  A source shape that
    # cannot be lowered by the bounded renderer therefore needs an ordinary
    # Lua rewrite, rather than expanding the Platform contract implicitly.
    value = source.value
    requirement_id = value.get("id")
    if not safe_platform_id(requirement_id):
        result.partial.append(f"{source.location}: requirement <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: requirement needs a stable native id")
        return None
    todo_count = len(result.todos)
    lines = ["local definition = content.Requirement {", f"    id = {lua_quote(requirement_id)},"]
    name = value.get("name")
    if name is not None:
        text = display_text(name)
        if text:
            lines.append(f"    name = {lua_quote(text)},")
        else:
            result.add_todo("manual_rewrite", f"{source.location}: requirement {requirement_id} name needs review")
    lines.append("}")
    render_requirement_groups(
        lines,
        value.get("components", []),
        "component",
        "component_any",
        result.add_todo,
        source.location,
        owner=f"requirement {requirement_id}",
    )
    render_requirement_groups(
        lines,
        value.get("tools", []),
        "tool",
        "tool_any",
        result.add_todo,
        source.location,
        tools=True,
        owner=f"requirement {requirement_id}",
    )
    qualities = value.get("qualities", [])
    if isinstance(qualities, list):
        for group in qualities:
            if not isinstance(group, list) or not group:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: requirement {requirement_id} quality group needs review"
                )
                continue
            converted: list[tuple[str, int, int]] = []
            for entry in group:
                if (
                    isinstance(entry, list) and
                    2 <= len(entry) <= 3 and
                    safe_platform_id(entry[0]) and
                    isinstance(entry[1], int) and
                    not isinstance(entry[1], bool) and
                    0 < entry[1] <= NATIVE_INT_MAX and
                    (len(entry) == 2 or (
                        isinstance(entry[2], int) and
                        not isinstance(entry[2], bool) and
                        0 < entry[2] <= NATIVE_INT_MAX
                    ))
                ):
                    converted.append((entry[0], entry[1], entry[2] if len(entry) == 3 else 1))
                else:
                    converted = []
                    break
            if not converted:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: requirement {requirement_id} quality group needs review"
                )
            elif len(converted) == 1:
                quality_id, level, count = converted[0]
                lines.append(
                    f"definition:quality({lua_quote(quality_id)}, {level}, {count})"
                )
            else:
                rendered = ", ".join(
                    f"{{ id = {lua_quote(quality_id)}, level = {level}, count = {count} }}"
                    for quality_id, level, count in converted
                )
                lines.append(f"definition:quality_any {{ {rendered} }}")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: requirement {requirement_id} qualities need review"
        )
    return finish_catalog(
        source,
        result,
        "requirement",
        requirement_id,
        lines,
        {"type", "id", "name", "components", "tools", "qualities"},
        todo_count,
    )


def render_recipe_group(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    group_id = value.get("id")
    if not safe_platform_id(group_id):
        result.partial.append(f"{source.location}: recipe group <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: recipe group needs a stable native id")
        return None
    todo_count = len(result.todos)
    building_type = value.get("building_type", "NONE")
    if not isinstance(building_type, str) or not building_type:
        building_type = "NONE"
        result.add_todo("manual_rewrite", f"{source.location}: recipe group {group_id} building type needs review")
    lines = [
        "local definition = content.RecipeGroup {",
        f"    id = {lua_quote(group_id)},",
        f"    building_type = {lua_quote(building_type)},",
        "}",
    ]
    recipes = value.get("recipes", [])
    if isinstance(recipes, list):
        for recipe in recipes:
            if not isinstance(recipe, dict) or not safe_platform_id(recipe.get("id")):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: recipe group {group_id} recipe entry needs review"
                )
                continue
            recipe_id = recipe["id"]
            description = display_text(recipe.get("description"), recipe_id)
            lines.append(
                f"definition:recipe({lua_quote(recipe_id)}, {lua_quote(description)})"
            )
            terrains = recipe.get("om_terrains", [])
            if not isinstance(terrains, list):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: recipe group {group_id} recipe {recipe_id} terrains need review"
                )
                continue
            for terrain in terrains:
                terrain_id: Any
                match_type: Any = "TYPE"
                parameters: Any = {}
                if isinstance(terrain, str):
                    terrain_id = terrain
                elif isinstance(terrain, dict):
                    terrain_id = terrain.get("om_terrain")
                    match_type = terrain.get("om_terrain_match_type", "TYPE")
                    parameters = terrain.get("parameters", {})
                else:
                    terrain_id = None
                if not isinstance(terrain_id, str) or not terrain_id or not isinstance(match_type, str) or match_type.upper() not in {"EXACT", "TYPE", "SUBTYPE", "PREFIX", "CONTAINS"}:
                    result.add_todo(
                        "manual_rewrite",
                        f"{source.location}: recipe group {group_id} recipe {recipe_id} terrain needs review"
                    )
                    continue
                lines.append(
                    f"definition:terrain({lua_quote(recipe_id)}, {lua_quote(terrain_id)}, {lua_quote(match_type.upper())})"
                )
                if not isinstance(parameters, dict):
                    result.add_todo(
                        "manual_rewrite",
                        f"{source.location}: recipe group {group_id} recipe {recipe_id} terrain parameters need review"
                    )
                    continue
                for parameter, accepted in parameters.items():
                    if isinstance(parameter, str) and parameter and isinstance(accepted, list) and accepted and all(isinstance(entry, str) and entry for entry in accepted):
                        rendered_values = "{ " + ", ".join(lua_quote(entry) for entry in accepted) + " }"
                        lines.append(
                            f"definition:terrain_parameter({lua_quote(recipe_id)}, {lua_quote(parameter)}, {rendered_values})"
                        )
                    else:
                        result.add_todo(
                            "manual_rewrite",
                            f"{source.location}: recipe group {group_id} recipe {recipe_id} terrain parameter needs review"
                        )
    else:
        result.add_todo("manual_rewrite", f"{source.location}: recipe group {group_id} recipes need review")
    return finish_catalog(
        source,
        result,
        "recipe group",
        group_id,
        lines,
        {"type", "id", "building_type", "recipes"},
        todo_count,
    )


def render_scenario(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    scenario_id = value.get("id")
    if not safe_platform_id(scenario_id):
        result.partial.append(f"{source.location}: scenario <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: scenario needs a stable native id")
        return None
    todo_count = len(result.todos)
    name = display_text(value.get("name"), scenario_id)
    description = display_text(value.get("description"), "")
    start_name = display_text(value.get("start_name"), "")

    def integer_option(field: str, default: int) -> int:
        raw = value.get(field, default)
        if (
            isinstance(raw, int) and
            not isinstance(raw, bool) and
            NATIVE_INT_MIN <= raw <= NATIVE_INT_MAX
        ):
            return raw
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: scenario {scenario_id} {field} needs review"
        )
        return default

    def boolean_option(field: str, default: bool) -> bool:
        raw = value.get(field, default)
        if isinstance(raw, bool):
            return raw
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: scenario {scenario_id} {field} needs review"
        )
        return default

    lines = [
        "local definition = content.Scenario {",
        f"    id = {lua_quote(scenario_id)},",
        f"    name = {lua_quote(name)},",
        f"    description = {lua_quote(description)},",
        f"    start_name = {lua_quote(start_name)},",
        f"    points = {integer_option('points', 0)},",
        f"    blacklist = {'true' if boolean_option('blacklist', False) else 'false'},",
        "    extra_professions = "
        f"{'true' if boolean_option('add_professions', False) else 'false'},",
        f"    reveal_locale = {'true' if boolean_option('reveal_locale', True) else 'false'},",
        "    distance_initial_visibility = "
        f"{integer_option('distance_initial_visibility', 15)},",
        "}",
    ]

    def render_id_list(field: str, method: str) -> None:
        raw = value.get(field, [])
        if not isinstance(raw, list) or any(
            not isinstance(entry, str) or not entry for entry in raw
        ):
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: scenario {scenario_id} {field} needs review"
            )
            return
        for entry in raw:
            lines.append(f"definition:{method}({lua_quote(entry)})")

    render_id_list("allowed_locs", "location")
    render_id_list("professions", "profession")
    render_id_list("traits", "allowed_trait")
    render_id_list("forced_traits", "forced_trait")
    render_id_list("forbidden_traits", "forbidden_trait")
    render_id_list("flags", "flag")
    requirement = value.get("requirement")
    if requirement is None:
        pass
    elif isinstance(requirement, str) and requirement:
        lines.append(f"definition:requirement({lua_quote(requirement)})")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: scenario {scenario_id} requirement needs review"
        )
    return finish_catalog(
        source,
        result,
        "scenario",
        scenario_id,
        lines,
        {
            "type", "id", "name", "description", "start_name", "points",
            "blacklist", "add_professions", "reveal_locale",
            "distance_initial_visibility", "allowed_locs", "professions",
            "traits", "forced_traits", "forbidden_traits", "flags",
            "requirement",
        },
        todo_count,
    )


def render_vehicle_color_palette(
    source: SourceObject, result: MigrationResult
) -> str | None:
    value = source.value
    palette_id = value.get("id")
    if not safe_platform_id(palette_id):
        result.partial.append(f"{source.location}: vehicle color palette <invalid id>")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: vehicle color palette needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    lines = [
        "local definition = content.VehicleColorPalette {",
        f"    id = {lua_quote(palette_id)},",
        "}",
    ]
    raw_groups = value.get("palette")
    if isinstance(raw_groups, list) and raw_groups:
        for raw_group in raw_groups:
            if not isinstance(raw_group, dict):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: vehicle color palette {palette_id} "
                    "group needs review"
                )
                continue
            fuzzy_ids = raw_group.get("fuzzy_ids", [])
            raw_colors = raw_group.get("colors", [])
            if not isinstance(fuzzy_ids, list) or not fuzzy_ids or any(
                not isinstance(entry, str) or not entry for entry in fuzzy_ids
            ) or not isinstance(raw_colors, list) or not raw_colors or any(
                not isinstance(entry, dict) or
                not isinstance(entry.get("color"), str) or
                not entry.get("color") or
                not isinstance(entry.get("weight"), int) or
                isinstance(entry.get("weight"), bool) or
                entry.get("weight", 0) <= 0
                for entry in raw_colors
            ):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: vehicle color palette {palette_id} "
                    "group needs review"
                )
                continue
            lines.append(
                "definition:group(" +
                "{ " + ", ".join(
                    lua_quote(entry) for entry in fuzzy_ids
                ) + " }, {"
            )
            for entry in raw_colors:
                lines.append(
                    "    { "
                    f"{lua_quote(entry['color'])}, {entry['weight']} }},"
                )
            lines[-1] = lines[-1][:-1]
            lines.append("})")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: vehicle color palette {palette_id} "
            "palette needs review"
        )
    return finish_catalog(
        source,
        result,
        "vehicle color palette",
        palette_id,
        lines,
        {"type", "id", "palette", "//"},
        todo_count,
    )


_LUA_RESERVED_WORDS = {
    "and", "break", "do", "else", "elseif", "end", "false", "for",
    "function", "goto", "if", "in", "local", "nil", "not", "or",
    "repeat", "return", "then", "true", "until", "while",
}


def _lua_literal(value: Any) -> str:
    """Render the bounded JSON scalar/table subset used by Platform descriptors."""
    if isinstance(value, LuaRaw):
        return value.source
    if value is None:
        return "nil"
    if isinstance(value, bool):
        return lua_boolean(value)
    if isinstance(value, (int, float)) and not isinstance(value, bool):
        return lua_number(value)
    if isinstance(value, str):
        return lua_quote(value)
    if isinstance(value, list):
        return "{ " + ", ".join(_lua_literal(entry) for entry in value) + " }"
    if isinstance(value, dict):
        entries: list[str] = []
        for key in sorted(value):
            rendered_key = (
                key if isinstance(key, str) and
                key not in _LUA_RESERVED_WORDS and
                re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", key)
                else f"[{lua_quote(str(key))}]"
            )
            entries.append(f"{rendered_key} = {_lua_literal(value[key])}")
        return "{ " + ", ".join(entries) + " }"
    raise TypeError(f"unsupported Lua literal {type(value).__name__}")


