def _distribute_food_auto_todo(effect: Any) -> str | None:
    """Describe the native zone and food-inventory transaction we cannot lower."""
    if not isinstance(effect, str) or effect != "distribute_food_auto":
        return None
    return (
        "native distribute_food_auto emits debugmsg and returns if the NPC has no camp at its "
        "current OMT or fails allowed_access_by, then adds enabled CAMP_FOOD and CAMP_STORAGE "
        "zones over the NPC's 3x3 map-square area and runs distribute_food(false). That call "
        "validates sort zones around the global avatar and may query_yn to open zone setup; "
        "missing zones also produce an NPC-distribution debugmsg, while no suitable food "
        "returns false quietly and the wrapper ignores the result. Successful distribution "
        "consumes eligible ground and vehicle food with native nutrition and spoilage rules, "
        "then credits the camp owner's faction. Cleanup removes every same-faction CAMP_FOOD "
        "and CAMP_STORAGE zone, including pre-existing zones, rather than only the temporary "
        "pair. Platform camps.food.add/consume mutate supply directly and services.zones only "
        "manage zones; neither preserves this inventory transaction, diagnostics/UI behavior, "
        "or destructive cleanup"
    )


def _camp_selector_object_todo(effect: Any) -> str | None:
    """Reject object forms for camp selectors registered as native strings."""
    if not isinstance(effect, dict):
        return None
    selectors = set(effect) & _CAMP_SELECTOR_TODOS.keys()
    if (
        not selectors and set(effect) == {"effect"} and
        isinstance(effect["effect"], str) and effect["effect"] in _CAMP_SELECTOR_TODOS
    ):
        selectors = {effect["effect"]}
    if not selectors:
        return None
    names = ", ".join(sorted(selectors))
    return (
        f"{names} is registered by native talk_effect_t as a string selector; "
        "object-valued forms are not accepted by its sub-effect parser and need "
        "the intended operation verified before choosing a Lua rewrite"
    )


def render_dialogue_trade_effect(
    effect: Any,
    result: MigrationResult,
    location: str,
    label: str,
) -> LuaRaw | None:
    """Reject trade, purchase, and payment callbacks without native context."""
    if isinstance(effect, dict) and set(effect) == {"effect"}:
        effect = effect["effect"]
    if isinstance(effect, str):
        key = effect
    elif isinstance(effect, dict):
        keys = [
            name for name in (
                "u_bulk_donate", "npc_bulk_donate",
                "u_bulk_trade_accept", "npc_bulk_trade_accept",
                "quote_npc_trade_item", "u_buy_monster", "u_spend_cash",
            ) if name in effect
        ]
        if len(keys) != 1:
            return None
        key = keys[0]
    else:
        return None

    if key == "quote_npc_trade_item":
        # Native quote effects set prefixed quote variables from an item type
        # and NPC pricing.  services.trade.quote instead requires an exact
        # held Item and returns a transaction token.
        return None

    if key in {
        "quote_vehicle_full_repair", "select_vehicle_part_service",
        "start_vehicle_full_repair",
    }:
        # The former path found a marked/current vehicle implicitly.  A
        # dialogue talker does not prove an exact Vehicle handle, so no
        # Vehicle service is emitted from this shape.
        return None

    if key not in {
        "u_bulk_donate", "npc_bulk_donate",
        "u_bulk_trade_accept", "npc_bulk_trade_accept",
        "u_buy_monster", "u_spend_cash",
    }:
        return None
    # These native actions depend on current dialogue participants and state.
    # Their selector arguments do not carry the exact transaction handles or
    # callback context required by the Platform services.
    return None


def _validated_eoc_references(
    value: Any, eoc_function_names: dict[str, str], *, allow_empty: bool = False
) -> list[str] | None:
    # The legacy contract accepts either one EOC id or an array.  Inline-EOC
    # normalization keeps scalar ``run_eocs`` values scalar, so normalize the
    # singleton here instead of making every renderer duplicate this shape
    # check.
    if isinstance(value, str):
        value = [value]
    if not isinstance(value, list) or (not value and not allow_empty):
        return None
    references: list[str] = []
    for entry in value:
        if not isinstance(entry, str) or entry not in eoc_function_names:
            return None
        references.append(entry)
    return references


def _traversal_calls(
    references: list[str], eoc_function_names: dict[str, str], *,
    target: bool = True, owner_actor: str | None = None,
) -> list[str]:
    lines: list[str] = []
    for reference in references:
        function_name = eoc_function_names[reference]
        if target:
            lines.append(f"        {function_name}(context, target)")
        else:
            lines.append(
                f"        {function_name}(context, {owner_actor or 'nil'})"
            )
    return lines


def _traversal_integer_expression(
    value: Any, minimum: int, maximum: int,
    actor_expression: str,
) -> str | None:
    literal = finite_number_literal(value)
    if literal is not None:
        if literal != math.trunc(float(literal)) or literal < minimum or literal > maximum:
            return None
        return str(int(literal))
    rendered = render_eoc_numeric_expression(value, str(minimum), actor_expression)
    if rendered is None:
        return None
    return f"math.floor(({rendered}) + 0.5)"


def _traversal_string_expression(value: Any, actor_expression: str) -> str | None:
    if bounded_utf8_string(value, PLATFORM_ID_MAX_BYTES, allow_empty=False):
        return lua_quote(value)
    return render_eoc_string_expression(value, actor_expression)


def render_static_traversal(
    effect: dict[str, Any],
    key: str,
    actor_expression: str | None,
    eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
) -> list[str] | None:
    """Lower bounded non-item ``*_run_*_eocs`` selectors to Lua iteration.

    Each supported branch consumes detached pages and generation-safe handles
    from the Platform domain services.  The generated code never calls an EOC
    runner or passes a native pointer across Lua.  Inline EOC objects have
    already been normalised to private function names by
    :func:`normalize_inline_eocs`.
    """
    # This branch is actor-owned.  Do not invent an avatar when the source
    # event did not provide a proven Character handle; the caller will retain
    # the shape as an explicit migration TODO.
    if actor_expression is None:
        return None
    if key not in effect:
        return None
    if key in {"u_run_inv_eocs", "npc_run_inv_eocs"}:
        # Native Character::all_items_loc() walks wielded and worn roots in
        # recursive postorder and excludes ordinary carried inventory, while
        # services.items.page does not expose the same set and order.
        return None
    if key in {"u_map_run_item_eocs", "npc_map_run_item_eocs"}:
        # Native map selection preserves points_in_radius/item-stack order,
        # evaluates search_data with the cloned owner and selected item talkers,
        # and gives manual_mult false_eocs only when the candidate set is empty.
        # The Platform map page sorts by position/UID and the generic
        # multi-picker path cannot preserve those callback/false-branch semantics.
        return None
    if key in {"u_run_monster_eocs", "npc_run_monster_eocs"}:
        # Native walks game::all_creatures() order and includes hallucination
        # monsters.  services.creatures.nearby sorts by distance/type and
        # defaults to excluding hallucinations.  Native also creates a
        # fresh dialogue with the target monster as alpha for each callback;
        # this ordinary Lua traversal cannot preserve that talker/context
        # boundary.  The npc_* forms read mutable actor(true), which is beta
        # and falls back to alpha with a debug diagnostic; an event alpha does
        # not prove that beta slot.
        return None
    if key in {"u_run_vehicle_eocs", "npc_run_vehicle_eocs"}:
        # Native walks map::get_vehicles() order, uses rl_dist, and creates a
        # fresh dialogue with each vehicle as alpha.  services.world.vehicles
        # sorts by position, while the former lowering used square_distance
        # and a shared Lua callback context.
        return None
    raw_references = effect.get(key)
    if isinstance(raw_references, str):
        raw_references = [raw_references]
    references = _validated_eoc_references(raw_references, eoc_function_names)
    if references is None:
        return None
    if eoc_actor_requirements is not None and any(
        eoc_actor_requirements.get(reference) in {"exact_avatar", "unproven"}
        for reference in references
    ):
        return None

    if key in {"u_run_npc_eocs", "npc_run_npc_eocs"}:
        if actor_expression is None:
            return None
        allowed = {key, "npc_range", "unique_ids", "local", "z_min", "z_max", "npc_must_see"}
        if set(effect) - allowed:
            return None
        local = effect.get("local", False)
        if not isinstance(local, bool):
            return None
        radius = effect.get("npc_range")
        radius_expression = (
            _traversal_integer_expression(radius, 0, 1000000, actor_expression)
            if radius is not None else None
        )
        if radius is not None and radius_expression is None:
            return None
        z_expressions: dict[str, str] = {}
        for name in ("z_min", "z_max"):
            value = effect.get(name)
            if value is not None:
                expression = _traversal_integer_expression(
                    value, -1000000, 1000000, actor_expression
                )
                if expression is None:
                    return None
                z_expressions[name] = expression
        unique_ids = effect.get("unique_ids")
        unique_id_expressions: list[str] = []
        if unique_ids is not None:
            if not isinstance(unique_ids, list) or not unique_ids:
                return None
            for value in unique_ids:
                expression = _traversal_string_expression(value, actor_expression)
                if expression is None:
                    return None
                unique_id_expressions.append(expression)
        calls = _traversal_calls(references, eoc_function_names)
        if not local:
            if unique_ids is None:
                # Native non-local traversal iterates only ``unique_ids``;
                # an absent/empty list is a deliberate no-op even if legacy
                # range fields are present.
                return []
            lines = [
                "    for _, unique_id in ipairs({ " +
                ", ".join(unique_id_expressions) + " }) do",
                "        local target = service_value(services.npcs.find_unique(unique_id))",
                "        if target ~= nil and target:is_valid() then",
                *calls,
                "        end",
                "    end",
            ]
            return lines
        lines = [
            f"    local npc_origin = service_value(services.characters.snapshot({actor_expression})).creature.position",
        ]
        if unique_ids is not None:
            lines.extend([
                "    for _, unique_id in ipairs({ " + ", ".join(unique_id_expressions) + " }) do",
                "        local target = service_value(services.npcs.find_unique(unique_id))",
                "        if target ~= nil and target:is_valid() then",
                "            local target_snapshot = service_value(services.creatures.snapshot(target))",
                "            if (",
                f"                {z_expressions['z_min']} <= target_snapshot.position.z" if "z_min" in z_expressions else "                true",
                ") and (",
                f"                target_snapshot.position.z <= {z_expressions['z_max']}" if "z_max" in z_expressions else "                true",
                ") and (",
                "                target_snapshot.position.z == npc_origin.z" if radius is not None and "z_min" not in z_expressions and "z_max" not in z_expressions else "                true",
                ") and (",
                "                not " + lua_boolean(bool(effect.get("npc_must_see", False))) +
                " or service_value(services.creatures.can_see(target, " + actor_expression + "))) then",
                *calls,
                "            end",
                "        end",
                "    end",
            ])
            return lines
        if radius is None:
            lines.extend([
                "    local npc_offset = 0",
                "    while true do",
                "        local npc_page = service_value(services.npcs.list({",
                "            offset = npc_offset, limit = 256,",
                "        }))",
                "        for _, entry in ipairs(npc_page.items) do",
                "            local target = entry.handle",
                "            local target_z = entry.position.z",
                "            if (",
                f"                {z_expressions['z_min']} <= target_z" if "z_min" in z_expressions else "                true",
                ") and (",
                f"                target_z <= {z_expressions['z_max']}" if "z_max" in z_expressions else "                true",
                ") and (",
                "                not " + lua_boolean(bool(effect.get("npc_must_see", False))) +
                " or service_value(services.creatures.can_see(target, " + actor_expression + "))",
                ") then",
                *[line.replace("        ", "                ", 1) for line in calls],
                "            end",
                "        end",
                "        if not npc_page.has_more or npc_page.returned == 0 then",
                "            break",
                "        end",
                "        npc_offset = npc_offset + npc_page.returned",
                "    end",
            ])
            return lines
        lines.extend([
            "    local npc_offset = 0",
            "    while true do",
            "        local npc_page = services.creatures.nearby(",
            f"            {actor_expression}, {{",
            "            origin = npc_origin,",
            f"            radius = {radius_expression},",
            "            kind = \"npc\",",
            "            visible_only = false,",
            "            include_avatar = false,",
            "            include_hallucinations = false,",
            "            offset = npc_offset,",
            "            limit = 256,",
            "        })",
            "        for _, entry in ipairs(npc_page.items) do",
            "            local target = entry.handle",
            "            local target_z = entry.snapshot.position.z",
            "            if (",
            (
                f"                {z_expressions['z_min']} <= target_z"
                if "z_min" in z_expressions
                else "                true"
            ),
            ") and (",
            (
                f"                target_z <= {z_expressions['z_max']}"
                if "z_max" in z_expressions
                else "                true"
            ),
            ") and (",
            "                target_z == npc_origin.z" if local and "z_min" not in z_expressions and "z_max" not in z_expressions else "                true",
            ") and (",
            "                not " + lua_boolean(bool(effect.get("npc_must_see", False))) +
            " or service_value(services.creatures.can_see(target, " + actor_expression + "))",
            ") then",
            *[line.replace("        ", "                ", 1) for line in calls],
            "            end",
            "        end",
            "        if not npc_page.has_more or npc_page.returned == 0 then",
            "            break",
            "        end",
            "        npc_offset = npc_offset + npc_page.returned",
            "    end",
        ])
        return lines

    if key in {"u_run_fixed_zone_eocs", "npc_run_fixed_zone_eocs"}:
        if actor_expression is None:
            return None
        allowed = {key, "zone_range", "z_min", "z_max"}
        if set(effect) - allowed:
            return None
        radius = effect.get("zone_range")
        radius_expression = (
            _traversal_integer_expression(
                radius, 0, 1000000, actor_expression
            )
            if radius is not None else None
        )
        if radius is not None and radius_expression is None:
            return None
        z_expressions = {}
        for name in ("z_min", "z_max"):
            value = effect.get(name)
            if value is not None:
                expression = _traversal_integer_expression(
                    value, -1000000, 1000000, actor_expression
                )
                if expression is None:
                    return None
                z_expressions[name] = expression
        calls = _traversal_calls(references, eoc_function_names)
        lines = [
            f"    local zone_origin = service_value(services.characters.snapshot({actor_expression})).creature.position",
            "    local zone_offset = 0",
            "    while true do",
            "        local zone_page = service_value(services.zones.list({ kind = \"global\", offset = zone_offset, limit = 256 }))",
            "        for _, entry in ipairs(zone_page.items) do",
            "            local target = entry.token",
            "            local target_z = entry.start.z",
        ]
        if radius_expression is not None:
            lines.append(
                "            local distance = zone_origin:square_distance(entry.start)"
            )
        lines.extend([
            "            if " + (
                f"distance <= {radius_expression} and "
                if radius_expression is not None else ""
            ) + "(",
            f"                {z_expressions['z_min']} <= target_z" if "z_min" in z_expressions else "                true",
            ") and (",
            f"                target_z <= {z_expressions['z_max']}" if "z_max" in z_expressions else "                true",
            ") then",
            *[line.replace("        ", "                ", 1) for line in calls],
            "            end",
            "        end",
            "        if not zone_page.has_more or zone_page.returned == 0 then",
            "            break",
            "        end",
            "        zone_offset = zone_offset + zone_page.returned",
            "    end",
        ])
        return lines

    if key in {"u_map_run_eocs", "npc_map_run_eocs"}:
        # The position query has the same closest_points_first order as native,
        # but that is not enough to preserve this callback. Native writes an
        # optional var_info before every tile, reevaluates condition(d) before
        # every EOC, and effect_on_condition::activate copies the dialogue and
        # its context for each callback. A generated Lua loop shares one mutable
        # context table, and this source does not prove typed coordinates or
        # equivalent per-callback context-copy semantics.
        return None

    return None


def render_static_npc_run_eocs(
    effect: dict[str, Any], key: str, actor_expression: str | None,
    eoc_function_names: dict[str, str],
) -> list[str] | None:
    """Compatibility wrapper retained for callers and focused tests."""
    return render_static_traversal(effect, key, actor_expression, eoc_function_names)


def render_static_set_condition(
    effect: dict[str, Any], avatar_actor_proven: bool,
    weapon_actor_proven: bool, npc_actor_proven: bool,
    creature_actor_proven: bool,
    eoc_conditions: dict[str, Any] | None,
    actor_expression: str | None,
    npc_actor_expression: str | None,
) -> list[str] | None:
    """Store one named predicate in the current ordinary Lua context."""
    if set(effect) != {"set_condition", "condition"}:
        return None
    # Native evaluates this key as str_or_var<std::string>.  A runtime
    # diag_value is converted with diag_value::str(), which is not proven to
    # match Lua tostring for every possible value type.  Keep this callback
    # registry limited to fixed keys until the conversion is modeled exactly.
    if (
        actor_expression is None or
        not bounded_utf8_string(effect["set_condition"], 8192, allow_empty=True)
    ):
        return None
    name = lua_quote(effect["set_condition"])
    # The native stored std::function evaluates against the dialogue passed
    # later to evaluate_conditional, which may have a different alpha/beta
    # from the setter event.  Compile only generic runtime actor queries here;
    # never bake the setter's avatar, weapon, or NPC proof into the closure.
    # Getter call sites separately prove that their current alpha is a
    # Character before invoking such a closure.
    predicate = render_eoc_condition_expression(
        effect["condition"],
        avatar_actor_proven=False,
        weapon_actor_proven=False,
        npc_actor_proven=False,
        creature_actor_proven=True,
        eoc_conditions=eoc_conditions,
        generic_character_actor_proven=True,
    )
    # Some legacy math predicates still fall back to the ambient avatar when
    # no exact variable scope is modeled. A saved callback must use its later
    # dialogue, so reject that generated fallback rather than capturing it.
    if (
        name is None or predicate is None or
        "services.characters.avatar()" in predicate
    ):
        return None
    return [
        "    context.conditions = context.conditions or {}",
        f"    local stored_condition_name = tostring(({name}) or \"\")",
        "    context.conditions[stored_condition_name] = function(context, actor, stored_condition_beta)",
        f"        return {predicate}",
        "    end",
    ]


def render_static_run_eocs(
    effect: dict[str, Any], eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
    actor_expression: str | None = None,
    avatar_actor_proven: bool = False,
    npc_actor_proven: bool = False,
    eoc_conditions: dict[str, Any] | None = None,
    npc_actor_expression: str | None = None,
    global_eoc_ids: frozenset[str] = frozenset(),
    character_actor_proven: bool = False,
) -> list[str] | None:
    """Call named/normalised EOC functions immediately as ordinary Lua."""
    if "run_eocs" not in effect:
        return None
    if actor_expression is None:
        return None
    allowed = {
        "run_eocs", "time_in_future", "alpha_loc", "alpha_talker",
        "beta_loc", "beta_talker", "false_effect", "false_eocs",
        "variables", "iterations", "condition", "randomize_time_in_future",
    }
    if set(effect) - allowed:
        return None
    fallback_actor = actor_expression or "services.characters.avatar()"
    raw = effect.get("run_eocs")
    raw_references = [raw] if isinstance(raw, (str, dict)) else raw
    if not isinstance(raw_references, list) or not raw_references:
        return None
    reference_entries: list[tuple[str, str]] = []
    for entry in raw_references:
        if isinstance(entry, str):
            if entry not in eoc_function_names:
                return None
            reference_entries.append(("static", entry))
            continue
        dynamic_reference = render_eoc_string_expression(
            entry, fallback_actor
        )
        if dynamic_reference is None:
            return None
        reference_entries.append(("dynamic", dynamic_reference))
    references = [
        value for kind, value in reference_entries if kind == "static"
    ]
    if eoc_actor_requirements is not None and any(
        eoc_actor_requirements.get(reference) in {"exact_avatar", "unproven"}
        for reference in references
    ):
        return None
    requires_current_character = (
        eoc_actor_requirements is not None and any(
            eoc_actor_requirements.get(reference) == "character"
            for reference in references
        )
    )
    if requires_current_character and not (
        character_actor_proven or avatar_actor_proven
    ):
        return None
    if requires_current_character and (
        "alpha_talker" in effect or "alpha_loc" in effect
    ):
        # A child alpha override can select a different generic Creature
        # talker.  This runner has no Character-kind proof for that override.
        return None
    has_dynamic_references = len(references) != len(reference_entries)
    if has_dynamic_references and eoc_actor_requirements is not None and any(
        requirement == "unproven"
        for requirement in eoc_actor_requirements.values()
    ):
        # A dynamic selector may resolve to a game_start EOC whose alpha is
        # not proven after an in-corpus replay. Do not let the generic
        # function table bypass the static-reference requirement check.
        return None
    false_references = _validated_eoc_references(
        effect.get("false_eocs", []), eoc_function_names, allow_empty=True
    )
    if references is None or false_references is None:
        return None
    alpha_talker = effect.get("alpha_talker")
    beta_talker = effect.get("beta_talker")
    alpha_loc = effect.get("alpha_loc")
    beta_loc = effect.get("beta_loc")
    if (
        alpha_talker is not None and alpha_loc is not None or
        beta_talker is not None and beta_loc is not None
    ):
        return None

    parent_alpha = (
        "((context.actors and context.actors.alpha) or " + actor_expression + ")"
        if actor_expression is not None else
        "(context.actors and context.actors.alpha)"
    )
    parent_beta = npc_actor_expression or (
        "(context.actors and (context.actors.beta or context.actors.npc))"
    )
    talker_setup: list[str] = []

    def location_expression(value: Any) -> str | None:
        context_location = _context_coordinate_expression(value)
        if context_location is not None:
            return context_location
        descriptor = _coordinate_variable_descriptor(value)
        if descriptor is None:
            return None
        scope, name = descriptor
        if scope == "global":
            return (
                "service_value(services.variables.get_global(" +
                lua_quote(name) + ")).value"
            )
        if scope == "context":
            return f"context.data[{lua_quote(name)}]"
        if scope == "var":
            return (
                "service_value(services.variables.resolve(context.data, " +
                fallback_actor + ", \"var\", " + lua_quote(name) + ")).value"
            )
        handle = _coordinate_variable_handle(
            scope, avatar_actor_proven, npc_actor_proven
        )
        if handle is None:
            return None
        return (
            "service_value(services.variables.get(" + handle + ", " +
            lua_quote(name) + ")).value"
        )

    def talker_expression(role: str, value: Any, location: Any) -> str | None:
        parent = parent_alpha if role == "alpha" else parent_beta
        if location is not None:
            coordinate = location_expression(location)
            if coordinate is None:
                return None
            variable = f"run_eocs_{role}"
            talker_setup.extend([
                f"        local {variable} = nil",
                f"        local {variable}_location = {coordinate}",
                f"        if {variable}_location ~= nil then",
                f"            local {variable}_result = services.creatures.at({variable}_location)",
                f"            if {variable}_result.ok then",
                f"                {variable} = {variable}_result.value",
                "            end",
                "        end",
            ])
            return variable
        if value is None:
            return parent
        if value == "":
            return "nil"
        if value == "u":
            return parent_alpha
        if value == "npc":
            return parent_beta
        if value == "avatar":
            return actor_expression if avatar_actor_proven else None
        # A dynamic talker may resolve to the avatar at runtime.  Without a
        # statically proven avatar participant, reject the complete shape
        # rather than hiding an ambient avatar lookup in generated code.
        if not avatar_actor_proven:
            return None
        dynamic = render_eoc_string_expression(value, fallback_actor)
        if dynamic is None:
            return None
        variable = f"run_eocs_{role}"
        talker_setup.extend([
            f"        local {variable} = nil",
            f"        local {variable}_name = tostring(({dynamic}) or \"\")",
            f"        if {variable}_name == \"u\" then",
            f"            {variable} = {parent_alpha}",
            f"        elseif {variable}_name == \"npc\" then",
            f"            {variable} = {parent_beta}",
            f"        elseif {variable}_name == \"avatar\" then",
            f"            {variable} = {actor_expression}",
            f"        elseif {variable}_name ~= \"\" then",
            f"            local {variable}_id = tonumber({variable}_name)",
            f"            if {variable}_id ~= nil then",
            f"                local {variable}_result = services.characters.by_id({variable}_id)",
            f"                if {variable}_result.ok then",
            f"                    {variable} = {variable}_result.value",
            "                end",
            "            end",
            "        end",
        ])
        return variable

    alpha_expression = talker_expression("alpha", alpha_talker, alpha_loc)
    beta_expression = talker_expression("beta", beta_talker, beta_loc)
    if alpha_expression is None or beta_expression is None:
        return None
    has_talker_override = any(
        name in effect for name in (
            "alpha_loc", "alpha_talker", "beta_loc", "beta_talker",
            "false_eocs",
        )
    )
    condition_expression = None
    if "condition" in effect:
        # Native f_run_eocs installs its loop guard only for an object.
        # Do not reinterpret other JSON shapes as a looping predicate.
        if not isinstance(effect["condition"], dict):
            return None
        condition_expression = render_eoc_condition_expression(
            effect["condition"], avatar_actor_proven,
            avatar_actor_proven or npc_actor_proven,
            npc_actor_proven, False, eoc_conditions,
            npc_actor_expression=npc_actor_expression,
        )
        if condition_expression is None:
            return None
    variables = effect.get("variables")

    def array_literal(value: list[Any]) -> str | None:
        nodes = 0

        def render(entry: Any, depth: int) -> str | None:
            nonlocal nodes
            nodes += 1
            if nodes > 512 or depth > 8:
                return None
            if isinstance(entry, list):
                children = [render(child, depth + 1) for child in entry]
                if any(child is None for child in children):
                    return None
                return "{" + ", ".join(children) + "}"
            if entry is None or isinstance(entry, bool):
                return "services.types.null"
            if isinstance(entry, dict) and (entry.get("i18n") or not set(entry) <= {
                    "str", "i18n", "//~", "tripoint"}):
                return None
            return render_eoc_value_expression(entry, "nil", fallback_actor)

        return render(value, 0)

    def variable_expression(value: Any) -> str | None:
        # Native diag_value_or_var assigns an explicit empty value, even when
        # a referenced variable is absent. Do not erase an inherited key.
        if value is None:
            return "services.types.null"
        if isinstance(value, list):
            return array_literal(value)
        literal = lua_scalar_literal(value)
        if literal is not None:
            return literal
        # Native evaluates assignments against the parent dialogue, before
        # applying the child alpha/beta overrides.
        variable_actor = fallback_actor
        if isinstance(value, dict):
            if "npc_val" in value:
                variable_actor = parent_beta
            elif "u_val" in value:
                variable_actor = parent_alpha
        if isinstance(value, dict) and ("default" in value or "var_val" in value):
            descriptor = {key: entry for key, entry in value.items() if key != "default"}
            if len(descriptor) != 1:
                return None
            scope, name = next(iter(descriptor.items()))
            if scope not in {"u_val", "npc_val", "global_val", "context_val", "var_val"}:
                return None
            if render_eoc_value_expression(descriptor, "nil", variable_actor) is None:
                return None
            # Native diag_value leaves JSON booleans as the empty variant.
            default = ("services.types.null" if value.get("default") is None or
                       isinstance(value.get("default"), bool) else
                       render_eoc_value_expression(value.get("default"), "nil", variable_actor))
            if isinstance(value.get("default"), list):
                default = array_literal(value["default"])
            if isinstance(value.get("default"), dict) and value.get("default").get("i18n"):
                return None
            # Defaults are native diag_value literals, not another variable read.
            if isinstance(value.get("default"), dict) and not set(value.get("default")) <= {
                "str", "i18n", "//~", "tripoint",
            }:
                return None
            if default is None:
                return None
            quoted = lua_quote(name)
            if scope == "context_val":
                return (f'(function(value) if value == nil then return {default} end; '
                        f'return value end)(context.data[{quoted}])')
            snapshot = (
                f'services.variables.get_global({quoted})' if scope == "global_val" else
                'services.variables.resolve(context.data, '
                f'{variable_actor}, {lua_quote(scope.removesuffix("_val"))}, {quoted}, '
                f'{{alpha={parent_alpha}, beta={parent_beta}}})'
            )
            return (f'(function(snapshot) if not snapshot.exists then return {default} end; '
                    'if snapshot.value == nil then return services.types.null end; '
                    f'return snapshot.value end)(service_value({snapshot}))')
        rendered = render_eoc_value_expression(value, "nil", variable_actor)
        if rendered is None:
            rendered = render_eoc_numeric_expression(value, "0", variable_actor)
        if rendered is None:
            return None
        if not isinstance(value, dict) or not set(value).intersection({
            "u_val", "npc_val", "global_val", "context_val", "var_val",
        }):
            return rendered
        return ('(function(value) if value == nil then return services.types.null end; '
                f'return value end)({rendered})')

    if variables is not None:
        if not isinstance(variables, dict) or len(variables) > 64:
            return None
        for name, value in variables.items():
            if (
                not isinstance(name, str) or not bounded_utf8_string(name, 256) or
                variable_expression(value) is None
            ):
                return None
    delay = effect.get("time_in_future", 0)
    randomize_delay = effect.get("randomize_time_in_future", False)
    if (
        not isinstance(randomize_delay, bool) or
        randomize_delay and "time_in_future" not in effect
    ):
        return None
    delay_turns = parse_turns(delay)
    delay_turns_expression: str | None = None
    if isinstance(delay, list):
        if len(delay) != 2:
            return None
        rendered_bounds: list[str] = []
        for bound in delay:
            parsed = parse_turns(bound)
            if parsed is not None:
                if parsed < 0 or parsed > MAX_EFFECT_DURATION_TURNS:
                    return None
                rendered_bounds.append(str(parsed))
                continue
            dynamic_bound = render_eoc_numeric_expression(
                bound, "0", fallback_actor
            )
            if dynamic_bound is None:
                return None
            rendered_bounds.append(
                "math.max(0, math.min(" + str(MAX_EFFECT_DURATION_TURNS) +
                ", math.floor((" + dynamic_bound + ") + 0.5)))"
            )
        lower, upper = rendered_bounds
        delay_turns_expression = (
            "services.random.int(math.min(" + lower + ", " + upper +
            "), math.max(" + lower + ", " + upper + "))"
        )
    if delay_turns is None and delay_turns_expression is None:
        # A context-backed delay is legal only when it is an integral value at
        # runtime.  tasks.after takes turns rather than a UnitValue.
        dynamic_delay = render_eoc_numeric_expression(
            delay, "0", fallback_actor
        )
        if dynamic_delay is None:
            return None
        if delay_turns_expression is None:
            delay_turns_expression = (
                "math.floor((" +
                dynamic_delay +
                ") + 0.5)"
            )
    else:
        if delay_turns_expression is None:
            delay_turns_expression = str(delay_turns)
    if has_dynamic_references and (
        delay_turns != 0 or delay_turns_expression not in (None, "0")
    ):
        return None
    # Persistent task payloads contain only serializable values.  Avatar
    # callbacks can reacquire their actor directly; exact Character, Item,
    # Monster, and Vehicle identities are persisted as scalars and rebound to
    # fresh generation-bound handles when the task fires.  A delayed talker
    # override persists each selected talker as a named participant and
    # therefore has no primary task actor.
    has_delay = (
        delay_turns != 0 or delay_turns_expression not in (None, "0")
    )
    delayed_talker_pair = has_delay and has_talker_override
    task_references = list(references)
    force_global_avatar_task = False
    if has_delay and eoc_actor_requirements is not None:
        task_references = []
        for reference in references:
            requirement = eoc_actor_requirements.get(reference, "none")
            if requirement == "unproven":
                # Do not reinterpret a global callback as an avatar task when
                # a JSON game_start replay can supply a different dialogue.
                return None
            if requirement in {"none", "avatar", "character"}:
                task_references.append(reference)
            elif reference in global_eoc_ids:
                task_references.append(reference)
                force_global_avatar_task = True
        if not task_references:
            if has_talker_override:
                return None
            # Native process_eoc intentionally does not queue a non-global
            # activation EOC whose alpha is an Item/Creature/Vehicle talker.
            return []
    delayed_character = bool(
        has_delay and not delayed_talker_pair and (
            force_global_avatar_task or
            eoc_actor_requirements is not None and any(
                eoc_actor_requirements.get(reference, "none") == "character"
                for reference in task_references
            )
        )
    )
    if delayed_character and not (
        character_actor_proven or avatar_actor_proven or npc_actor_proven
    ):
        return None
    if delayed_character and actor_expression is None and not has_talker_override:
        return None
    context_expression = "context"
    prefix: list[str] = []
    prefix.extend([
        "    local function copy_child_value(value)",
        "        if services.types and value == services.types.null then return value end",
        "        if type(value) ~= \"table\" then return value end",
        "        local copied = {}",
        "        for key, entry in pairs(value) do copied[key] = copy_child_value(entry) end",
        "        return copied",
        "    end",
        "    local child_data = {}",
        "    for name, value in pairs((context and context.data) or {}) do",
        "        child_data[name] = copy_child_value(value)",
        "    end",
    ])
    for name, value in (variables or {}).items():
        rendered = variable_expression(value)
        if rendered is None:
            return None
        prefix.extend([
            f"    child_data[{lua_quote(name)}] = {rendered}",
            f"    child_data[{lua_quote(name)}] = copy_child_value(child_data[{lua_quote(name)}])",
        ])
    prefix.extend([
        "    local child_conditions = {}",
        "    for name, predicate in pairs(context.conditions or {}) do",
        "        child_conditions[name] = predicate",
        "    end",
        "    local child_context = { data = child_data, conditions = child_conditions, actors = {} }",
        "    for name, handle in pairs(context.actors or {}) do child_context.actors[name] = handle end",
    ])
    if has_talker_override:
        prefix.extend([
            "    child_context.actors.alpha = selected_alpha",
            "    child_context.actors.beta = selected_beta",
        ])
    context_expression = "child_context"
    iterations = effect.get("iterations")
    loop_count_expression = None
    if iterations is not None:
        if isinstance(iterations, int) and not isinstance(iterations, bool):
            if iterations < 0 or iterations > MAX_RUN_EOC_ITERATIONS:
                return None
            loop_count_expression = str(iterations)
        else:
            dynamic_iterations = render_eoc_numeric_expression(
                iterations, "0", fallback_actor
            )
            if dynamic_iterations is None:
                return None
            loop_count_expression = (
                "math.max(0, math.min(" + str(MAX_RUN_EOC_ITERATIONS) +
                ", math.floor(" + dynamic_iterations + ")))"
            )
    elif condition_expression is not None:
        loop_count_expression = "100"

    def wrap_talker_context(lines: list[str]) -> list[str]:
        if not has_talker_override:
            return lines
        wrapped = [
            "    do",
            *talker_setup,
            f"        local selected_alpha = {alpha_expression}",
            f"        local selected_beta = {beta_expression}",
            "        if selected_alpha == nil and selected_beta == nil then",
        ]
        failure_lines = render_copied_eoc_callbacks(
            false_references, eoc_function_names, actor_expression or "nil"
        )
        assert failure_lines is not None  # References were validated above.
        wrapped.extend("    " + line for line in failure_lines)
        wrapped.extend([
            "        else",
        ])
        wrapped.extend(
            line.replace("    ", "            ", 1) for line in lines
        )
        wrapped.extend([
            "        end",
            "    end",
        ])
        return wrapped

    callback_actor_expression = (
        "selected_alpha" if has_talker_override else actor_expression or "nil"
    )

    def callback_lines(context_value: str, indent: str) -> list[str]:
        rendered: list[str] = []
        for kind, value in reference_entries:
            if kind == "static":
                rendered.append(
                    f"{indent}{eoc_function_names[value]}({context_value}, "
                    f"{callback_actor_expression})"
                )
                continue
            rendered.extend([
                f"{indent}do",
                f"{indent}    local dynamic_eoc_id = tostring(({value}) or \"\")",
                f"{indent}    local dynamic_eoc = migrated_eoc_functions[dynamic_eoc_id]",
                f"{indent}    if dynamic_eoc ~= nil then",
                f"{indent}        dynamic_eoc({context_value}, {callback_actor_expression})",
                f"{indent}    end",
                f"{indent}end",
            ])
        return rendered

    if loop_count_expression is not None:
        if (
            delay_turns != 0 or
            delay_turns_expression not in (None, "0")
        ):
            return None
        if loop_count_expression.isdigit():
            lines = prefix + [
                f"    for _ = 1, {loop_count_expression} do",
            ]
        else:
            lines = prefix + [
                f"    local run_eocs_iterations = {loop_count_expression}",
                "    for _ = 1, run_eocs_iterations do",
            ]
        if condition_expression not in (None, "true"):
            lines.append(f"        if not ({condition_expression}) then break end")
        lines.extend(callback_lines(context_expression, "        "))
        lines.append("    end")
        return wrap_talker_context(lines)
    if delay_turns is not None and delay_turns == 0:
        return wrap_talker_context(
            prefix + callback_lines(context_expression, "    ")
        )
    task_payload = context_expression + ".data"
    task_scope = "\"character\"" if delayed_character else "\"world\""
    task_delay_expression = delay_turns_expression
    if not randomize_delay and len(task_references) > 1:
        prefix.append(
            f"    local delayed_task_turns = {delay_turns_expression}"
        )
        task_delay_expression = "delayed_task_turns"
    if delayed_talker_pair:
        task_actor_arguments = (
            ", nil, { alpha = selected_alpha, beta = selected_beta }"
        )
    elif delayed_character:
        task_actor_arguments = ", delayed_task_actor"
    else:
        task_actor_arguments = ""
    task_lines = [
        f"    ccb.tasks.after({task_delay_expression}, "
        f"{lua_quote('migrated-task.' + reference)}, {task_payload}, 1, {task_scope}"
        f"{task_actor_arguments})"
        for reference in task_references
    ]
    if delayed_character:
        lines = prefix + [
            f"    local delayed_task_actor = {actor_expression}",
            "    if delayed_task_actor ~= nil then",
            *[line.replace("    ", "        ", 1) for line in task_lines],
            "    end",
        ]
    else:
        lines = prefix + task_lines
    return wrap_talker_context(lines)


def render_static_eoc_selector(
    effect: dict[str, Any],
    eoc_function_names: dict[str, str],
    actor_expression: str | None,
) -> list[str] | None:
    """Keep selectors fail-closed until native menu and activation state match.

    Native selectors filter each target EOC's condition, evaluate translated
    and tag-expanded labels, apply selected context variables, have a distinct
    test-mode path, then activate on a copied dialogue.  No Platform adapter
    currently reproduces that combination.
    """
    del effect, eoc_function_names, actor_expression
    return None


_WEIGHTED_LIST_EOC_TODO = (
    "native weighted_list_eocs reads source-ordered [EOC, dbl_or_var] pairs, "
    "narrows each dialogue-evaluated double weight to int, and drops nonpositive "
    "results. services.random.weighted_index now reproduces weighted_int_list "
    "selection for dense source-ordered native-int weights: it drops nonpositive "
    "rows, returns the original 1-based row, and consumes one global "
    "rng_bits() draw even for a single survivor; pick_ent returns index 0 "
    "without using that value for one survivor, while multiple survivors use "
    "raw_draw % total_weight and cumulative source-order weights. It is bounded to "
    "1024 rows and a positive total no greater than INT_MAX; an all-nonpositive "
    "list returns nil after the draw, while native weighted_list_eocs "
    "dereferences its null pick. The native int total itself is unchecked. "
    "This primitive does not evaluate dbl_or_var through the native Dialogue "
    "or synchronously activate the chosen EOC: native activation uses a copied "
    "dialogue, which activate() copies again, and Platform EOC callbacks lack "
    "the copied alpha/beta Dialogue"
)


def render_static_weighted_list_eocs(
    effect: dict[str, Any],
    eoc_function_names: dict[str, str],
    actor_expression: str | None,
) -> list[str] | None:
    """Keep fail-closed until the native modulo RNG and copied dialogue can match."""
    del effect, eoc_function_names, actor_expression
    return None


def render_static_spawn_item_effect(
    effect: dict[str, Any], avatar_actor_proven: bool,
) -> list[str] | None:
    """Keep EOC forms of native ``receive_item`` out of migration.

    Direct TALK singleton responses have a callback-scoped operation that
    retains native dialogue alpha/beta and response phase. EOC callbacks do not
    carry that Dialogue; general inventory insertion also does not preserve
    ``i_add_or_drop`` behavior, default ammo, spawn location, popup, or the
    count/group/container/flags/force-equip branches. Keep all EOC shapes TODO.
    """
    del effect, avatar_actor_proven
    return None


def render_static_map_spawn_item_effect(
    effect: dict[str, Any], live_avatar_actor_proven: bool,
    actor_expression: str | None,
) -> list[str] | None:
    """Lower only direct map spawns at a source-proven loaded Avatar position.

    Native ``map_spawn_item`` defaults to dialogue alpha's current absolute
    map-square position.  The bounded caller proof is the unreferenced,
    event-exclusive ``game_start`` Avatar: ``game::start_game`` loads the map
    and places the player before ``on_world_ready`` and the event send.  It is
    further restricted to the first EOC effect so prior Lua cannot relocate
    the Avatar or unload the map.  The world service accepts only loaded
    absolute map-square coordinates; off-screen tinymap writes, item groups,
    containers, flags, dynamic ids, and dynamic quantities remain TODOs.
    """
    item_id = effect.get("map_spawn_item")
    quantity = _literal_integer_or_none(
        effect.get("count", 1), 1, 100
    )
    if (
        not live_avatar_actor_proven or actor_expression != "actor" or
        set(effect) - {"map_spawn_item", "count", "//~"} or
        "loc" in effect or
        "//~" in effect and not isinstance(effect["//~"], str) or
        not bounded_utf8_string(item_id, PLATFORM_ID_MAX_BYTES) or
        quantity is None
    ):
        return None
    position = (
        "service_value(services.characters.snapshot(actor))"
        ".creature.position"
    )
    return [
        "    service_value(services.world.spawn_item("
        f"{position}, services.types.id(\"item\", {lua_quote(item_id)}), "
        f"{quantity}))"
    ]


def render_participant_string(value: Any, target: str, alpha: str | None, beta: str | None) -> str | None:
    if isinstance(value, dict) and value.get("i18n") is True and "str" in value:
        if set(value) - {"str", "i18n", "//~"} or not isinstance(value["str"], str):
            return None
        return render_participant_translation_expression(value, target, alpha, beta)
    if isinstance(value, dict) and value.get("mutator") == "topic_item":
        if (set(value) - {"mutator", "//~"} or
                "//~" in value and not isinstance(value["//~"], str)):
            return None
        # EOC actions run from copied dialogue state, which has no current
        # topic item.  Preserve native ``d.cur_item.str()`` semantics instead
        # of reading a live dialogue or an unrelated Platform context field.
        return lua_quote("")
    if isinstance(value, dict) and value.get("mutator") == "game_option":
        if set(value) != {"mutator", "option"}:
            return None
        option = render_participant_string(value["option"], target, alpha, beta)
        if option is None:
            return None
        return (
            '(function(option) if option == nil then error("unknown game option") end; '
            'if option.type ~= "string_select" and option.type ~= "string_input" then '
            'error("string game option required") end; return option.value end)'
            f'(services.gameplay.options.get({option}))'
        )
    if isinstance(value, dict) and value.get("mutator") in {
            "mon_faction", "ma_technique_name", "ma_technique_description"}:
        monster = value["mutator"] == "mon_faction"
        key = "mtype_id" if monster else "matec_id"
        if set(value) != {"mutator", key}:
            return None
        identifier = render_participant_string(value[key], target, alpha, beta)
        if identifier is None:
            return None
        if monster:
            return (
                '(function(definition) if definition == nil then '
                'error("unknown monster definition") end; return definition.default_faction.value end)'
                f'(services.registry.get("monster", {identifier}))'
            )
        field = "name" if value["mutator"] == "ma_technique_name" else "flavor_description"
        return ('services.martial_arts.technique_definition('
                f'services.types.id("martial_art_technique", {identifier})).{field}')
    if isinstance(value, dict) and value.get("mutator") == "valid_technique":
        if (set(value) - {"mutator", "blacklist", "crit", "dodge_counter", "block_counter"} or
                alpha is None or beta is None):
            return None
        options = []
        for source, name in (("crit", "critical"), ("dodge_counter", "dodge_counter"),
                             ("block_counter", "block_counter")):
            flag = value.get(source, False)
            if not isinstance(flag, bool):
                return None
            if flag:
                options.append(f"{name} = true")
        blacklist = value.get("blacklist", [])
        if not isinstance(blacklist, list):
            return None
        entries = [render_participant_string(
            entry, target, alpha, beta) for entry in blacklist]
        if any(entry is None for entry in entries):
            return None
        if entries:
            options.append("blacklist = { " + ", ".join(entries) + " }")
        rendered_options = "{ " + ", ".join(options) + " }"
        # Native always selects for dialogue alpha against beta, regardless
        # of the variable destination or the surrounding effect's target.
        return (
            'service_value(services.characters.choose_technique('
            f'{alpha}, {beta}, {rendered_options})).technique.value'
        )
    source = target
    if isinstance(value, dict):
        if "u_val" in value:
            source = alpha
        elif "npc_val" in value:
            source = beta
    if source is None:
        return None
    mutation = render_eoc_string_expression(value, source)
    if isinstance(value, dict):
        descriptors = set(value) - {"default"}
        if len(descriptors) == 1 and next(iter(descriptors)) in {
                "u_val", "npc_val", "context_val", "global_val", "var_val"}:
            descriptor = next(iter(descriptors))
            name = value[descriptor]
            valid_name = (
                bounded_platform_context_variable_key(name)
                if descriptor == "var_val" else
                lua_quotable_native_variable_string(name)
            )
            if not valid_name:
                return None
            fallback = value.get("default", "")
            if not isinstance(fallback, str):
                return None
            if descriptor == "context_val":
                mutation = (
                    '(function(stored) if stored == nil then return ' + lua_quote(fallback) +
                    ' end; if type(stored) == "string" then return stored end; return "" end)'
                    '(context and context.data and context.data[' + lua_quote(name) + '])'
                )
            else:
                scope = descriptor.removesuffix("_val")
                mutation = (
                    '(function(snapshot) if not snapshot.exists then return ' + lua_quote(fallback) +
                    ' end; if type(snapshot.value) == "string" then return snapshot.value end; return "" end)'
                    '(service_value(services.variables.resolve(context.data, nil, ' + lua_quote(scope) +
                    ', ' + lua_quote(name) + ', {alpha=' + (alpha or "nil") + ', beta=' + (beta or "nil") + '})))'
                )
    return mutation


def render_mutation_action(effect: Any, alpha: str | None, beta: str | None) -> list[str] | None:
    if not isinstance(effect, dict):
        return None
    keys = set(effect) & {"u_activate_trait", "npc_activate_trait", "u_deactivate_trait", "npc_deactivate_trait",
                          "u_lose_trait", "npc_lose_trait", "u_add_trait", "npc_add_trait"}
    if len(keys) != 1:
        return None
    key = next(iter(keys))
    allowed = {key, "variant"} if key.endswith("_add_trait") else {key}
    if set(effect) - allowed:
        return None
    value = effect[key]
    target = beta if key.startswith("npc_") else alpha
    if target is None:
        return None
    mutation = render_participant_string(value, target, alpha, beta)
    if mutation is None:
        return None
    if key.endswith("_add_trait"):
        variant = render_participant_string(effect.get("variant", ""), target, alpha, beta)
        if variant is None:
            return None
        return ["    service_value(services.mutations.replace(",
                f'        {target}, services.types.id("mutation", {mutation}), {variant}))']
    if key.endswith("_lose_trait"):
        return ["    service_value(services.mutations.erase(",
                f'        {target}, services.types.id("mutation", {mutation})))']
    active = key.endswith("_activate_trait")
    return ["    service_value(services.mutations.invoke_activation(",
            f'        {target}, services.types.id("mutation", {mutation}), {lua_boolean(active)}))']


def mutation_migration_gap(effect: Any) -> str | None:
    """Explain a missing target or parameter shape after action rendering fails."""
    if isinstance(effect, dict) and any(
            prefix + operation in effect for prefix in ("u_", "npc_")
            for operation in ("add_trait", "lose_trait", "activate_trait", "deactivate_trait")):
        return "resolve an exact Character target and supported mutation ID/variant expressions"
    return None


def render_static_sound_effect(effect: dict[str, Any]) -> list[str] | None:
    if (
        set(effect) - {"sound_effect", "id", "volume", "outdoor_event"} or
        not {"sound_effect", "id"} <= set(effect) or
        not bounded_utf8_string(effect.get("id"), 128) or
        not bounded_utf8_string(effect.get("sound_effect"), 128)
    ):
        return None
    raw_volume = effect.get("volume", -1)
    # Native f_sound_effect treats -1 (including its default) as the
    # context-sensitive default: 80 indoors/on the surface and 80 * hearing
    # underground for outdoor_event.  This bounded migration only covers the
    # context-independent branch below, so lower the sentinel to 80 there.
    volume = (
        80 if raw_volume == -1 else
        _literal_nonnegative_integer(raw_volume, 128)
    )
    outdoor = effect.get("outdoor_event", False)
    # The existing generic Platform play_from_outdoors service uses a
    # positive-depth attenuation policy, while native EOC code computes its
    # probability from the signed absolute z level.  Keep that shape visible
    # as a migration TODO until the public service contract is reconciled.
    # For the supported indoor/default branch, the Platform service's random
    # angle is audio-only but comes from the runtime RNG rather than native
    # random_direction(); this is not exact native RNG-sequence parity.
    if volume is None or not isinstance(outdoor, bool) or outdoor:
        return None
    return [
        f"    services.sound.play_if_audible({lua_quote(effect['id'])}, "
        f"{lua_quote(effect['sound_effect'])}, {volume})"
    ]


def _effect_part_expression(raw_expression: str) -> str:
    """Resolve native Character part sentinels after evaluating a string."""
    return (
        '(function(part) if part == "bp_null" then return nil '
        'elseif part == "RANDOM" then return service_value('
        'services.characters.random_body_part(services.characters.avatar(), true)) '
        'else return services.types.id("body_part", part) end end)(' +
        raw_expression + ')'
    )


def render_static_remove_effects(
    effect: dict[str, Any], key: str, target_expression: str | None,
    *, avatar_expression: str | None = None, npc_expression: str | None = None,
    character_target_proven: bool | None = True,
    target_kind: str | None = "character",
) -> list[str] | None:
    if target_expression is None or key not in effect or target_kind not in {
        "character", "monster", "creature",
    }:
        return None
    if set(effect) - {key, "target_part"}:
        return None
    alpha = avatar_expression or (target_expression if key.startswith("u_") else None)
    beta = npc_expression or (target_expression if key.startswith("npc_") else None)

    def identifier(value: Any, kind: str) -> str | None:
        if isinstance(value, dict):
            raw = render_participant_string_expression(value, target_expression, alpha, beta)
            return None if raw is None else f'services.types.id("{kind}", {raw})'
        return _dynamic_id_expression(value, kind, target_expression)

    raw_ids = effect[key]
    # Native f_remove_effect only populates its vector for a string or array.
    # A standalone variable object is ignored natively; translating it would
    # activate a removal that never happened. Leave it for explicit review.
    if not isinstance(raw_ids, (str, list)):
        return None
    if isinstance(raw_ids, list):
        # Native f_remove_effect accepts an empty vector and imposes no list
        # limit. Emit separate calls to preserve order and repeated removals.
        effect_ids = [
            identifier(value, "effect")
            for value in raw_ids
        ]
        if any(value is None for value in effect_ids):
            return None
    else:
        effect_id = identifier(raw_ids, "effect")
        if effect_id is None:
            return None
        effect_ids = [effect_id]
    if effect.get("target_part") == "ALL" and character_target_proven is not False:
        if not effect_ids:
            return []
        rendered = ["    do"]
        if character_target_proven is None:
            # An event beta or caller-supplied Creature need not be a Character.
            # Native monster talkers expose no body parts to ALL removal.
            rendered.extend([
                "        local parts = {}",
                f"        local target_kind = service_value(services.creatures.snapshot({target_expression})).kind",
                '        if target_kind == "avatar" or target_kind == "npc" then',
                f"            parts = service_value(services.characters.body_parts({target_expression}))",
                "        end",
            ])
        else:
            rendered.append(
                f"        local parts = service_value(services.characters.body_parts({target_expression}))")
        for effect_id in effect_ids:
            rendered.extend([
                "        for _, part in ipairs(parts) do",
                f"            service_value(services.effects.remove({target_expression}, {effect_id}, part))",
                "        end",
                f"        service_value(services.effects.remove({target_expression}, {effect_id}))",
            ])
        return rendered + ["    end"]
    raw_part = effect.get("target_part")
    if raw_part is None or raw_part in ("ALL", "bp_null"):
        part_expression = None
    elif raw_part == "RANDOM":
        # Native talker_character uses the actual game player, independently
        # of both dialogue participants.
        part_expression = "service_value(services.characters.random_body_part(services.characters.avatar(), true))"
    elif isinstance(raw_part, dict):
        raw_expression = render_participant_string_expression(raw_part, target_expression, alpha, beta)
        if raw_expression is None:
            return None
        part_expression = _effect_part_expression(raw_expression)
    else:
        part_expression = identifier(raw_part, "body_part")
        if part_expression is None:
            return None
    rendered: list[str] = []
    for effect_id in effect_ids:
        suffix = (
            f", {part_expression}" if part_expression is not None else ""
        )
        rendered.append(
            f"    service_value(services.effects.remove("
            f"{target_expression}, {effect_id}{suffix}))"
        )
    if isinstance(raw_part, dict):
        # Native first evaluates the string to select ALL, then reevaluates it
        # for each non-ALL removal. Keep those reads and per-part ID evaluation.
        all_lines = render_static_remove_effects(
            {key: raw_ids, "target_part": "ALL"}, key, target_expression,
            avatar_expression=alpha, npc_expression=beta,
            character_target_proven=character_target_proven,
            target_kind=target_kind,
        )
        assert all_lines is not None
        return (
            [f'    if {raw_expression} == "ALL" then'] +
            ["    " + line for line in all_lines] + ["    else"] +
            ["    " + line for line in rendered] + ["    end"]
        )
    return rendered


def render_static_false_effect(
    effect: Any,
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
    eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
    actor_expression: str | None = None,
    eoc_conditions: dict[str, Any] | None = None,
    creature_actor_proven: bool = False,
    npc_actor_expression: str | None = None,
    effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    character_effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    sell_item_pair_proven: bool = False,
    wound_actor_targets: dict[str, str | None] | None = None,
    known_body_part_ids: frozenset[str] = frozenset(),
    known_wound_ids: frozenset[str] = frozenset(),
    field_avatar_center_proven: bool = False,
) -> list[str] | None:
    """Render source-proven effects inside ordinary Lua control flow.

    Nested branches and loops retain their caller's participant proofs.
    Unsupported shapes remain visible migration TODOs instead of being
    silently discarded or routed through a second EOC handler.
    """
    if isinstance(effect, dict) and "foreach" in effect:
        return render_static_foreach(
            effect, avatar_actor_proven, npc_actor_proven,
            eoc_function_names, eoc_actor_requirements,
            actor_expression, eoc_conditions, npc_actor_expression,
            effect_actor_targets, character_effect_actor_targets,
            wound_actor_targets=wound_actor_targets,
            known_body_part_ids=known_body_part_ids,
            known_wound_ids=known_wound_ids,
            field_avatar_center_proven=field_avatar_center_proven,
        )
    activation = render_mutation_action(
        effect, (actor_expression or "actor") if avatar_actor_proven else None,
        npc_actor_expression or ((actor_expression or "actor") if npc_actor_proven else None))
    if activation is not None:
        return activation
    if mutation_migration_gap(effect) is not None:
        return None
    if effect == "nothing":
        return []
    if effect == "u_cancel_activity" and avatar_actor_proven:
        return [f"        services.activities.cancel({actor_expression or 'actor'})"]
    if effect == "npc_cancel_activity" and (npc_actor_proven or npc_actor_expression is not None):
        target = npc_actor_expression or actor_expression or "actor"
        return [f"        services.activities.cancel({target})"]
    if isinstance(effect, dict) and "u_spawn_item" in effect:
        rendered = render_static_spawn_item_effect(
            effect, avatar_actor_proven
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and any(key in effect for key in {
        "wield", "wear", "takeoff", "unequip",
        "u_wield", "u_wear", "u_takeoff", "u_unequip",
        "npc_wield", "npc_wear", "npc_takeoff", "npc_unequip",
    }):
        rendered = render_static_equipment_effect(
            effect, avatar_actor_proven, npc_actor_proven, actor_expression
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_remove_item_with" in effect or "npc_remove_item_with" in effect
    ):
        key = (
            "u_remove_item_with"
            if "u_remove_item_with" in effect else "npc_remove_item_with"
        )
        actor_proven = (
            avatar_actor_proven if key.startswith("u_") else npc_actor_proven
        )
        rendered = render_static_remove_item_with_effect(
            effect, key, actor_proven, "actor"
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_spawn_monster" in effect or "npc_spawn_monster" in effect
    ):
        key = (
            "u_spawn_monster"
            if "u_spawn_monster" in effect else "npc_spawn_monster"
        )
        rendered = render_static_spawn(
            effect, key, "monster", avatar_actor_proven, npc_actor_proven,
            eoc_function_names, npc_actor_expression,
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_consume_item" in effect or "npc_consume_item" in effect
    ):
        key = (
            "u_consume_item"
            if "u_consume_item" in effect else "npc_consume_item"
        )
        rendered = render_static_inventory_consume(
            effect, key, avatar_actor_proven, npc_actor_proven
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_learn_recipe" in effect or "npc_learn_recipe" in effect or
        "u_forget_recipe" in effect or "npc_forget_recipe" in effect
    ):
        key = next(name for name in (
            "u_learn_recipe", "npc_learn_recipe",
            "u_forget_recipe", "npc_forget_recipe",
        ) if name in effect)
        target = _eoc_actor_expression(
            key, avatar_actor_proven, npc_actor_proven
        )
        rendered = render_dynamic_simple_character_effect(
            effect, key, target
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "alter_timed_events" in effect:
        rendered = render_static_timed_event_reschedule(effect)
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "u_sell_item" in effect:
        rendered = render_static_sell_item_effect(
            effect,
            ( actor_expression or "actor" ) if sell_item_pair_proven else None,
            "context.actors.interlocutor" if sell_item_pair_proven else None,
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_roll_remainder" in effect or "npc_roll_remainder" in effect
    ):
        key = (
            "u_roll_remainder"
            if "u_roll_remainder" in effect else "npc_roll_remainder"
        )
        rendered = render_static_roll_remainder_effect(
            effect, key, avatar_actor_proven, npc_actor_proven,
            eoc_function_names,
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_transform_radius" in effect or "npc_transform_radius" in effect
    ):
        key = (
            "u_transform_radius"
            if "u_transform_radius" in effect else "npc_transform_radius"
        )
        rendered = render_static_transform_radius(
            effect, key, event_exclusive_live_avatar_actor_proven=False
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "sound_effect" in effect:
        rendered = render_static_sound_effect(effect)
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_lose_effect" in effect or "npc_lose_effect" in effect
    ):
        key = (
            "u_lose_effect" if "u_lose_effect" in effect
            else "npc_lose_effect"
        )
        target_map = character_effect_actor_targets or effect_actor_targets
        target_kind: str | None = None
        if target_map is None:
            target = _eoc_actor_expression(
                key, avatar_actor_proven, npc_actor_proven
            )
            if target is None and key == "u_lose_effect" and creature_actor_proven:
                target = actor_expression or "actor"
            target_kind = (
                "monster" if creature_actor_proven and not avatar_actor_proven
                else "character" if target is not None else None
            )
        else:
            target_info = target_map["npc" if key.startswith("npc_") else "u"]
            target = target_info[0] if target_info is not None else None
            target_kind = target_info[1] if target_info is not None else None
        alpha = (
            target if key.startswith("u_") and target_map is not None else
            (actor_expression or "actor") if avatar_actor_proven else None
        )
        beta = (
            target if key.startswith("npc_") and target_map is not None else
            npc_actor_expression or ("actor" if npc_actor_proven else None)
        )
        if target_map is None and key == "npc_lose_effect":
            target = beta
        elif target_map is None and alpha is not None:
            target = alpha
        if target_map is None and target_kind is None and target is not None:
            target_kind = (
                "monster" if creature_actor_proven and not avatar_actor_proven
                else "character"
            )
        rendered = render_static_remove_effects(
            effect, key, target, avatar_expression=alpha, npc_expression=beta,
            character_target_proven=(
                None if target_kind == "creature" else target_kind == "character"
            ),
            target_kind=target_kind,
        )
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "weighted_list_eocs" in effect:
        rendered = render_static_weighted_list_eocs(
            effect, eoc_function_names, actor_expression
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_deal_damage" in effect or "npc_deal_damage" in effect
    ):
        key = "u_deal_damage" if "u_deal_damage" in effect else "npc_deal_damage"
        dynamic_shape = (
            not isinstance(effect.get(key), str) or
            finite_number_literal(effect.get("amount")) is None or
            any(
                name in effect and finite_number_literal(effect[name]) is None
                for name in ("arpen", "arpen_mult", "dmg_mult", "min_hit", "max_hit", "hit_roll")
            ) or
            "bodypart" in effect and not safe_platform_id(effect.get("bodypart"))
        )
        if dynamic_shape:
            rendered = render_dynamic_combat_damage(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        target = _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
        if target is None:
            return None
        allowed = {
            key, "amount", "bodypart", "arpen", "arpen_mult", "dmg_mult",
            "min_hit", "max_hit", "hit_roll", "can_attack_high",
        }
        if set(effect) - allowed or not safe_platform_id(effect.get(key)):
            return None
        amount = finite_number_literal(effect.get("amount"))
        if (
            amount is None or
            not -MAX_CHARACTER_DAMAGE <= float(amount) <= MAX_CHARACTER_DAMAGE
        ):
            return None
        options: list[str] = []
        for legacy_name, lua_name in (
            ("arpen", "armor_penetration"),
            ("arpen_mult", "armor_penetration_multiplier"),
            ("dmg_mult", "damage_multiplier"),
        ):
            if legacy_name not in effect:
                continue
            number = finite_number_literal(effect[legacy_name])
            minimum = (
                -MAX_CHARACTER_DAMAGE
                if legacy_name == "arpen"
                else -MAX_CHARACTER_DAMAGE_MULTIPLIER
            )
            maximum = (
                MAX_CHARACTER_DAMAGE
                if legacy_name == "arpen"
                else MAX_CHARACTER_DAMAGE_MULTIPLIER
            )
            if number is None or not minimum <= float(number) <= maximum:
                return None
            options.append(f"{lua_name} = {lua_number(number)}")
        for name in ("min_hit", "max_hit", "hit_roll"):
            if name not in effect:
                continue
            number = effect[name]
            if (
                not isinstance(number, int) or isinstance(number, bool) or
                not -MAX_CHARACTER_HIT_OPTION <= number <= MAX_CHARACTER_HIT_OPTION or
                name in {"min_hit", "max_hit"} and number < -1
            ):
                return None
            options.append(f"{name} = {number}")
        if (
            "min_hit" in effect and "max_hit" in effect and
            effect["max_hit"] != -1 and effect["max_hit"] < effect["min_hit"]
        ):
            return None
        if "can_attack_high" in effect:
            if not isinstance(effect["can_attack_high"], bool):
                return None
            options.append(
                f"can_attack_high = {lua_boolean(effect['can_attack_high'])}"
            )
        lines = [
            "    services.characters.damage(",
            f"        {target}, services.types.id(\"damage_type\", "
            f"{lua_quote(effect[key])}), {lua_number(amount)},",
        ]
        if options:
            lines.append("        { " + ", ".join(options) + " })")
        else:
            lines[-1] += ")"
        return [line.replace("    ", "        ", 1) for line in lines]
    if isinstance(effect, dict) and (
        "u_make_sound" in effect or "npc_make_sound" in effect
    ):
        key = "u_make_sound" if "u_make_sound" in effect else "npc_make_sound"
        rendered = render_static_character_sound(
            effect, key, avatar_actor_proven, effect_actor_targets,
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_set_field" in effect or "npc_set_field" in effect
    ):
        key = "u_set_field" if "u_set_field" in effect else "npc_set_field"
        rendered = render_static_set_field(
            effect, key, avatar_actor_proven, npc_actor_proven,
            event_exclusive_live_avatar_center_proven=field_avatar_center_proven,
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and any(
        key in effect for key in (
            "u_attack", "npc_attack", "u_knockback", "npc_knockback",
            "u_explosion", "npc_explosion", "u_emit", "npc_emit",
            "u_cast_spell", "npc_cast_spell", "u_die", "npc_die",
        )
    ):
        key = next(key for key in (
            "u_attack", "npc_attack", "u_knockback", "npc_knockback",
            "u_explosion", "npc_explosion", "u_emit", "npc_emit",
            "u_cast_spell", "npc_cast_spell", "u_die", "npc_die",
        ) if key in effect)
        rendered = None
        if key in {"u_attack", "npc_attack"}:
            rendered = render_static_combat_attack(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        elif key in {"u_knockback", "npc_knockback"}:
            rendered = render_static_combat_knockback(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        elif key in {"u_explosion", "npc_explosion"}:
            rendered = render_static_combat_explosion(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        elif key in {"u_emit", "npc_emit"}:
            rendered = render_static_combat_emit(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        elif key in {"u_cast_spell", "npc_cast_spell"}:
            rendered = render_static_combat_cast_spell(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        elif key in {"u_die", "npc_die"}:
            rendered = render_static_combat_die(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, str) and effect in {
        "u_ranged_attack", "npc_ranged_attack",
        "u_prevent_death", "npc_prevent_death", "u_die", "npc_die",
    }:
        rendered = None
        if effect in {"u_ranged_attack", "npc_ranged_attack"}:
            rendered = render_static_combat_ranged_attack(
                effect, effect, avatar_actor_proven, npc_actor_proven
            )
        elif effect in {"u_prevent_death", "npc_prevent_death"}:
            rendered = render_static_combat_prevent_death(
                effect, effect, avatar_actor_proven, npc_actor_proven
            )
        else:
            rendered = render_static_combat_die(
                effect, effect, avatar_actor_proven, npc_actor_proven
            )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_teleport" in effect or "npc_teleport" in effect
    ):
        rendered = render_static_teleport_effect(
            effect,
            monster_actor_proven=False,
            avatar_actor_proven=False,
            vehicle_actor_proven=False,
            npc_actor_proven=False,
            npc_actor_expression=None,
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "message" in effect:
        rendered = render_message_effect(effect, "message", "actor")
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "u_message" in effect:
        if not avatar_actor_proven:
            return None
        target = "actor"
        rendered = render_message_effect(effect, "u_message", target)
        if rendered is not None:
            return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "run_eocs" in effect:
        rendered = render_static_run_eocs(
            effect, eoc_function_names, eoc_actor_requirements,
            actor_expression,
            character_actor_proven=(
                avatar_actor_proven or npc_actor_proven
            ),
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if effect == "open_dialogue" or (
        isinstance(effect, dict) and "open_dialogue" in effect
    ):
        # The native explicit-topic path opens a topic-list talker without an
        # NPC beta and runs its true_eocs after the UI; the no-topic path clones
        # actor(true). Platform's NPC service instead requires an exact NPC,
        # avatar, and topic and opens an NPC-bound conversation. Neither native
        # shape can be replaced by that call or inherit its EOC context.
        return None
    if isinstance(effect, dict) and "transform_item" in effect:
        rendered = render_dynamic_item_transform_effect(effect, actor_expression)
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "mapgen_update" in effect:
        rendered = render_static_mapgen_update(
            effect, avatar_actor_proven, npc_actor_proven
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "give_achievement" in effect:
        if (
            set(effect) != {"give_achievement"} or
            not safe_platform_id(effect.get("give_achievement"))
        ):
            return None
        return [
            "        do",
            "            local achievement_id = services.types.id(\"achievement\", "
            f"{lua_quote(effect['give_achievement'])})",
            "            if achievement_id:is_valid() then",
            "                services.achievements.complete(achievement_id)",
            "            end",
            "        end",
        ]
    if isinstance(effect, dict) and "copy_var" in effect:
        rendered = render_static_character_copy_var(
            effect, effect_actor_targets
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and "set_string_var" in effect:
        rendered = render_static_character_string_var(
            effect, effect_actor_targets,
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and (
        "u_location_variable" in effect or
        "npc_location_variable" in effect
    ):
        key = (
            "u_location_variable"
            if "u_location_variable" in effect else "npc_location_variable"
        )
        rendered = render_dynamic_location_variable_search(
            effect, key, avatar_actor_proven, npc_actor_proven,
            eoc_function_names,
        )
        if rendered is None:
            rendered = render_static_location_variable(
                effect, key, avatar_actor_proven, npc_actor_proven
            )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and any(
        key in effect for key in (
            "u_run_npc_eocs", "npc_run_npc_eocs",
            "u_run_inv_eocs", "npc_run_inv_eocs",
            "u_run_monster_eocs", "npc_run_monster_eocs",
            "u_run_vehicle_eocs", "npc_run_vehicle_eocs",
            "u_run_fixed_zone_eocs", "npc_run_fixed_zone_eocs",
            "u_map_run_eocs", "npc_map_run_eocs",
            "u_map_run_item_eocs", "npc_map_run_item_eocs",
        )
    ):
        key = next(key for key in (
            "u_run_npc_eocs", "npc_run_npc_eocs",
            "u_run_inv_eocs", "npc_run_inv_eocs",
            "u_run_monster_eocs", "npc_run_monster_eocs",
            "u_run_vehicle_eocs", "npc_run_vehicle_eocs",
            "u_run_fixed_zone_eocs", "npc_run_fixed_zone_eocs",
            "u_map_run_eocs", "npc_map_run_eocs",
            "u_map_run_item_eocs", "npc_map_run_item_eocs",
        ) if key in effect)
        rendered = render_static_traversal(
            effect, key, actor_expression, eoc_function_names
        )
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and ("u_add_var" in effect or "npc_add_var" in effect):
        key = "u_add_var" if "u_add_var" in effect else "npc_add_var"
        target = (
            _proven_character_variable_target(effect_actor_targets, key)
            if key == "npc_add_var" else
            _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
        )
        if key == "npc_add_var" and effect.get("time", False) is not True:
            return None
        rendered = render_static_character_variable(effect, key, target)
        if rendered is None:
            return None
        return [line.replace("    ", "        ", 1) for line in rendered]
    if isinstance(effect, dict) and set(effect) in ({"u_lose_var"}, {"npc_lose_var"}):
        key = next(iter(effect))
        target = (
            _proven_character_variable_target(effect_actor_targets, key)
            if key == "npc_lose_var" else
            _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
        )
        name = effect[key]
        if target is not None and lua_quotable_native_variable_string(name):
            return [
                f"        services.variables.remove({target}, {lua_quote(name)}, {{ include_before = false }})"
            ]
    if isinstance(effect, dict):
        key: str | None = next(
            (name for name in (
                "u_add_effect", "npc_add_effect", "u_add_wound", "npc_add_wound",
                "u_remove_wound", "npc_remove_wound",
            ) if name in effect),
            None,
        )
        if key is not None:
            target_kind: str | None = None
            effect_targets = character_effect_actor_targets or effect_actor_targets
            if "effect" in key and effect_targets is not None:
                target_info = effect_targets["npc" if key.startswith("npc_") else "u"]
                target = target_info[0] if target_info is not None else None
                target_kind = target_info[1] if target_info is not None else None
            else:
                target = _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
            if "effect" in key:
                alpha = (
                    target if key.startswith("u_") and effect_targets is not None else
                    (actor_expression or "actor") if avatar_actor_proven else None
                )
                beta = (
                    target if key.startswith("npc_") and effect_targets is not None else
                    npc_actor_expression or ("actor" if npc_actor_proven else None)
                )
                if effect_targets is None and key.startswith("npc_"):
                    target = npc_actor_expression or target
                elif effect_targets is None and alpha is not None:
                    target = alpha
                if target_kind is None and target is not None and effect_targets is None:
                    target_kind = (
                        "monster" if creature_actor_proven and not avatar_actor_proven
                        else "character"
                    )
                rendered = render_static_character_effect(
                    effect, key, target, target_kind=target_kind
                )
                if rendered is None:
                    rendered = render_dynamic_character_effect(
                        effect, key, target, avatar_expression=alpha,
                        npc_expression=beta,
                        target_kind=target_kind,
                    )
            elif "wound" in key:
                # The generic Character proof is weaker than the native wound
                # target proof. Use the same actor and registered-ID evidence
                # as the main effect, including inside ordinary Lua branches.
                wound_target = (
                    wound_actor_targets.get("npc" if key.startswith("npc_") else "u")
                    if wound_actor_targets is not None else None
                )
                rendered = render_static_character_wound(
                    effect, key, wound_target, key.endswith("remove_wound"),
                    known_body_part_ids, known_wound_ids,
                )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        key = next(
            (name for name in (
                "u_add_bionic", "npc_add_bionic",
                "u_lose_bionic", "npc_lose_bionic",
            ) if name in effect),
            None,
        )
        if key is not None:
            target = _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
            npc_target = npc_actor_expression or ("actor" if npc_actor_proven else None)
            if key.startswith("npc_"):
                target = npc_target
            rendered = render_dynamic_simple_character_effect(
                effect, key, target,
                avatar_expression="actor" if avatar_actor_proven else None,
                npc_expression=npc_target,
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        # The false branch is still a normal effect list.  Keep the common
        # arithmetic/control-flow and character mutations on the same typed
        # services as the owning EOC instead of dropping them behind a generic
        # TODO marker.
        if "math" in effect:
            rendered = render_static_character_math(
                effect, effect_actor_targets,
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        # Morale effects use the dialogue's mutable/const alpha-beta slots.
        # This helper is also used for conditional/foreach child effects and
        # receives broad actor facts rather than a source-specific dispatch
        # proof, so those shapes deliberately remain TODO here.
        if effect == "u_prevent_death" and avatar_actor_proven:
            return ["        services.characters.prevent_death(actor)"]
        comment_keys = {
            name for name in effect
            if isinstance(name, str) and name.startswith("//")
        }
        if (
            "turn_cost" in effect and
            set(effect) - comment_keys == {"turn_cost"} and
            avatar_actor_proven
        ):
            adjustment = parse_turn_cost_adjustment(effect["turn_cost"])
            if adjustment is not None:
                return [
                    "        services.characters.adjust(actor, "
                    f"{{ moves = {adjustment} }})",
                ]
        if "place_override" in effect:
            rendered = render_static_place_override(
                effect, "actor" if (avatar_actor_proven or npc_actor_proven) else None
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        if "custom_light_level" in effect:
            rendered = render_static_light_override(effect)
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        # A false-effect callback does not prove an exact Character target for
        # both participant slots.  Even the target-practice special case must
        # stay explicit until that branch has a source-specific actor proof.
        if "u_sell_item" in effect:
            rendered = render_static_sell_item_effect(
                effect,
                ( actor_expression or "actor" )
                if sell_item_pair_proven else None,
                "context.actors.interlocutor"
                if sell_item_pair_proven else None,
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        if "switch" in effect:
            rendered = render_static_switch_effect(
                effect, avatar_actor_proven, npc_actor_proven, False,
                eoc_function_names, eoc_actor_requirements,
                actor_expression, eoc_conditions,
                npc_actor_expression=npc_actor_expression,
                effect_actor_targets=effect_actor_targets,
                character_effect_actor_targets=character_effect_actor_targets,
                wound_actor_targets=wound_actor_targets,
                known_body_part_ids=known_body_part_ids,
                known_wound_ids=known_wound_ids,
                field_avatar_center_proven=field_avatar_center_proven,
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
        if "if" in effect and ({"then", "else"} & set(effect)):
            rendered = render_static_if_effect(
                effect, avatar_actor_proven, npc_actor_proven, False,
                eoc_function_names, eoc_actor_requirements, actor_expression,
                eoc_conditions, npc_actor_expression=npc_actor_expression,
                effect_actor_targets=effect_actor_targets,
                character_effect_actor_targets=character_effect_actor_targets,
                wound_actor_targets=wound_actor_targets,
                known_body_part_ids=known_body_part_ids,
                known_wound_ids=known_wound_ids,
                field_avatar_center_proven=field_avatar_center_proven,
            )
            if rendered is not None:
                return [line.replace("    ", "        ", 1) for line in rendered]
    return None


def render_dynamic_combat_damage(
    effect: dict[str, Any],
    key: str,
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Render bounded variable-backed ``u_/npc_deal_damage`` options."""
    if key not in effect or set(effect) - {
        key, "amount", "bodypart", "arpen", "arpen_mult", "dmg_mult",
        "min_hit", "max_hit", "hit_roll", "can_attack_high",
    }:
        return None
    actor = _eoc_actor_expression(key, avatar_actor_proven, npc_actor_proven)
    if actor is None:
        return None
    if "amount" not in effect:
        return None
    damage_type = _dynamic_id_expression(effect[key], "damage_type", actor)
    amount = _combat_number_expression(
        effect["amount"], actor,
        -MAX_CHARACTER_DAMAGE, MAX_CHARACTER_DAMAGE,
    )
    if damage_type is None or amount is None:
        return None
    options: list[str] = []
    if "bodypart" in effect:
        bodypart = _dynamic_id_expression(effect["bodypart"], "body_part", actor)
        if bodypart is None:
            return None
        options.append(f"body_part = {bodypart}")
    for source, target, minimum, maximum in (
        ("arpen", "armor_penetration", -MAX_CHARACTER_DAMAGE, MAX_CHARACTER_DAMAGE),
        (
            "arpen_mult", "armor_penetration_multiplier",
            -MAX_CHARACTER_DAMAGE_MULTIPLIER, MAX_CHARACTER_DAMAGE_MULTIPLIER,
        ),
        (
            "dmg_mult", "damage_multiplier",
            -MAX_CHARACTER_DAMAGE_MULTIPLIER, MAX_CHARACTER_DAMAGE_MULTIPLIER,
        ),
    ):
        if source not in effect:
            continue
        expression = _combat_number_expression(
            effect[source], actor, minimum, maximum
        )
        if expression is None:
            return None
        options.append(f"{target} = {expression}")
    hit_expressions: dict[str, str] = {}
    for name, minimum in (
        ("min_hit", -1), ("max_hit", -1),
        ("hit_roll", -MAX_CHARACTER_HIT_OPTION),
    ):
        if name not in effect:
            continue
        expression = _combat_number_expression(
            effect[name], actor, minimum, MAX_CHARACTER_HIT_OPTION,
            integer=True,
        )
        if expression is None:
            return None
        hit_expressions[name] = expression
    if "min_hit" in hit_expressions and "max_hit" in hit_expressions:
        minimum_expression = hit_expressions["min_hit"]
        maximum_expression = hit_expressions["max_hit"]
        # Native damage rejects max_hit < min_hit.  Keep dynamic ranges
        # executable by preserving the requested lower bound at runtime;
        # literal inverted ranges were already rejected by the static path.
        if not (
            minimum_expression.lstrip("-").isdigit() and
            maximum_expression.lstrip("-").isdigit()
        ):
            maximum_expression = (
                f"math.max({minimum_expression}, {maximum_expression})"
            )
        hit_expressions["max_hit"] = maximum_expression
    options.extend(
        f"{name} = {expression}"
        for name, expression in hit_expressions.items()
    )
    if "can_attack_high" in effect:
        value = effect["can_attack_high"]
        if not isinstance(value, bool):
            return None
        options.append(f"can_attack_high = {lua_boolean(value)}")
    lines = [
        "    services.characters.damage(",
        f"        {actor}, {damage_type}, {amount},",
    ]
    if options:
        lines.append("        { " + ", ".join(options) + " })")
    else:
        lines[-1] += ")"
    return lines


def render_message_effect(
    effect: dict[str, Any], key: str, actor_expression: str,
    dialogue_alpha_expression: str | None = None,
    dialogue_beta_expression: str | None = None,
) -> list[str] | None:
    """Render bounded static text with the native dialogue tag service."""
    comment_keys = {
        name for name in effect
        if isinstance(name, str) and name.startswith("//")
    }
    if key not in effect or set(effect) - comment_keys - {
        key, "popup", "type", "snippet", "same_snippet", "store_in_lore",
        "popup_w_interrupt_query", "interrupt_type", "popup_flag", "sound",
        "outdoor_only",
    }:
        return None
    popup = effect.get("popup", False)
    if not isinstance(popup, bool):
        return None
    snippet = effect.get("snippet", False)
    if not isinstance(snippet, bool):
        return None
    same_snippet = effect.get("same_snippet", False)
    store_in_lore = effect.get("store_in_lore", False)
    popup_w_interrupt_query = effect.get("popup_w_interrupt_query", False)
    sound = effect.get("sound", False)
    outdoor_only = effect.get("outdoor_only", False)
    if not all(
        isinstance(value, bool)
        for value in (same_snippet, store_in_lore, popup_w_interrupt_query,
                      sound, outdoor_only)
    ):
        return None
    if (same_snippet or store_in_lore) and not snippet:
        return None
    # The text service uses the real native dialogue parser, but the message
    # migration deliberately leaves explicit tags/snippets and dynamic text
    # manual until their RNG and variable semantics can be bounded.
    if (sound and outdoor_only) or snippet:
        return None
    raw_literal = effect[key]
    if (
        not bounded_utf8_string(raw_literal, 8192, allow_empty=True) or
        "<" in raw_literal or ">" in raw_literal or
        dialogue_alpha_expression is None or
        dialogue_beta_expression is None
    ):
        return None
    message_type = effect.get("type")
    if message_type is not None and not isinstance(message_type, str):
        return None
    if message_type is not None and message_type not in {
        "good", "bad", "mixed", "warning", "info", "neutral", "debug",
        "headshot", "critical", "grazing",
    }:
        return None
    interrupt_type = effect.get("interrupt_type", "default")
    if not isinstance(interrupt_type, str) or not bounded_utf8_string(
        interrupt_type, 128, allow_empty=False
    ):
        return None
    if popup_w_interrupt_query and interrupt_type != "portal_storm_popup":
        # Native f_message only implements the portal-storm query.  Other
        # values either produce a debug message or no query at all.
        return None
    if sound and (popup or popup_w_interrupt_query):
        # Native sound gating happens before popup and interruption UI.  The
        # Platform audibility helper emits a message, so it cannot guard UI
        # operations without changing behavior.
        return None
    popup_flag = effect.get("popup_flag")
    popup_flag = {
        # JSON dialogue uses the native PopupFlags spellings while the Lua
        # presentation service intentionally exposes short capability names.
        "PF_GET_KEY": "get_key",
        "PF_ON_TOP": "on_top",
        "PF_FULLSCREEN": "fullscreen",
    }.get(popup_flag, popup_flag)
    if popup_flag is not None and popup_flag not in {
        "get_key", "on_top", "fullscreen",
    }:
        return None
    translated = (
        f"services.translate({lua_quote(raw_literal)})"
    )
    expanded_message = (
        "service_value(services.text.expand_for("
        f"{translated}, {dialogue_alpha_expression}, "
        f"{dialogue_beta_expression}))"
    )
    if key in {"u_message", "npc_message"}:
        target = actor_expression.strip()
        if not target:
            return None
        lines = [
            f"    local message_target = {target}",
            '    if message_target ~= nil and message_target.kind == "creature" and '
            'message_target.subtype == "avatar" then',
            f"        local message_text = {expanded_message}",
        ]
        indent = "        "
    else:
        lines = [f"    local message_text = {expanded_message}"]
        indent = "    "
    message = "message_text"

    if popup:
        popup_call = {
            None: "ccb.presentation.notice",
            "get_key": "ccb.presentation.notice_any_key",
            "on_top": "ccb.presentation.notice_top",
            "fullscreen": "ccb.presentation.notice_large",
        }[popup_flag]
        lines.append(f"{indent}{popup_call}({message})")
        lines.append(f"{indent}services.activities.offer_interruption(\"\")")
    if popup_w_interrupt_query:
        lines.append(
            f"{indent}services.activities.offer_portal_storm_interruption({message})"
        )
    else:
        if sound:
            add_call = "services.messages.add_if_audible"
        elif message_type in (None, "neutral"):
            lines.append(f"{indent}services.message({message})")
            add_call = None
        else:
            add_call = "services.messages.add"
        if add_call is not None:
            type_argument = (
                f", {lua_quote(message_type)}"
                if message_type not in (None, "neutral") else ""
            )
            lines.append(f"{indent}{add_call}({message}{type_argument})")
    if key in {"u_message", "npc_message"}:
        lines.append("    end")
    return lines


def render_optional_npc_job(
    target: str, job: str, normal_return: str = "assignment_rejected",
) -> list[str]:
    """Native interactive jobs may return without assigning an activity."""
    return [
        f'    if ({target}) ~= nil and ({target}).kind == "creature" and ({target}).subtype == "npc" then',
        f"        local assignment = services.activities.assign_npc_job({target}, {lua_quote(job)})",
        f"        if not assignment.ok and assignment.error.code ~= {lua_quote(normal_return)} then",
        "            service_value(assignment)",
        "        end",
        "    end",
    ]


def render_static_foreach(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
    eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
    actor_expression: str | None = None,
    eoc_conditions: dict[str, Any] | None = None,
    npc_actor_expression: str | None = None,
    effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    character_effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    wound_actor_targets: dict[str, str | None] | None = None,
    known_body_part_ids: frozenset[str] = frozenset(),
    known_wound_ids: frozenset[str] = frozenset(),
    field_avatar_center_proven: bool = False,
) -> list[str] | None:
    """Lower the bounded registry/array ``foreach`` effect.

    Snapshot each native registry or dynamic string array before its body.
    Nested loops share dialogue variables, while their input snapshots remain
    lexical Lua locals. Unsupported body effects remain explicit migration gaps.
    """
    if "foreach" not in effect or set(effect) - {"foreach", "var", "target", "effect"}:
        return None
    variable = effect.get("var")
    if not isinstance(variable, dict) or len(variable) != 1:
        return None
    scope = next(iter(variable))
    if scope not in {"context_val", "global_val", "u_val", "npc_val", "var_val"}:
        return None
    name = variable[scope]
    if not bounded_utf8_string(name, 256 if scope == "context_val" else 128):
        return None
    owner = (actor_expression if avatar_actor_proven else None) if scope == "u_val" else (
        npc_actor_expression or (actor_expression if npc_actor_proven else None))
    if scope in {"u_val", "npc_val"} and owner is None:
        return None
    body = effect.get("effect", [])
    body = body if isinstance(body, list) else [body]
    target = effect.get("target")
    mode = effect.get("foreach")
    lines: list[str] = ["    context.actors = context.actors or {}"]

    def append_body(item_expression: str) -> bool:
        if scope == "context_val":
            lines.append(f"        context.data[{lua_quote(name)}] = {item_expression}")
        elif scope == "global_val":
            lines.append(f"        services.variables.set_global({lua_quote(name)}, {item_expression})")
        elif scope == "var_val":
            alpha = actor_expression if avatar_actor_proven else "nil"
            beta = npc_actor_expression or (actor_expression if npc_actor_proven else "nil")
            lines.append(
                "        service_value(services.variables.set_resolved(context.data, nil, \"var\", "
                f"{lua_quote(name)}, {item_expression}, {{alpha={alpha or 'nil'}, beta={beta or 'nil'}}}))"
            )
        else:
            lines.append(f"        services.variables.set({owner}, {lua_quote(name)}, {item_expression})")
        for nested in body:
            rendered = render_static_false_effect(
                nested, avatar_actor_proven, npc_actor_proven,
                eoc_function_names, eoc_actor_requirements,
                actor_expression, eoc_conditions,
                npc_actor_expression=npc_actor_expression,
                effect_actor_targets=effect_actor_targets,
                character_effect_actor_targets=character_effect_actor_targets,
                wound_actor_targets=wound_actor_targets,
                known_body_part_ids=known_body_part_ids,
                known_wound_ids=known_wound_ids,
                field_avatar_center_proven=field_avatar_center_proven,
            )
            if rendered is None:
                return False
            lines.extend(line.replace("    ", "        ", 1) for line in rendered)
        return True

    def append_paged_loop(
        page_expression: str, entries_field: str, item_expression: str,
    ) -> bool:
        lines.extend([
            "    local foreach_values = {}",
            "    local foreach_offset = 0",
            "    while true do",
            f"        local foreach_page = {page_expression}",
            f"        for _, entry in ipairs(foreach_page.{entries_field}) do",
        ])
        lines.append(f"            foreach_values[#foreach_values + 1] = {item_expression}")
        lines.extend([
            "        end",
            "        if not foreach_page.has_more or foreach_page.returned == 0 then",
            "            break",
            "        end",
            "        foreach_offset = foreach_offset + foreach_page.returned",
            "    end",
        ])
        lines.append("    for _, entry in ipairs(foreach_values) do")
        if not append_body("entry"):
            return False
        lines.append("    end")
        return True

    if mode == "array":
        if not isinstance(target, list):
            return None
        values: list[str] = []
        for value in target:
            if isinstance(value, str):
                rendered_value = lua_scalar_literal(value)
            elif isinstance(value, dict) and (
                    set(value) - {"default"} in (
                        {"u_val"}, {"npc_val"}, {"context_val"}, {"global_val"}, {"var_val"}) or
                    (value.get("i18n") is True and "str" in value) or
                    value.get("mutator") in {
                        "game_option", "mon_faction", "ma_technique_name", "ma_technique_description",
                        "valid_technique"}):
                rendered_value = render_participant_string(
                    value, actor_expression or "nil",
                    actor_expression if avatar_actor_proven else None,
                    npc_actor_expression or (actor_expression if npc_actor_proven else None),
                )
            else:
                return None
            if rendered_value is None:
                return None
            values.append(rendered_value)
        # Native foreach evaluates the entire input before running any effects.
        lines.append("    local foreach_values = {}")
        lines.extend(f"    foreach_values[{index}] = {value}"
                     for index, value in enumerate(values, 1))
        lines.append("    for _, entry in ipairs(foreach_values) do")
        if not append_body("entry"):
            return None
        lines.append("    end")
        return lines

    if not isinstance(target, str) or not bounded_platform_id(target):
        return None
    if mode == "ids":
        registry_kinds = {
            "bodypart": "body_part",
            "flag": "json_flag",
        }
        definition_sources = {
            "trait": "services.mutations.definitions",
            "vitamin": "services.vitamins.definitions",
        }
        if target in registry_kinds:
            page_expression = (
                f"services.registry.list({lua_quote(registry_kinds[target])}, "
                '{ offset = foreach_offset, limit = 256, order = "native" })'
            )
            return (
                lines if append_paged_loop(page_expression, "entries", "entry.id")
                else None
            )
        if target in definition_sources:
            order = ', order = "native"'
            page_expression = (
                f"{definition_sources[target]}"
                f"({{ offset = foreach_offset, limit = 256{order} }})"
            )
            return (
                lines if append_paged_loop(page_expression, "items", "entry.id.value")
                else None
            )
        return None
    if mode == "item_group":
        lines.append(
            "    local foreach_page = services.items.possible_from_group("
            f"services.types.id(\"item_group\", {lua_quote(target)}), "
            '{ order = "native" })'
        )
        lines.append("    for _, entry in ipairs(foreach_page.items) do")
        if not append_body("entry.value"):
            return None
        lines.append("    end")
        return lines
    if mode == "monstergroup":
        page_expression = (
            "services.hordes.monsters("
            f"services.types.id(\"monster_group\", {lua_quote(target)}), "
            'true, { offset = foreach_offset, limit = 256, order = "native" })'
        )
        return (
            lines if append_paged_loop(page_expression, "items", "entry.value")
            else None
        )
    return None


def contains_open_dialogue_effect(value: Any) -> bool:
    """Return whether an effect branch retains legacy open_dialogue."""
    if value == "open_dialogue":
        return True
    if isinstance(value, list):
        return any(contains_open_dialogue_effect(entry) for entry in value)
    if not isinstance(value, dict):
        return False
    if "open_dialogue" in value:
        return True
    return any(
        contains_open_dialogue_effect(value[key])
        for key in ("then", "else")
        if key in value
    )


def render_static_if_effect(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
    creature_actor_proven: bool,
    eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
    actor_expression: str | None = None,
    eoc_conditions: dict[str, Any] | None = None,
    npc_actor_expression: str | None = None,
    effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    character_effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    wound_actor_targets: dict[str, str | None] | None = None,
    known_body_part_ids: frozenset[str] = frozenset(),
    known_wound_ids: frozenset[str] = frozenset(),
    field_avatar_center_proven: bool = False,
) -> list[str] | None:
    """Lower an ``if/then/else`` made solely of simple Lua-native effects."""
    if (
        set(effect) - {"if", "then", "else", "//"} or
        "if" not in effect or
        not ({"then", "else"} & set(effect))
    ):
        return None
    condition = render_eoc_condition_expression(
        effect["if"], avatar_actor_proven, avatar_actor_proven or npc_actor_proven,
        npc_actor_proven, creature_actor_proven, eoc_conditions,
        npc_actor_expression=npc_actor_expression,
    )
    if condition is None:
        return None
    then_value = effect.get("then", [])
    then_values = then_value if isinstance(then_value, list) else [then_value]
    else_values = effect.get("else", [])
    else_values = else_values if isinstance(else_values, list) else [else_values]
    rendered_then: list[str] = []
    for value in then_values:
        chunk = render_static_false_effect(
            value, avatar_actor_proven, npc_actor_proven, eoc_function_names,
            eoc_actor_requirements,
            actor_expression, eoc_conditions, creature_actor_proven,
            effect_actor_targets=effect_actor_targets,
            character_effect_actor_targets=character_effect_actor_targets,
            wound_actor_targets=wound_actor_targets,
            known_body_part_ids=known_body_part_ids,
            known_wound_ids=known_wound_ids,
            field_avatar_center_proven=field_avatar_center_proven,
        )
        if chunk is None:
            return None
        rendered_then.extend(chunk)
    rendered_else: list[str] = []
    for value in else_values:
        chunk = render_static_false_effect(
            value, avatar_actor_proven, npc_actor_proven, eoc_function_names,
            eoc_actor_requirements,
            actor_expression, eoc_conditions, creature_actor_proven,
            effect_actor_targets=effect_actor_targets,
            character_effect_actor_targets=character_effect_actor_targets,
            wound_actor_targets=wound_actor_targets,
            known_body_part_ids=known_body_part_ids,
            known_wound_ids=known_wound_ids,
            field_avatar_center_proven=field_avatar_center_proven,
        )
        if chunk is None:
            return None
        rendered_else.extend(chunk)
    lines = [f"    if {condition} then", *rendered_then]
    if rendered_else:
        lines.extend(["    else", *rendered_else])
    lines.append("    end")
    return lines


def render_static_switch_effect(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
    creature_actor_proven: bool,
    eoc_function_names: dict[str, str],
    eoc_actor_requirements: dict[str, str] | None = None,
    actor_expression: str | None = None,
    eoc_conditions: dict[str, Any] | None = None,
    npc_actor_expression: str | None = None,
    effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    character_effect_actor_targets: dict[str, tuple[str, str] | None] | None = None,
    wound_actor_targets: dict[str, str | None] | None = None,
    known_body_part_ids: frozenset[str] = frozenset(),
    known_wound_ids: frozenset[str] = frozenset(),
    field_avatar_center_proven: bool = False,
) -> list[str] | None:
    """Lower a legacy ``switch`` into ordinary Lua comparisons.

    Branch bodies are normalized to private EOC callbacks before rendering,
    so this helper only needs to validate the selector and dispatch the typed
    callback.  It therefore also handles nested ``if``/``switch`` branches
    without exposing an EOC runner in the generated Mod.
    """
    comment_keys = {
        key for key in effect
        if isinstance(key, str) and key.startswith("//")
    }
    # Legacy f_switch ignores an unmatched switch and has no top-level
    # ``default`` branch.  Only numeric defaults inside selector descriptors
    # (handled below) are supported here.
    if (
        "switch" not in effect or
        set(effect) - {"switch", "cases"} - comment_keys
    ):
        return None
    raw_switch = effect.get("switch")
    switch_expression: str | None = None
    if isinstance(raw_switch, dict) and set(raw_switch) == {"math"}:
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif (
        isinstance(raw_switch, dict) and
        "global_val" in raw_switch and
        set(raw_switch) <= {"global_val", "default"}
    ):
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif (
        isinstance(raw_switch, dict) and
        "context_val" in raw_switch and
        set(raw_switch) <= {"context_val", "default"}
    ):
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif (
        isinstance(raw_switch, dict) and "u_val" in raw_switch and
        set(raw_switch) <= {"u_val", "default"}
    ):
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif (
        isinstance(raw_switch, dict) and "npc_val" in raw_switch and
        set(raw_switch) <= {"npc_val", "default"}
    ):
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif (
        isinstance(raw_switch, dict) and "var_val" in raw_switch and
        set(raw_switch) <= {"var_val", "default"}
    ):
        switch_expression = render_eoc_numeric_expression(
            raw_switch, "0", actor_expression or "actor"
        )
    elif isinstance(raw_switch, (int, float)) and not isinstance(raw_switch, bool):
        switch_expression = lua_number(raw_switch)
    if switch_expression is None:
        return None

    cases = effect.get("cases")
    if not isinstance(cases, list) or not cases or len(cases) > 128:
        return None
    case_data: list[tuple[str, list[str]]] = []
    for case in cases:
        if not isinstance(case, dict) or "case" not in case or "effect" not in case:
            return None
        case_value = case.get("case")
        case_expression = render_eoc_numeric_expression(
            case_value, "0", actor_expression or "actor"
        )
        if case_expression is None:
            return None
        branch_effect = case.get("effect")
        branch_values = (
            branch_effect if isinstance(branch_effect, list) else [branch_effect]
        )
        rendered: list[str] = []
        for branch_value in branch_values:
            chunk = render_static_false_effect(
                branch_value, avatar_actor_proven, npc_actor_proven,
                eoc_function_names, eoc_actor_requirements,
                actor_expression, eoc_conditions, creature_actor_proven,
                effect_actor_targets=effect_actor_targets,
                character_effect_actor_targets=character_effect_actor_targets,
                wound_actor_targets=wound_actor_targets,
                known_body_part_ids=known_body_part_ids,
                known_wound_ids=known_wound_ids,
                field_avatar_center_proven=field_avatar_center_proven,
            )
            if chunk is None:
                return None
            rendered.extend(chunk)
        case_data.append((case_expression, rendered))
    lines: list[str] = [
        f"    local switch_value = ({switch_expression})",
        "    local switch_case = 0",
    ]
    # The native switch selects the last case whose threshold is no greater
    # than the switch value (it is a >= ladder, not an equality map).
    for index, (case_expression, _) in enumerate(case_data, 1):
        lines.append(
            f"    if switch_value >= ({case_expression}) then switch_case = {index} end"
        )
    for index, (_, rendered) in enumerate(case_data, 1):
        lines.append(
            f"    {'if' if index == 1 else 'elseif'} switch_case == {index} then"
        )
        lines.extend(rendered)
    if case_data:
        lines.append("    end")
    return lines


def _lua_choice(value: Any) -> str | None:
    """Render a terrain/furniture-style string or weighted choice value."""
    if isinstance(value, str) and value:
        return lua_quote(value)
    if not isinstance(value, list) or not value:
        return None
    if all(isinstance(entry, str) and entry for entry in value):
        return _lua_literal(value)
    if all(
        isinstance(entry, list) and
        len(entry) == 2 and
        isinstance(entry[0], str) and
        entry[0] and
        isinstance(entry[1], (int, float)) and
        not isinstance(entry[1], bool) and
        entry[1] > 0
        for entry in value
    ):
        return _lua_literal(value)
    return None


def _mapgen_item_descriptor(value: Any, location: str, result: MigrationResult) -> dict[str, Any] | None:
    """Convert one legacy mapgen item entry into a symbol descriptor."""
    if isinstance(value, str) and value:
        return {"item": value}
    if not isinstance(value, dict):
        result.add_todo("manual_rewrite", f"{location}: mapgen item entry needs review")
        return None
    item = value.get("item")
    group = value.get("group", value.get("item_group"))
    if not isinstance(item, str) and not isinstance(group, str):
        result.add_todo("manual_rewrite", f"{location}: mapgen item entry needs an item or group")
        return None
    descriptor: dict[str, Any] = {}
    if isinstance(item, str) and item:
        descriptor["item"] = item
    elif isinstance(group, str) and group:
        descriptor["item_group"] = group
    for source_key, target_key in (
        ("chance", "chance"),
        ("amount", "item_quantity"),
        ("charges", "item_charges"),
        ("ammo", "item_charges"),
        ("faction", "item_faction"),
    ):
        if source_key in value:
            raw = value[source_key]
            if isinstance(raw, (int, float)) and not isinstance(raw, bool):
                descriptor[target_key] = raw
            else:
                result.add_todo(
                    "manual_rewrite",
                    f"{location}: mapgen item {source_key} needs a numeric/string literal"
                )
    repeat = value.get("repeat")
    if isinstance(repeat, int) and not isinstance(repeat, bool) and repeat > 0:
        descriptor["repeat"] = repeat
    elif repeat is not None:
        result.add_todo("manual_rewrite", f"{location}: mapgen item repeat range needs review")
    return descriptor


def _mapgen_symbol_descriptors(
    source: dict[str, Any], location: str, result: MigrationResult
) -> dict[str, dict[str, Any]]:
    symbols: dict[str, dict[str, Any]] = {}

    def add_choice_map(field: str, target: str) -> None:
        raw = source.get(field)
        if raw is None:
            return
        if not isinstance(raw, dict):
            result.add_todo("manual_rewrite", f"{location}: mapgen {field} map needs review")
            return
        for glyph, value in raw.items():
            if not isinstance(glyph, str) or not glyph:
                result.add_todo("manual_rewrite", f"{location}: mapgen {field} glyph needs review")
                continue
            choice = _lua_choice(value)
            if choice is None:
                result.add_todo("manual_rewrite", f"{location}: mapgen {field} {glyph!r} needs review")
                continue
            symbols.setdefault(glyph, {})[target] = value

    add_choice_map("terrain", "terrain")
    add_choice_map("furniture", "furniture")
    add_choice_map("traps", "trap")
    add_choice_map("trap", "trap")
    raw_items = source.get("items", source.get("item"))
    if isinstance(raw_items, dict):
        for glyph, value in raw_items.items():
            entries = value if isinstance(value, list) else [value]
            descriptors = [
                _mapgen_item_descriptor(entry, f"{location} item {glyph!r}", result)
                for entry in entries
            ]
            descriptors = [entry for entry in descriptors if entry is not None]
            if descriptors:
                if len(descriptors) == 1:
                    symbols.setdefault(glyph, {}).update(descriptors[0])
                else:
                    symbols.setdefault(glyph, {})["sequence"] = descriptors
    raw_fields = source.get("fields")
    if isinstance(raw_fields, dict):
        for glyph, value in raw_fields.items():
            descriptor = symbols.setdefault(glyph, {})
            if isinstance(value, str) and value:
                descriptor["field"] = value
            elif isinstance(value, dict) and isinstance(value.get("field"), str):
                descriptor.update({
                    "field": value["field"],
                    "field_intensity": value.get("intensity", 1),
                    "field_age_turns": value.get("age", 0),
                })
            else:
                result.add_todo("manual_rewrite", f"{location}: mapgen field {glyph!r} needs review")
    raw_vending = source.get("vendingmachines", source.get("vending_machines"))
    if isinstance(raw_vending, dict):
        for glyph, value in raw_vending.items():
            if isinstance(value, dict) and isinstance(value.get("item_group"), str):
                symbols.setdefault(glyph, {}).update({
                    "vending": value["item_group"],
                    "vending_reinforced": bool(value.get("reinforced", False)),
                    "vending_powered": bool(value.get("powered", False)),
                    "vending_networked": bool(value.get("networked", False)),
                    "vending_lootable": bool(value.get("lootable", False)),
                })
            else:
                result.add_todo("manual_rewrite", f"{location}: mapgen vending machine {glyph!r} needs review")
    raw_liquids = source.get("liquids", source.get("liquid"))
    if isinstance(raw_liquids, dict):
        for glyph, value in raw_liquids.items():
            if isinstance(value, dict) and isinstance(value.get("liquid"), str):
                amount = value.get("amount", value.get("charges", 1))
                if isinstance(amount, list) and amount:
                    amount = amount[-1]
                    result.add_todo(
                        "manual_rewrite",
                        f"{location}: mapgen liquid {glyph!r} amount range bounded to its maximum"
                    )
                if isinstance(amount, int) and not isinstance(amount, bool):
                    symbols.setdefault(glyph, {}).update({
                        "liquid": value["liquid"], "liquid_charges": amount
                    })
                else:
                    result.add_todo("manual_rewrite", f"{location}: mapgen liquid {glyph!r} amount needs review")
            else:
                result.add_todo("manual_rewrite", f"{location}: mapgen liquid {glyph!r} needs review")
    return symbols


def _mapgen_terrain_ids(value: Any) -> list[str]:
    result: list[str] = []
    values = value if isinstance(value, list) else [value]

    def visit(entry: Any) -> None:
        if isinstance(entry, str) and entry:
            result.append(entry)
        elif isinstance(entry, list):
            for nested in entry:
                visit(nested)
    for entry in values:
        visit(entry)
    return list(dict.fromkeys(result))


def render_mapgen(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    object_value = value.get("object") if isinstance(value.get("object"), dict) else {}
    mapgen_id = value.get("nested_mapgen_id") or value.get("update_mapgen_id")
    if not isinstance(mapgen_id, str) or not mapgen_id:
        mapgen_id = value.get("id")
    if not isinstance(mapgen_id, str) or not mapgen_id:
        terrain_ids = _mapgen_terrain_ids(value.get("om_terrain"))
        mapgen_id = terrain_ids[0] if terrain_ids else None
    if not safe_platform_id(mapgen_id):
        result.partial.append(f"{source.location}: mapgen <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: mapgen needs a stable native id")
        return None
    todo_count = len(result.todos)
    rows = object_value.get("rows")
    if rows is not None and (
        not isinstance(rows, list) or
        any(not isinstance(row, str) for row in rows) or
        len(rows) > 24 or
        any(len(row) > 24 for row in rows)
    ):
        result.add_todo("manual_rewrite", f"{source.location}: mapgen {mapgen_id} rows exceed the 24x24 Platform shape")
        rows = []
    fill = object_value.get("fill_ter")
    if fill is not None and not isinstance(fill, str):
        result.add_todo("manual_rewrite", f"{source.location}: mapgen {mapgen_id} fill_ter needs review")
        fill = None
    symbols = _mapgen_symbol_descriptors(object_value, source.location, result)
    terrain_ids = _mapgen_terrain_ids(value.get("om_terrain"))
    primary = "false" if value.get("update_mapgen_id") else "true"
    if not rows and not fill:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: mapgen {mapgen_id} requires rows/fill_ter for a declarative definition"
        )
        result.partial.append(f"{source.location}: mapgen {mapgen_id}")
        return None
    lines = [
        "services.mapgen.define {",
        f"    id = {lua_quote(mapgen_id)},",
        f"    primary = {primary},",
    ]
    if terrain_ids:
        lines.append(f"    terrain_ids = {_lua_literal(terrain_ids)},")
    if isinstance(fill, str) and fill:
        lines.append(f"    fill_terrain = {lua_quote(fill)},")
    if isinstance(rows, list) and rows:
        lines.append(f"    rows = {_lua_literal(rows)},")
    palettes = object_value.get("palettes")
    if isinstance(palettes, list) and all(isinstance(entry, str) for entry in palettes):
        lines.append(f"    palettes = {_lua_literal(palettes)},")
    elif palettes is not None:
        result.add_todo("manual_rewrite", f"{source.location}: mapgen {mapgen_id} palettes need review")
    if symbols:
        lines.append("    symbols = {")
        for glyph in sorted(symbols):
            lines.append(f"        [{lua_quote(glyph)}] = {_lua_literal(symbols[glyph])},")
        lines.append("    },")
    lines.append("}")
    supported = {
        "type", "id", "om_terrain", "update_mapgen_id", "nested_mapgen_id", "object", "//",
    }
    unresolved = unresolved_fields(value, supported)
    if unresolved:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: mapgen {mapgen_id} unresolved fields: {', '.join(unresolved)}"
        )
    for key in set(object_value) - {
        "rows", "fill_ter", "palettes", "terrain", "furniture", "traps", "trap",
        "items", "item", "fields", "vendingmachines", "vending_machines", "liquids", "liquid",
    }:
        if not key.startswith("//"):
            result.add_todo("manual_rewrite", f"{source.location}: mapgen {mapgen_id} object field {key} needs a typed conversion")
    (result.partial if len(result.todos) != todo_count else result.converted).append(
        f"{source.location}: mapgen {mapgen_id}"
    )
    lines.extend(("",))
    return "\n".join(lines)


def render_palette(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    palette_id = value.get("id")
    if not safe_platform_id(palette_id):
        result.partial.append(f"{source.location}: palette <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: palette needs a stable native id")
        return None
    todo_count = len(result.todos)
    symbols = _mapgen_symbol_descriptors(value, source.location, result)
    if not symbols:
        result.add_todo("manual_rewrite", f"{source.location}: palette {palette_id} requires at least one symbol mapping")
    lines = [
        "services.mapgen.register_palette {",
        f"    id = {lua_quote(palette_id)},",
    ]
    copy_from = value.get("copy-from")
    if isinstance(copy_from, str) and copy_from:
        lines.append(f"    palettes = {{ {lua_quote(copy_from)} }},")
    if symbols:
        lines.append("    symbols = {")
        for glyph in sorted(symbols):
            lines.append(f"        [{lua_quote(glyph)}] = {_lua_literal(symbols[glyph])},")
        lines.append("    },")
    lines.append("}")
    supported = {
        "type", "id", "copy-from", "terrain", "furniture", "traps", "trap", "items", "item",
        "fields", "vendingmachines", "vending_machines", "liquids", "liquid", "//",
    }
    unresolved = unresolved_fields(value, supported)
    if unresolved:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: palette {palette_id} unresolved fields: {', '.join(unresolved)}"
        )
    for key in set(value) - supported:
        if not key.startswith("//"):
            result.add_todo("manual_rewrite", f"{source.location}: palette {palette_id} field {key} needs review")
    (result.partial if len(result.todos) != todo_count else result.converted).append(
        f"{source.location}: palette {palette_id}"
    )
    return "\n".join(lines) + "\n"


def render_mod_tileset(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    compatibility = value.get("compatibility")
    if not isinstance(compatibility, list) or not compatibility or any(
        not isinstance(entry, str) or not entry for entry in compatibility
    ):
        result.partial.append(f"{source.location}: mod tileset <invalid compatibility>")
        result.add_todo("manual_rewrite", f"{source.location}: mod tileset compatibility needs review")
        return None
    todo_count = len(result.todos)
    atlases: list[dict[str, Any]] = []
    raw_atlases = value.get("tiles-new", value.get("tiles"))
    if not isinstance(raw_atlases, list):
        result.add_todo("manual_rewrite", f"{source.location}: mod tileset tiles-new needs review")
        raw_atlases = []
    for atlas in raw_atlases:
        if not isinstance(atlas, dict) or not isinstance(atlas.get("file"), str):
            result.add_todo("manual_rewrite", f"{source.location}: mod tileset atlas needs a relative file")
            continue
        converted = {key: copy.deepcopy(raw) for key, raw in atlas.items() if key != "//"}
        converted["tiles"] = converted.get("tiles", [])
        if not isinstance(converted["tiles"], list):
            result.add_todo("manual_rewrite", f"{source.location}: mod tileset atlas tiles need review")
            converted["tiles"] = []
        atlases.append(converted)
    lines = [
        "services.tileset.register {",
        f"    id = {lua_quote(source.value.get('id', source.location))},",
        f"    compatibility = {_lua_literal(compatibility)},",
        f"    atlases = {_lua_literal(atlases)},",
        "}",
    ]
    supported = {"type", "compatibility", "tiles-new", "tiles", "id", "//"}
    unresolved = unresolved_fields(value, supported)
    if unresolved:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: mod tileset unresolved fields: {', '.join(unresolved)}"
        )
    # A legacy mod_tileset has no stable id; derive one from its source path.
    if not safe_platform_id(value.get("id")):
        derived = re.sub(r"[^A-Za-z0-9_]+", "_", source.path.stem).strip("_") or "tileset"
        lines[1] = f"    id = {lua_quote(derived)},"
        result.add_todo("manual_rewrite", f"{source.location}: mod tileset id derived as {derived!r}")
    (result.partial if len(result.todos) != todo_count else result.converted).append(
        f"{source.location}: mod tileset {source.path.stem}"
    )
    return "\n".join(lines) + "\n"


def _talk_text(value: Any) -> tuple[str | LuaRaw | None, str | None]:
    if isinstance(value, str):
        return value, None
    if isinstance(value, list):
        return None, "dynamic_line random-choice arrays need a manual choice conversion"
    if not isinstance(value, dict) or "concatenate" not in value:
        return None, "dynamic_line needs a static string or flat concatenate"

    extra_fields = sorted(
        key for key in value
        if key != "concatenate" and not (isinstance(key, str) and key.startswith("//"))
    )
    if extra_fields:
        return None, (
            "dynamic_line concatenate has unsupported fields: " +
            ", ".join(extra_fields)
        )
    pieces = value["concatenate"]
    if not isinstance(pieces, list):
        return None, "dynamic_line concatenate must be an array"
    if not pieces:
        return None, "dynamic_line concatenate must contain at least one translation piece"

    calls: list[str] = []
    for index, piece in enumerate(pieces, start=1):
        if isinstance(piece, str):
            text = piece
            context = None
        elif isinstance(piece, list):
            return None, (
                f"dynamic_line concatenate entry {index} is a random-choice array; "
                "only flat translation entries are supported"
            )
        elif isinstance(piece, dict):
            extra_piece_fields = sorted(
                key for key in piece
                if key not in {"str", "ctxt"} and
                not (isinstance(key, str) and key.startswith("//"))
            )
            text = piece.get("str")
            context = piece.get("ctxt")
            if extra_piece_fields or not isinstance(text, str) or (
                "ctxt" in piece and not isinstance(context, str)
            ):
                return None, (
                    f"dynamic_line concatenate entry {index} must be a string or "
                    "a typed {str, ctxt} translation"
                )
        else:
            return None, (
                f"dynamic_line concatenate entry {index} must be a string or "
                "a typed {str, ctxt} translation"
            )
        if "\0" in text or (context is not None and "\0" in context):
            return None, f"dynamic_line concatenate entry {index} contains NUL text"
        arguments = [lua_quote(text)]
        if context is not None:
            arguments.append(lua_quote(context))
        calls.append(f"ccb.services.translate({', '.join(arguments)})")

    callback = "\n".join((
        "function(context)",
        "        return " + "\n            .. ".join(calls),
        "    end",
    ))
    # Native dynamic_line_t translates each piece when the line is generated.
    # Keep each gettext key/context separate and defer those lookups to the
    # Platform callback instead of joining the source strings during migration.
    return LuaRaw(callback), None


def _render_talk_topic_npc_state_condition(condition: Any) -> str | None:
    """Render bounded beta Character snapshot predicates for a topic callback."""
    if (
        isinstance(condition, str) and
        condition in NPC_BETA_CHARACTER_SNAPSHOT_FIELDS
    ):
        field = NPC_BETA_CHARACTER_SNAPSHOT_FIELDS[condition]
        return f"state.{field} == true"
    if isinstance(condition, dict):
        if set(condition) == {"npc_has_activity"}:
            # The native jarg::string parser ignores this member value.
            if isinstance(condition["npc_has_activity"], str):
                return "state.activity.active == true"
            return None
    return None


def render_talk_topic_response_condition(
    condition: Any, _depth: int = 0,
) -> LuaRaw | None:
    """Render one source-proven response predicate against its live speaker.

    Native ``u_has_intelligence`` reads ``const_actor(false)->int_cur()``.
    Platform dialogue callbacks expose that same alpha participant as
    ``PlatformDialogueContext:speaker()``. ``u_can_stow_weapon`` uses the
    exact avatar and the matching read-only weapon-state query. Camp predicates
    use the exact native global-player query or the live dialogue beta exposed
    as ``interlocutor()``. Assigned-mission predicates read the active native
    dialogue vector. NPC-prefixed mission predicates use the live beta and the
    existing typed NPC mission services. Direct ``npc_*`` state conditions use
    that live beta Character's typed snapshot. Safe-space conditions query the
    callback-scoped native beta talker directly, preserving native talker
    overrides without retaining an actor reference. Native unprefixed mission
    aliases select beta. ``u_*`` alpha mission predicates remain fail-closed;
    Boolean compositions require every child to have a supported lowering.
    Training-offer predicates use the live alpha/beta pair and select the
    teacher from the native parser's ``is_npc`` orientation.
    ``mission_has_generic_rewards`` reads beta's selected mission; the typed
    query preserves the native true result for an empty selection, while
    non-NPC talkers inherit the native null selection.
    """
    if _depth > 16:
        return None
    identity_condition = _render_talk_topic_participant_identity_condition(
        condition
    )
    if identity_condition is not None:
        return identity_condition
    if isinstance(condition, dict) and set(condition) == {"math"}:
        # Native u_skill reads dialogue alpha even when the named skill ID is
        # unregistered (Exodii says 'social', while the registered ID is
        # 'speech').  Use the same native math evaluator, not skills.get,
        # which rejects invalid IDs.  Other expressions stay TODO.
        expressions = condition["math"]
        if isinstance(expressions, list) and len(expressions) == 1 and isinstance(expressions[0], str):
            skill_match = re.fullmatch(
                r"u_skill\('social'\)\s*([<>])\s*([0-9]+)", expressions[0]
            )
            if skill_match is not None:
                operator, threshold_text = skill_match.groups()
                threshold = int(threshold_text)
                if threshold <= NATIVE_INT_MAX:
                    expression = f"u_skill('social') {operator} {threshold}"
                    return LuaRaw(
                        "function(dialogue_context)\n"
                        "            if not dialogue_context:valid() then return false end\n"
                        "            local alpha = dialogue_context:speaker()\n"
                        '            if alpha == nil or alpha.kind ~= "creature" or '
                        '(alpha.subtype ~= "avatar" and alpha.subtype ~= "character" '
                        'and alpha.subtype ~= "npc") then return false end\n'
                        "            if not alpha:is_valid() then return false end\n"
                        "            local evaluated = services.gameplay.math.evaluate("
                        f"{lua_quote(expression)}, alpha, {{}})\n"
                        "            return evaluated.ok and evaluated.value ~= 0\n"
                        "        end"
                    )
    if (
        isinstance(condition, dict) and set(condition) == {"not"} and
        condition["not"] == "is_by_radio"
    ):
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            return not dialogue_context:by_radio()\n"
            "        end"
        )
    if isinstance(condition, dict) and len(condition) == 1:
        if "not" in condition and isinstance(condition["not"], (str, dict)):
            child = render_talk_topic_response_condition(
                condition["not"], _depth + 1,
            )
            if child is not None:
                return LuaRaw(
                    "function(dialogue_context)\n"
                    "            if not dialogue_context:valid() then return false end\n"
                    f"            return not ({child.source})(dialogue_context)\n"
                    "        end"
                )
        for operator, separator, empty_result in (
            ("and", " and ", "true"), ("or", " or ", "false"),
        ):
            entries = condition.get(operator)
            if not isinstance(entries, list) or len(entries) > 32:
                continue
            if not all(isinstance(entry, (str, dict)) for entry in entries):
                return None
            children = [
                render_talk_topic_response_condition(entry, _depth + 1)
                for entry in entries
            ]
            if any(child is None for child in children):
                return None
            expression = separator.join(
                f"({child.source})(dialogue_context)"
                for child in children if child is not None
            ) or empty_result
            return LuaRaw(
                "function(dialogue_context)\n"
                "            if not dialogue_context:valid() then return false end\n"
                f"            return {expression}\n"
                "        end"
            )
    if isinstance(condition, str) and condition in SAFE_SPACE_BETA_CONDITION_SELECTORS:
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            return dialogue_context:interlocutor_at_safe_space()\n"
            "        end"
        )
    if isinstance(condition, dict) and set(condition) == {"npc_has_effect"}:
        effect_id = condition["npc_has_effect"]
        if safe_platform_id(effect_id):
            # Native f_has_effect uses dialogue.reason when bodypart is omitted.
            # Keep that implicit target inside the native callback context.
            return LuaRaw("\n".join([
                "function(dialogue_context)",
                "            if not dialogue_context:valid() then return false end",
                "            return dialogue_context:has_interlocutor_effect(",
                "                services.types.id(\"effect\", "
                f"{lua_quote(effect_id)}))",
                "        end",
            ]))
    if condition == "npc_friend":
        # Native f_npc_friend(true) queries the beta talker against the global
        # player Character. Only NPC talkers override the native default false;
        # the Platform snapshot's friendly field uses the same NPC query.
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local beta = dialogue_context:interlocutor()\n"
            '            if beta == nil or beta.kind ~= "creature" or beta.subtype ~= "npc" then return false end\n'
            "            if not beta:is_valid() then return false end\n"
            "            local snapshot = services.npcs.get(beta)\n"
            "            return snapshot.ok and snapshot.value.friendly == true\n"
            "        end"
        )
    npc_state_expression = _render_talk_topic_npc_state_condition(condition)
    if npc_state_expression is not None:
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local beta = dialogue_context:interlocutor()\n"
            '            if beta == nil or beta.kind ~= "creature" or '
            '(beta.subtype ~= "avatar" and beta.subtype ~= "character" and '
            'beta.subtype ~= "npc") then return false end\n'
            "            if not beta:is_valid() then return false end\n"
            "            local snapshot = services.characters.snapshot(beta)\n"
            "            if not snapshot.ok then return false end\n"
            "            local state = snapshot.value\n"
            f"            return {npc_state_expression}\n"
            "        end"
        )
    training_offer_counts = {
        "u_train_skills": ("skill_count", "alpha", "beta"),
        "npc_train_skills": ("skill_count", "beta", "alpha"),
        "u_train_styles": ("style_count", "alpha", "beta"),
        "npc_train_styles": ("style_count", "beta", "alpha"),
        "u_train_spells": ("spell_count", "alpha", "beta"),
        "npc_train_spells": ("spell_count", "beta", "alpha"),
    }
    if isinstance(condition, str) and condition in training_offer_counts:
        count_field, teacher, student = training_offer_counts[condition]
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local alpha = dialogue_context:speaker()\n"
            "            local beta = dialogue_context:interlocutor()\n"
            "            if alpha == nil or beta == nil then return false end\n"
            "            if not alpha:is_valid() or not beta:is_valid() then return false end\n"
            "            local offers = services.characters.training_offers("
            f"{teacher}, {student})\n"
            f"            return offers.ok and offers.value.{count_field} > 0\n"
            "        end"
        )
    if condition == "u_has_camp":
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local result = services.camps.has_player_owned_camp()\n"
            "            return result.ok and result.value == true\n"
            "        end"
        )
    if condition == "npc_has_assigned_camp":
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local beta = dialogue_context:interlocutor()\n"
            '            if beta == nil or beta.kind ~= "creature" or beta.subtype ~= "npc" then return false end\n'
            "            if not beta:is_valid() then return false end\n"
            "            local result = services.npcs.get(beta)\n"
            "            return result.ok and result.value.has_assigned_camp == true\n"
            "        end"
        )
    if condition == "u_can_stow_weapon":
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local avatar = services.characters.avatar()\n"
            "            if avatar == nil or not avatar:is_valid() then return false end\n"
            "            local weapon = services.inventory.weapon_state(avatar)\n"
            "            return weapon.ok and weapon.value.can_stow == true\n"
            "        end"
        )
    if condition in ("u_has_stolen_item", "npc_has_stolen_item"):
        # Native f_has_stolen_item ignores the selector's is_npc flag: alpha's
        # inventory is checked against beta's old ownership in both cases.
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local holder = dialogue_context:speaker()\n"
            "            local owner = dialogue_context:interlocutor()\n"
            '            if holder == nil or holder.kind ~= "creature" then return false end\n'
            '            if owner == nil or owner.kind ~= "creature" then return false end\n'
            "            if not holder:is_valid() or not owner:is_valid() then return false end\n"
            "            local result = services.inventory.has_stolen_from(holder, owner)\n"
            "            return result.ok and result.value == true\n"
            "        end"
        )
    mission_count_conditions = {
        "has_no_assigned_mission": ("assigned", "== 0"),
        "has_assigned_mission": ("assigned", "== 1"),
        "has_many_assigned_missions": ("assigned", ">= 2"),
        "u_has_no_available_mission": ("available", "== 0"),
        "u_has_available_mission": ("available", "== 1"),
        "u_has_many_available_missions": ("available", ">= 2"),
        "npc_has_no_available_mission": ("available", "== 0"),
        "npc_has_available_mission": ("available", "== 1"),
        "npc_has_many_available_missions": ("available", ">= 2"),
        "has_no_available_mission": ("available", "== 0"),
        "has_available_mission": ("available", "== 1"),
        "has_many_available_missions": ("available", ">= 2"),
    }
    # condition_parser's u_* spelling selects is_npc=false; both unprefixed
    # and npc_* aliases select is_npc=true. The alpha forms query the exact
    # speaker; NPC talkers expose the same raw chatbin list through the typed
    # service, while other native talkers inherit the empty list.
    if isinstance( condition, str ) and condition in mission_count_conditions:
        collection, comparison = mission_count_conditions[condition]
        if collection == "available":
            actor_accessor = "speaker" if condition.startswith( "u_" ) else "interlocutor"
            count_query = (
                "            local count = 0\n"
                f"            local actor = dialogue_context:{actor_accessor}()\n"
                "            if actor == nil then return false end\n"
                '            if actor.kind == "creature" and not actor:is_valid() then return false end\n'
                '            if actor.kind == "creature" and actor.subtype == "npc" then\n'
                "                local available = services.npcs.missions.available_count(actor)\n"
                "                if not available.ok then return false end\n"
                "                count = available.value\n"
                "            end\n"
            )
        else:
            count_query = (
                "            local count = dialogue_context:assigned_mission_count()\n"
            )
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            + count_query +
            f"            return count {comparison}\n"
            "        end"
        )
    mission_status_conditions = {
        "u_mission_complete": "complete",
        "u_mission_incomplete": "incomplete",
        "u_mission_failed": "failed",
        "npc_mission_complete": "complete",
        "npc_mission_incomplete": "incomplete",
        "npc_mission_failed": "failed",
        "mission_complete": "complete",
        "mission_incomplete": "incomplete",
        "mission_failed": "failed",
    }
    if isinstance( condition, str ) and condition in mission_status_conditions:
        # A native talker NPC stores its selected mission in chatbin. Other
        # talkers inherit the native null selection and therefore return false.
        predicate = mission_status_conditions[condition]
        actor_accessor = "speaker" if condition.startswith( "u_" ) else "interlocutor"
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            f"            local actor = dialogue_context:{actor_accessor}()\n"
            '            if actor == nil or actor.kind ~= "creature" or actor.subtype ~= "npc" then return false end\n'
            "            if not actor:is_valid() then return false end\n"
            "            local owner = services.characters.avatar()\n"
            "            if owner == nil or not owner:is_valid() then return false end\n"
            "            local selected = services.npcs.missions.selected_condition(actor, owner, "
            f"{lua_quote(predicate)})\n"
            "            return selected.ok and selected.value == true\n"
            "        end"
        )
    if isinstance(condition, dict) and set(condition) in (
        {"u_mission_goal"}, {"npc_mission_goal"}, {"mission_goal"}
    ):
        # Only NPC talkers override selected_mission(); the other native
        # talker classes have the same false result as the selected query.
        goal_key = next(iter(condition))
        goal = condition[goal_key]
        if not isinstance( goal, str ) or goal not in NATIVE_MISSION_GOALS:
            return None
        actor_accessor = "speaker" if goal_key == "u_mission_goal" else "interlocutor"
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            f"            local actor = dialogue_context:{actor_accessor}()\n"
            '            if actor == nil or actor.kind ~= "creature" or actor.subtype ~= "npc" then return false end\n'
            "            if not actor:is_valid() then return false end\n"
            "            local selected = services.npcs.missions.selected_has_goal(actor, "
            f"{lua_quote(goal)})\n"
            "            return selected.ok and selected.value == true\n"
            "        end"
        )
    if condition == "mission_has_generic_rewards":
        return LuaRaw(
            "function(dialogue_context)\n"
            "            if not dialogue_context:valid() then return false end\n"
            "            local beta = dialogue_context:interlocutor()\n"
            "            if beta == nil or not beta:is_valid() then return false end\n"
            '            if beta.kind ~= "creature" or beta.subtype ~= "npc" then return true end\n'
            "            local selected = services.npcs.missions.selected_has_generic_rewards(beta)\n"
            "            return selected.ok and selected.value == true\n"
            "        end"
        )
    if not isinstance(condition, dict) or set(condition) != {"u_has_intelligence"}:
        return None
    threshold = finite_number_literal(condition["u_has_intelligence"])
    if threshold is None or threshold <= 0:
        return None
    callback = (
        "function(dialogue_context)\n"
        "            if not dialogue_context:valid() then return false end\n"
        "            local speaker = dialogue_context:speaker()\n"
        '            if speaker == nil or speaker.kind ~= "creature" then return false end\n'
        '            if speaker.subtype ~= "avatar" and speaker.subtype ~= "character" and '
        'speaker.subtype ~= "npc" then return false end\n'
        "            if not speaker:is_valid() then return false end\n"
        "            local snapshot = services.characters.snapshot(speaker)\n"
        "            if not snapshot.ok then return false end\n"
        f"            return snapshot.value.stats.intelligence >= {lua_number(threshold)}\n"
        "        end"
    )
    return LuaRaw(callback)


def _talk_topic_effect_todo(effect: Any) -> tuple[str, str] | None:
    if isinstance(effect, list):
        if any(
            isinstance(nested, dict) and "u_spawn_item" in nested
            for nested in effect
        ):
            return (
                "manual_rewrite",
                "combined effects containing u_spawn_item are not lowered; only "
                "a single direct TALK response with one literal item ID uses the "
                "callback-scoped native dialogue grant",
            )
        for nested in effect:
            mission_todo = _talk_topic_effect_todo(nested)
            if mission_todo is not None and "mission" in mission_todo[1]:
                return mission_todo
    if isinstance(effect, dict):
        if "u_spawn_item" in effect:
            return (
                "manual_rewrite",
                "parameterized u_spawn_item forms remain TODO; only a direct TALK "
                "response containing exactly one literal item ID is lowered; "
                "count, group, container, flags, force_equip, loc, and dynamic "
                "values require their native semantics",
            )
        selectors = set(effect) & {"npc_gets_item", "npc_gets_item_to_use"}
        if not selectors and set(effect) == {"effect"}:
            wrapped = effect["effect"]
            if isinstance(wrapped, str) and wrapped in {
                "npc_gets_item", "npc_gets_item_to_use",
            }:
                selectors = {wrapped}
        if selectors:
            return (
                "semantic_choice",
                "native item offers are registered as direct string selectors; "
                "object-shaped forms are not lowered without an exact native parse",
            )
    if effect == "goto_location":
        return (
            "platform_gap",
            "goto_location cannot preserve native camp ordering, the NPC's saved "
            "first topic, or goal/path clearing after a declined or unreachable route "
            "with current typed services",
        )
    if effect == "player_weapon_away":
        return (
            "manual_rewrite",
            "native player_weapon_away can use the typed stow_current_weapon "
            "service in Platform on_action before opinion and hostility handling; "
            "the response still needs its condition, opinion, helpless "
            "consequence, and translated text preserved together",
        )
    if isinstance(effect, str) and effect in {
        "mission_success", "mission_failure", "clear_mission",
    }:
        if effect == "mission_success":
            return (
                "manual_rewrite",
                "only a direct TALK mission_success response with a converted "
                "condition and native switch/default ordering is lowered through "
                "the callback-scoped beta operation; trial branches, opinion fields, "
                "combined effects, and EOCs remain TODO",
            )
        if effect == "clear_mission":
            return (
                "manual_rewrite",
                "only a standalone direct TALK response with static text/topic is "
                "lowered through the callback-scoped native beta clear; conditions, "
                "additional response fields, combined effects, and EOCs remain TODO",
            )
        return (
            "manual_rewrite",
            f"native WRAP {effect} executes inside talk_effect_t::apply before "
            "opinion/hostility handling; Platform on_action can preserve that "
            "phase, but the current typed services do not match this effect's "
            "selected-mission and provider-side-effect semantics",
        )
    if effect == "mission_reward":
        return (
            "manual_rewrite",
            "native mission_reward adds beta's selected mission value to NPC debt "
            "before opening the localized Reward barter UI; only the bounded direct "
            "TALK response with a converted condition is lowered, while EOCs and "
            "responses with additional fields remain TODO",
        )
    if effect == "remove_active_mission":
        return (
            "semantic_choice",
            "string-form remove_active_mission is not registered in the native "
            "WRAP map; use the object form only in an EOC with a proven avatar",
        )
    if isinstance(effect, dict):
        if "npc_lose_morale" in effect:
            return (
                "manual_rewrite",
                "npc_lose_morale lowers only for a direct static-topic response "
                "with one registered morale ID and no other response fields or actions",
            )
        for selector in ("goto_location", "player_weapon_away"):
            if selector in effect:
                return (
                    "semantic_choice",
                    f"native WRAP {selector} accepts only a string; this "
                    "object-shaped form has no native effect semantics",
                )
        mission_selectors = {
            "finish_mission", "remove_active_mission", "mission_success",
            "mission_failure", "clear_mission",
        }
        if mission_selectors.intersection(effect):
            return (
                "manual_rewrite",
                "native response mission effects execute inside talk_effect_t::apply "
                "before opinion/hostility handling; Platform on_action can preserve "
                "that phase, but the current typed services do not match the "
                "selected-mission and provider-side-effect semantics",
            )
        if "mission_reward" in effect:
            return (
                "manual_rewrite",
                "native mission_reward adds beta's selected mission value to NPC debt "
                "before opening the localized Reward barter UI; this object-shaped "
                "form is outside the bounded direct TALK string-effect lowering",
            )
    if not _node_has_key(effect, "run_eocs"):
        if not (
            _node_has_key(effect, "true_eocs") or
            _node_has_key(effect, "false_eocs")
        ):
            return None
        # These callbacks run within the enclosing native action before
        # talk_effect_t applies opinion and hostility. Platform on_action has
        # the matching phase, but this renderer cannot yet preserve the
        # enclosing action's selected EOC branch.
        return (
            "manual_rewrite",
            "native true_eocs/false_eocs run inside talk_effect_t::apply before "
            "opinion and hostility handling; migrate the enclosing native "
            "action and its success/failure branch together to preserve ordering",
        )
    # Native f_run_eocs executes synchronously inside talk_effect_t::apply,
    # before talk_effect_t applies opinion and checks whether the NPC turned
    # hostile. Platform on_action has this phase, but this renderer cannot yet
    # preserve the enclosing action's selected EOC branch.
    # The Platform on_action slot now runs in this native effect phase, but
    # translating a nested run_eocs callback alone would lose its enclosing
    # action and branch result.
    return (
        "manual_rewrite",
        "native run_eocs executes inside talk_effect_t::apply before opinion and "
        "hostility handling; migrate the enclosing native action and its "
        "success/failure branch together to preserve ordering",
    )


def render_talk_topic_npc_lose_morale_action(
    entry: Any, known_morale_ids: frozenset[str],
) -> LuaRaw | None:
    """Render the one direct response shape with native action-phase parity."""
    if not isinstance(entry, dict) or set(entry) != {"text", "topic", "effect"}:
        return None
    if (
        not isinstance(entry.get("text"), str) or
        not isinstance(entry.get("topic"), str) or
        not entry["topic"]
    ):
        return None
    effect = entry.get("effect")
    if (
        not isinstance(effect, dict) or
        set(effect) != {"npc_lose_morale"} or
        not safe_platform_id(effect.get("npc_lose_morale")) or
        effect["npc_lose_morale"] not in known_morale_ids
    ):
        return None
    morale_id = effect["npc_lose_morale"]
    return LuaRaw(
        "function(context, _trial_success)\n"
        "    local morale_target = context:interlocutor()\n"
        "    if morale_target ~= nil and morale_target.kind == \"creature\" and "
        "morale_target.subtype == \"npc\" and morale_target:is_valid() then\n"
        "        service_value(services.morale.remove(morale_target, "
        "services.types.id(\"morale\", " + lua_quote(morale_id) + ")))\n"
        "    end\n"
        "end"
    )


def render_talk_topic_mission_reward_action(
    entry: Any, converted_condition: LuaRaw | None,
) -> LuaRaw | None:
    """Run native WRAP mission_reward for one exact, conditioned TALK response."""
    if (
        not isinstance(entry, dict) or
        set(entry) != {"text", "topic", "condition", "effect"} or
        not isinstance(entry.get("text"), str) or
        not isinstance(entry.get("topic"), str) or
        not safe_platform_id(entry["topic"]) or
        converted_condition is None or
        entry.get("effect") != "mission_reward"
    ):
        return None
    # avatar::talk_to builds native alpha from the active avatar and beta from
    # talk_with. The typed operation calls the original native function, which
    # preserves debt-before-UI ordering, localization, and null-selection
    # behavior. EOCs and responses with additional fields remain TODO.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    local alpha = context:speaker()",
        '    if alpha == nil or alpha.kind ~= "creature" or alpha.subtype ~= "avatar" then return end',
        "    if not alpha:is_valid() then return end",
        "    local beta = context:interlocutor()",
        '    if beta == nil or beta.kind ~= "creature" or beta.subtype ~= "npc" then return end',
        "    if not beta:is_valid() then return end",
        "    service_value(services.npcs.missions.open_selected_reward_trade(beta, alpha))",
        "end",
    ]))


def render_talk_topic_mission_success_action(
    entry: Any, converted_condition: LuaRaw | None,
) -> LuaRaw | None:
    """Run the native beta mission-success operation for an exact switch response."""
    required_fields = {"text", "topic", "condition", "switch", "effect"}
    if (
        not isinstance(entry, dict) or
        set(entry) not in (required_fields, required_fields | {"default"}) or
        not isinstance(entry.get("text"), str) or
        not isinstance(entry.get("topic"), str) or
        not safe_platform_id(entry["topic"]) or
        converted_condition is None or
        entry.get("switch") is not True or
        ("default" in entry and entry["default"] is not True) or
        entry.get("effect") != "mission_success"
    ):
        return None
    # The real mission response table uses ordered switch responses. The
    # Platform runtime implements the same switch/default evaluation order;
    # the callback invokes the native beta operation only after selection.
    # Trials, opinions, combined effects, and EOCs remain outside this shape.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    context:succeed_selected_mission()",
        "end",
    ]))


def render_talk_topic_clear_mission_action(entry: Any) -> LuaRaw | None:
    """Lower one standalone direct TALK clear_mission response."""
    if (
        not isinstance(entry, dict) or
        set(entry) != {"text", "topic", "effect"} or
        not isinstance(entry.get("text"), str) or
        not isinstance(entry.get("topic"), str) or
        not safe_platform_id(entry["topic"]) or
        entry.get("effect") != "clear_mission"
    ):
        return None
    # TALK response actions execute in talk_effect_t::apply. The typed context
    # delegates to talk_function::clear_mission on the live native beta NPC,
    # preserving selected-pointer, follow-up, and ordering semantics without
    # retaining a provider pointer. Conditions, added effects, and EOCs remain
    # outside this shape.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    context:clear_selected_mission()",
        "end",
    ]))


def render_talk_topic_mission_failure_action(entry: Any) -> LuaRaw | None:
    """Lower the Lighthouse mission-failure response's exact native sequence."""
    if (
        not isinstance(entry, dict) or
        set(entry) != {"text", "topic", "effect"} or
        not isinstance(entry.get("text"), str) or
        entry.get("topic") != "TALK_DONE" or
        entry.get("effect") != [
            "mission_failure", "clear_mission", "end_conversation",
        ]
    ):
        return None
    # These are synchronous native TALK effects in this exact order. Each
    # typed call resolves the live beta NPC in the writable response callback;
    # trials, conditions, extra effects, and EOCs are deliberately excluded.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    context:fail_selected_mission()",
        "    context:clear_selected_mission()",
        "    context:end_interlocutor_conversation()",
        "end",
    ]))


def render_talk_topic_item_offer_effect(response: Any) -> LuaRaw | None:
    """Lower an exact, condition-renderable native TALK item-offer response."""
    if not isinstance(response, dict) or set(response) - {
        "text", "topic", "condition", "effect",
    }:
        return None
    if "topic" in response and (
        not isinstance(response["topic"], str) or not response["topic"]
    ):
        return None
    if "condition" in response and render_talk_topic_response_condition(
        response["condition"]
    ) is None:
        return None
    effect = response.get("effect")
    if not isinstance(effect, str):
        return None
    if effect == "npc_gets_item":
        use_item = "false"
    elif effect == "npc_gets_item_to_use":
        use_item = "true"
    else:
        return None
    return LuaRaw(
        "function(dialogue_context, trial_success) "
        "if not trial_success then return end; "
        f"dialogue_context:offer_item_to_interlocutor({use_item}) "
        "end"
    )


def _talk_topic_item_offer_todo(response: Any) -> tuple[str, str] | None:
    if not isinstance(response, dict):
        return None
    effect = response.get("effect")
    if not isinstance(effect, str) or effect not in {
        "npc_gets_item", "npc_gets_item_to_use",
    }:
        return None
    return (
        "manual_rewrite",
        "native item offers lower only for direct string responses without a trial "
        "or extra fields and with a precisely converted condition",
    )


def render_talk_topic_pet_purchase_action(response: Any) -> LuaRaw | None:
    """Lower the two exact shelter responses using native purchase semantics."""
    if (
        not isinstance(response, dict) or
        set(response) != {"text", "topic", "condition", "effect"} or
        not isinstance(response.get("text"), str) or
        response.get("topic") != "TALK_DONE" or
        response.get("condition") != {"not": {"npc_has_effect": "sold_pet"}}
    ):
        return None
    effects = response.get("effect")
    if not isinstance(effects, list) or len(effects) != 2:
        return None
    purchase, mark_sold = effects
    # These are the exact checked-in animal-shelter variants. Keep richer
    # options, EOC tails, extra effects, and altered order as TODO until their
    # native response-phase semantics have a separate proof.
    if purchase not in (
        {"u_buy_monster": "mon_dog", "cost": 5000, "pacified": True},
        {"u_buy_monster": "mon_cat", "cost": 2500, "pacified": True},
    ) or mark_sold != {"npc_add_effect": "sold_pet", "duration": "24 hours"}:
        return None
    monster_id = purchase["u_buy_monster"]
    cost = purchase["cost"]
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    context:purchase_pet(services.types.id(\"monster\", "
        f"{lua_quote(monster_id)}), {{ cost = {cost}, pacified = true }})",
        "    local sold = services.effects.add(",
        "        context:interlocutor(),",
        "        services.types.id(\"effect\", \"sold_pet\"),",
        "        services.time.duration(86400, \"turn\"))",
        "    if not sold.ok then error(sold.error.code) end",
        "end",
    ]))


def render_talk_topic_weapon_away_action(
    response: Any, converted_condition: LuaRaw | None,
) -> LuaRaw | None:
    """Keep the exact native response action, opinion, and consequence order."""
    if (
        not isinstance(response, dict) or
        set(response) != {"text", "topic", "condition", "effect", "opinion"} or
        not isinstance(response.get("text"), str) or
        not safe_platform_id(response.get("topic")) or
        converted_condition is None or
        response.get("effect") != "player_weapon_away"
    ):
        return None
    opinion = response.get("opinion")
    if (
        not isinstance(opinion, dict) or not opinion or
        set(opinion) - {"trust", "fear", "value", "anger", "owed", "sold"} or
        any(type(value) is not int or not NATIVE_INT_MIN <= value <= NATIVE_INT_MAX
            for value in opinion.values())
    ):
        return None
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    service_value(services.equipment.stow_current_weapon(",
        "        services.characters.avatar()))",
        "end",
    ]))


def render_talk_topic(
    source: SourceObject,
    result: MigrationResult,
    known_morale_ids: frozenset[str] = frozenset(),
) -> str | None:
    value = source.value
    topic_id = value.get("id")
    if isinstance(topic_id, list) and len(topic_id) == 1:
        # Native load_talk_topic registers each array entry independently. A
        # singleton array therefore has the same registration semantics as a
        # string ID; multiple aliases would require duplicate topic output.
        topic_id = topic_id[0]
    if not safe_platform_id(topic_id):
        result.partial.append(f"{source.location}: talk topic <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: talk topic needs a stable id")
        return None
    todo_count = len(result.todos)
    raw_dynamic_line = value.get("dynamic_line")
    dynamic_line, dynamic_line_issue = _talk_text(raw_dynamic_line)
    if dynamic_line is None:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: talk topic {topic_id} "
            f"{dynamic_line_issue or 'dynamic_line needs manual conversion'}",
        )
        dynamic_line = "[Lua-first dialogue line requires manual conversion]"
    responses: list[dict[str, Any]] = []
    raw_responses = value.get("responses", [])
    if not isinstance(raw_responses, list):
        result.add_todo("manual_rewrite", f"{source.location}: talk topic {topic_id} responses need review")
        raw_responses = []
    for entry in raw_responses:
        if not isinstance(entry, dict):
            result.add_todo("manual_rewrite", f"{source.location}: talk topic {topic_id} response needs a static text")
            continue
        if "truefalsetext" in entry:
            truefalse = entry["truefalsetext"]
            if (
                isinstance(truefalse, dict) and
                set(truefalse) in (
                    {"true", "false"}, {"true", "false", "condition"},
                ) and
                isinstance(truefalse["true"], str) and
                isinstance(truefalse["false"], str)
            ):
                if "condition" in truefalse:
                    text_condition = render_talk_topic_response_condition(
                        truefalse["condition"]
                    )
                    if text_condition is None:
                        result.add_todo(
                            "manual_rewrite",
                            f"{source.location}: talk topic {topic_id} truefalsetext "
                            "condition needs Lua conversion; response skipped",
                        )
                        continue
                else:
                    # Native read_condition defaults a missing truefalsetext
                    # condition to true.
                    text_condition = LuaRaw("true")
                response = {
                    "text": truefalse["true"],
                    "text_translation": {},
                    "text_condition": text_condition,
                    "false_text": truefalse["false"],
                    "false_text_translation": {},
                }
            else:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: talk topic {topic_id} truefalsetext needs "
                    "manual shape and translation review; response skipped",
                )
                continue
        else:
            if not isinstance(entry.get("text"), str):
                result.add_todo("manual_rewrite", f"{source.location}: talk topic {topic_id} response needs a static text")
                continue
            response = {
                "text": entry["text"],
                # JSON talk_response::talk_response reads this as a translation;
                # authored Lua strings remain literal unless marked explicitly.
                "text_translation": {},
            }
        converted_condition = None
        converted_opinion = False
        if isinstance(entry.get("topic"), str) and entry["topic"]:
            response["topic"] = entry["topic"]
        if "condition" in entry:
            condition = render_talk_topic_response_condition(entry["condition"])
            converted_condition = condition
            if condition is None:
                # A TODO condition must not silently make the response
                # unconditional in the declarative Platform topic.
                response["condition"] = LuaRaw("false")
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: talk topic {topic_id} response condition needs Lua conversion"
                )
            else:
                response["condition"] = condition
        for switch_field in ("switch", "default"):
            if isinstance(entry.get(switch_field), bool):
                response[switch_field] = entry[switch_field]
        if "effect" in entry:
            action_callback = render_talk_topic_mission_failure_action(entry)
            if action_callback is None:
                action_callback = render_talk_topic_mission_success_action(
                    entry, converted_condition,
                )
            if action_callback is None:
                action_callback = render_talk_topic_mission_reward_action(
                    entry, converted_condition,
                )
            if action_callback is None:
                action_callback = render_talk_topic_clear_mission_action(entry)
            if action_callback is None and set(entry) <= {"text", "topic", "effect"}:
                action_callback = render_dialogue_mission_action_effect(
                    entry["effect"]
                )
                if action_callback is None:
                    action_callback = render_dialogue_spend_cash_action_effect(
                        entry["effect"]
                    )
                if action_callback is None:
                    action_callback = render_dialogue_item_grant_action_effect(
                        entry["effect"]
                    )
                if action_callback is None:
                    action_callback = render_dialogue_stolen_item_action_effect(
                        entry["effect"]
                    )
            elif action_callback is None and (
                set(entry) <= {"text", "topic", "condition", "effect"} and
                converted_condition is not None
            ):
                # Native evaluates the response condition before selection;
                # the grant runs in the response effect phase after selection.
                action_callback = render_dialogue_item_grant_action_effect(
                    entry["effect"]
                )
            elif (
                set(entry) == {"text", "topic", "condition", "effect", "opinion"} and
                converted_condition is not None and
                isinstance(entry["opinion"], dict) and entry["opinion"] and
                set(entry["opinion"]) <= {"trust", "fear", "value", "anger", "owed", "sold"} and
                all(type(value) is int and NATIVE_INT_MIN <= value <= NATIVE_INT_MAX
                    for value in entry["opinion"].values())
            ):
                # Native talk_effect_t::apply runs the effect vector first,
                # then applies the response's opinion to dialogue beta.
                action_callback = render_dialogue_stolen_item_action_effect(
                    entry["effect"]
                )
                if action_callback is not None:
                    response["success_opinion"] = entry["opinion"]
                    converted_opinion = True
            if action_callback is None:
                action_callback = render_talk_topic_weapon_away_action(
                    entry, converted_condition,
                )
                if action_callback is not None:
                    response["success_opinion"] = entry["opinion"]
                    response["success_consequence"] = "helpless"
                    converted_opinion = True
            if action_callback is None:
                action_callback = render_talk_topic_npc_lose_morale_action(
                    entry, known_morale_ids,
                )
            if action_callback is None:
                action_callback = render_talk_topic_item_offer_effect(entry)
            if action_callback is None:
                action_callback = render_talk_topic_pet_purchase_action(entry)
            if action_callback is None:
                action_callback = render_dialogue_sell_item_action_effect(
                    entry, converted_condition,
                )
                if action_callback is not None and "opinion" in entry:
                    response["success_opinion"] = entry["opinion"]
                    converted_opinion = True
            if action_callback is not None:
                response["on_action"] = action_callback
            else:
                callback = render_dialogue_trade_effect(
                    entry["effect"], result, source.location,
                    f"topic {topic_id} response",
                )
                if callback is not None:
                    response["on_select"] = callback
                else:
                    trade_todo = _legacy_trade_action_effect_todo(entry["effect"])
                    item_offer_todo = _talk_topic_item_offer_todo(entry)
                    camp_todo = _camp_selector_todo(entry["effect"])
                    camp_object_todo = _camp_selector_object_todo(entry["effect"])
                    food_todo = _distribute_food_auto_todo(entry["effect"])
                    response_effect_todo = _talk_topic_effect_todo(
                        entry["effect"]
                    )
                    if item_offer_todo is not None:
                        response_effect_category, response_effect_reason = item_offer_todo
                    elif camp_todo is not None:
                        response_effect_category, response_effect_reason = camp_todo
                    elif camp_object_todo is not None:
                        response_effect_category = "semantic_choice"
                        response_effect_reason = camp_object_todo
                    elif food_todo is not None:
                        response_effect_category = "platform_gap"
                        response_effect_reason = food_todo
                    elif trade_todo is not None:
                        response_effect_category = "manual_rewrite"
                        response_effect_reason = trade_todo
                    elif response_effect_todo is not None:
                        response_effect_category, response_effect_reason = response_effect_todo
                    else:
                        response_effect_category = "manual_rewrite"
                        response_effect_reason = "needs a native callback"
                    result.add_todo(
                        response_effect_category,
                        f"{source.location}: talk topic {topic_id} response effect "
                        f"{response_effect_reason}"
                    )
        responses.append(response)
        supported_fields = {
            "text", "topic", "condition", "effect", "switch", "default",
            "truefalsetext",
        }
        if converted_opinion:
            supported_fields.add("opinion")
        unsupported = set(entry) - supported_fields
        if unsupported:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: talk topic {topic_id} response fields need Lua conversion: " +
                ", ".join(sorted(unsupported))
            )
    descriptor: dict[str, Any] = {
        "id": topic_id,
        "dynamic_line": dynamic_line,
        "responses": responses,
    }
    if isinstance(raw_dynamic_line, str):
        descriptor["dynamic_line_translation"] = {}
    if isinstance(value.get("insert_before_standard_exits"), bool):
        descriptor["insert_before_standard_exits"] = value["insert_before_standard_exits"]
    if isinstance(value.get("replace_built_in_responses"), bool):
        descriptor["replace_built_in_responses"] = value["replace_built_in_responses"]
    raw_repeat = value.get("repeat_responses")
    if isinstance(raw_repeat, list):
        repeats: list[dict[str, Any]] = []
        for entry in raw_repeat:
            if isinstance(entry, dict) and isinstance(entry.get("for_item"), str):
                response = entry.get("response")
                if isinstance(response, dict) and isinstance(response.get("text"), str):
                    repeats.append({
                        "item": entry["for_item"],
                        "response": {
                            "text": response["text"],
                            "text_translation": {},
                            **({"topic": response["topic"]} if isinstance(response.get("topic"), str) else {}),
                        },
                    })
                    continue
            result.add_todo("manual_rewrite", f"{source.location}: talk topic {topic_id} repeat response needs review")
        if repeats:
            descriptor["repeat_responses"] = repeats
    if "speaker_effect" in value:
        raw_effects = value["speaker_effect"]
        if not isinstance(raw_effects, list):
            raw_effects = [raw_effects]
        callbacks: list[LuaRaw] = []
        for raw_effect in raw_effects:
            callback = render_dialogue_trade_effect(
                raw_effect, result, source.location,
                f"talk topic {topic_id} speaker_effect",
            )
            if callback is None:
                trade_todo = _legacy_trade_action_effect_todo(raw_effect)
                speaker_effect_value = raw_effect
                if (
                    isinstance(raw_effect, dict) and
                    set(raw_effect) <= {"effect", "opinion", "mission_opinion"} and
                    isinstance(raw_effect.get("effect"), str)
                ):
                    speaker_effect_value = raw_effect["effect"]
                food_todo = _distribute_food_auto_todo(speaker_effect_value)
                result.add_todo(
                    "platform_gap" if food_todo is not None else "manual_rewrite",
                    f"{source.location}: talk topic {topic_id} speaker_effect "
                    f"{food_todo or trade_todo or 'needs a native callback'}"
                )
            else:
                callbacks.append(callback)
        if callbacks and len(callbacks) == len(raw_effects):
            descriptor["speaker_effects"] = callbacks[0] if len(callbacks) == 1 else callbacks
    lines = ["ccb.dialogue.register_topic(", _lua_literal(descriptor), ")"]
    supported = {
        "type", "id", "dynamic_line", "responses", "repeat_responses", "speaker_effect",
        "insert_before_standard_exits", "replace_built_in_responses", "//", "//1", "//2", "//3", "//4",
    }
    unresolved = unresolved_fields(value, supported)
    if unresolved:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: talk topic {topic_id} unresolved fields: {', '.join(unresolved)}"
        )
    (result.partial if len(result.todos) != todo_count else result.converted).append(
        f"{source.location}: talk topic {topic_id}"
    )
    return "\n".join(lines) + "\n"


def render_overmap_connection(
    source: SourceObject, result: MigrationResult
) -> str | None:
    value = source.value
    connection_id = value.get("id")
    if not safe_platform_id(connection_id):
        result.partial.append(f"{source.location}: overmap connection <invalid id>")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: overmap connection needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    lines = [
        "local definition = content.OvermapConnection {",
        f"    id = {lua_quote(connection_id)},",
        "}",
    ]
    raw_subtypes = value.get("subtypes")
    if isinstance(raw_subtypes, list) and raw_subtypes:
        for raw_subtype in raw_subtypes:
            if not isinstance(raw_subtype, dict):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: overmap connection {connection_id} "
                    "subtype needs review"
                )
                continue
            terrain = raw_subtype.get("terrain")
            basic_cost = raw_subtype.get("basic_cost", 0)
            locations = raw_subtype.get("locations", [])
            raw_flags = raw_subtype.get("flags", [])
            flags_valid = (
                isinstance(raw_flags, list) and
                all(
                    isinstance(flag, str) and
                    flag in {"ORTHOGONAL", "PERPENDICULAR_CROSSING"}
                    for flag in raw_flags
                )
            )
            if (
                not isinstance(terrain, str) or not terrain or
                not isinstance(basic_cost, int) or
                isinstance(basic_cost, bool) or
                not 0 <= basic_cost <= NATIVE_INT_MAX or
                not isinstance(locations, list) or
                any(
                    not isinstance(location, str) or not location
                    for location in locations
                ) or
                not flags_valid or
                any(
                    field in raw_subtype
                    for field in set(raw_subtype) - {
                        "terrain", "basic_cost", "locations", "flags"
                    }
                )
            ):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: overmap connection {connection_id} "
                    "subtype needs review"
                )
                continue
            lines.append(
                f"definition:subtype({lua_quote(terrain)}, {basic_cost}, " +
                "{ " + ", ".join(
                    lua_quote(location) for location in locations
                ) + " }, " +
                f"{'true' if 'ORTHOGONAL' in raw_flags else 'false'}, " +
                f"{'true' if 'PERPENDICULAR_CROSSING' in raw_flags else 'false'})"
            )
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: overmap connection {connection_id} "
            "subtypes need review"
        )
    return finish_catalog(
        source,
        result,
        "overmap connection",
        connection_id,
        lines,
        {"type", "id", "subtypes", "//"},
        todo_count,
    )


def render_monster_group(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    group_id = value.get("id")
    if not safe_platform_id(group_id):
        result.partial.append(f"{source.location}: monster group <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: monster group needs a stable native id")
        return None
    todo_count = len(result.todos)
    lines = [
        "local definition = content.MonsterGroup {",
        f"    id = {lua_quote(group_id)},",
    ]
    default_monster = value.get("default")
    if default_monster is None:
        pass
    elif isinstance(default_monster, str) and default_monster:
        lines.append(f"    default_monster = {lua_quote(default_monster)},")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: monster group {group_id} default needs review"
        )
    is_animal = value.get("is_animal")
    if is_animal is None:
        pass
    elif isinstance(is_animal, bool):
        lines.append(f"    is_animal = {'true' if is_animal else 'false'},")
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: monster group {group_id} is_animal needs review"
        )
    lines.append("}")
    raw_monsters = value.get("monsters")
    if isinstance(raw_monsters, list) and raw_monsters:
        for raw_entry in raw_monsters:
            if not isinstance(raw_entry, dict):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: monster group {group_id} entry needs review"
                )
                continue
            entry_id = raw_entry.get("monster", raw_entry.get("group"))
            if not isinstance(entry_id, str) or not entry_id:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: monster group {group_id} entry needs review"
                )
                continue
            weight = raw_entry.get("weight", raw_entry.get("freq", 1))
            cost = raw_entry.get("cost_multiplier", 1)
            raw_pack = raw_entry.get("pack_size", [1, 1])
            pack_valid = (
                isinstance(raw_pack, list) and len(raw_pack) == 2 and
                all(
                    isinstance(part, int) and not isinstance(part, bool) and
                    1 <= part <= NATIVE_INT_MAX
                    for part in raw_pack
                ) and raw_pack[0] <= raw_pack[1]
            )
            if any(
                field in raw_entry
                for field in ("starts", "ends", "conditions", "event", "spawn_data")
            ) or not (
                isinstance(weight, int) and not isinstance(weight, bool) and
                weight >= 1
            ) or not (
                isinstance(cost, int) and not isinstance(cost, bool) and
                cost >= 0
            ) or not pack_valid:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: monster group {group_id} entry "
                    f"{entry_id} needs review"
                )
                continue
            method = "monster" if "monster" in raw_entry else "group"
            lines.append(
                f"definition:{method}({lua_quote(entry_id)}, "
                f"{weight}, {cost}, {raw_pack[0]}, {raw_pack[1]})"
            )
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: monster group {group_id} monsters need review"
        )
    return finish_catalog(
        source,
        result,
        "monster group",
        group_id,
        lines,
        {
            "type", "id", "default", "is_animal", "monsters", "//", "//2",
        },
        todo_count,
    )


def render_item_action(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    action_id = value.get("id")
    if not safe_platform_id(action_id):
        result.partial.append(f"{source.location}: item action <invalid id>")
        result.add_todo("manual_rewrite", f"{source.location}: item action needs a stable id")
        return None
    todo_count = len(result.todos)
    name = display_text(value.get("name"), action_id)
    lines = [
        "local definition = content.ItemAction {",
        f"    id = {lua_quote(action_id)},",
        f"    name = {lua_quote(name)},",
        "}",
    ]
    return finish_catalog(
        source,
        result,
        "item action",
        action_id,
        lines,
        {"type", "id", "name", "//"},
        todo_count,
    )


def render_butchery_requirement(
    source: SourceObject, result: MigrationResult
) -> str | None:
    value = source.value
    requirement_id = value.get("id")
    if not safe_platform_id(requirement_id):
        result.partial.append(f"{source.location}: butchery requirement <invalid id>")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: butchery requirement needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    size_names = ("TINY", "SMALL", "MEDIUM", "LARGE", "HUGE")
    butcher_names = (
        "BLEED", "QUICK", "FULL", "FIELD_DRESS", "SKIN", "QUARTER",
        "DISMEMBER", "DISSECT",
    )
    lines = [
        "local definition = content.ButcheryRequirement {",
        f"    id = {lua_quote(requirement_id)},",
        "}",
    ]
    raw_rows = value.get("requirements")
    if isinstance(raw_rows, dict):
        for raw_speed, raw_sizes in raw_rows.items():
            try:
                speed = float(raw_speed)
            except (TypeError, ValueError):
                speed = float("nan")
            if not math.isfinite(speed) or speed < 0 or \
                    not isinstance(raw_sizes, list) or \
                    len(raw_sizes) != len(size_names):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: butchery requirement {requirement_id} "
                    f"speed row {raw_speed!r} needs review"
                )
                continue
            for size_index, raw_size in enumerate(raw_sizes):
                if not isinstance(raw_size, dict) or any(
                    name not in raw_size or
                    not isinstance(raw_size[name], str) or
                    not raw_size[name]
                    for name in butcher_names
                ):
                    result.add_todo(
                        "manual_rewrite",
                        f"{source.location}: butchery requirement {requirement_id} "
                        f"size row {size_names[size_index]} needs review"
                    )
                    continue
                for name in butcher_names:
                    lines.append(
                        "definition:requirement("
                        f"{lua_number(speed)}, {lua_quote(size_names[size_index])}, "
                        f"{lua_quote(name)}, {lua_quote(raw_size[name])})"
                    )
    else:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: butchery requirement {requirement_id} "
            "requirements need review"
        )
    return finish_catalog(
        source,
        result,
        "butchery requirement",
        requirement_id,
        lines,
        {"type", "id", "requirements"},
        todo_count,
    )


def render_scent_type(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
