def _bounded_content_value(value: Any, depth: int = 0) -> bool:
    """Validate the JSON-to-Lua descriptor tree before generic lowering."""
    if depth > 16:
        return False
    if value is None or isinstance(value, (bool, int)):
        return True
    if isinstance(value, float):
        return math.isfinite(value)
    if isinstance(value, str):
        return bounded_utf8_string(value, 32768, allow_empty=True)
    if isinstance(value, list):
        return len(value) <= 4096 and all(
            _bounded_content_value(entry, depth + 1) for entry in value
        )
    if isinstance(value, dict):
        return len(value) <= 4096 and all(
            isinstance(key, str) and bounded_utf8_string(key, 256, allow_empty=False) and
            _bounded_content_value(entry, depth + 1)
            for key, entry in value.items()
        )
    return False


def normalize_generic_platform_payload(
    kind: str, payload: dict[str, Any]
) -> dict[str, Any]:
    """Adapt legacy spelling/translation shapes to typed builder options.

    Generic builders intentionally expose domain names rather than parser
    aliases.  Keeping this normalization in the extractor makes generated
    Lua executable for real legacy objects while retaining unknown fields for
    the builder's explicit bounded-field audit.
    """
    result = copy.deepcopy(payload)
    field_aliases = {
        "sym": "symbol",
        "mondensity": "monster_density",
        "likes_u": "likes",
        "respects_u": "respects",
        "known_by_u": "known",
        "fac_food_supply": "food_calories",
        "mon_faction": "monster_faction",
        "name_unique": "unique_name",
        "name_suffix": "suffix",
        "mission_offered": "missions_offered",
        "worn_override": "worn",
        "carry_override": "carry",
        "weapon_override": "weapon",
        "bonus_str": "strength",
        "bonus_dex": "dexterity",
        "bonus_int": "intelligence",
        "bonus_per": "perception",
        "bonus_aggression": "aggression",
        "bonus_bravery": "bravery",
        "bonus_collector": "collector",
        "bonus_altruism": "altruism",
    }
    if kind in {"overmap_terrain", "faction", "npc", "npc_class"}:
        for old, new in field_aliases.items():
            if old in result and new not in result:
                result[new] = result[old]
    # JSON translation objects are valid legacy values but the bounded native
    # constructors intentionally accept one resolved author-facing string.
    for field_name in (
        "name", "description", "desc", "job_description", "label",
        "string", "text", "suffix", "temporary_suffix",
    ):
        if isinstance(result.get(field_name), dict):
            result[field_name] = display_text(result[field_name], "")
    variants = result.get("variants")
    if isinstance(variants, list):
        normalized_variants: list[Any] = []
        for variant in variants:
            if not isinstance(variant, dict):
                normalized_variants.append(variant)
                continue
            item = copy.deepcopy(variant)
            if "symbols_broken" in item and "broken_symbols" not in item:
                item["broken_symbols"] = item["symbols_broken"]
            normalized_variants.append(item)
        result["variants"] = normalized_variants
    return result


def typed_inheritance_payload(
    value: dict[str, Any],
    result: MigrationResult,
    *,
    label: str,
    location: str,
    inheritance_corpus: dict[str, dict[str, Any]] | None,
) -> tuple[bool, dict[str, Any] | None]:
    """Lower the small set of native collection patches kept by Platform.

    This intentionally handles only the two registrars whose native builders
    expose typed patch descriptors.  Every other legacy patch continues
    through the generic resolver, which either flattens a proven literal or
    emits an explicit TODO.
    """
    if label not in {"vehicle_part", "vehicle"}:
        return False, None
    if not any(key in value for key in ("copy-from", "extend", "delete")):
        return False, None

    object_id = stable_id(value, "<invalid id>")
    parent = value.get("copy-from")
    if not isinstance(parent, str) or not safe_platform_id(parent):
        result.partial.append(f"{location}: {label} {object_id}")
        result.add_todo(
            "manual_rewrite",
            f"{location}: {label} copy-from must name one safe concrete parent"
        )
        return True, None
    parent_value = (
        inheritance_corpus.get(parent) if inheritance_corpus is not None else None
    )
    if not isinstance(parent_value, dict) or not isinstance(
        parent_value.get("id"), str
    ):
        result.partial.append(f"{location}: {label} {object_id}")
        result.add_todo(
            "manual_rewrite",
            f"{location}: {label} copy-from parent '{parent}' needs a concrete "
            "Platform definition in the migration corpus"
        )
        return True, None

    allowed = (
        {"categories", "flags", "emissions", "exhaust"}
        if label == "vehicle_part"
        else {"parts"}
    )
    typed_patch: dict[str, Any] = {}
    operations: dict[str, dict[str, list[Any]]] = {
        "extend": {},
        "delete": {},
    }
    for operation in ("extend", "delete"):
        raw_patch = value.get(operation)
        if raw_patch is None:
            continue
        if not isinstance(raw_patch, dict):
            result.partial.append(f"{location}: {label} {object_id}")
            result.add_todo(
                "manual_rewrite",
                f"{location}: {label} {operation} must be an object with typed members"
            )
            return True, None
        for member, raw_entries in raw_patch.items():
            if member not in allowed:
                result.partial.append(f"{location}: {label} {object_id}")
                result.add_todo(
                    "manual_rewrite",
                    f"{location}: {label} {operation}.{member} is not supported by the Platform patch"
                )
                return True, None
            if member in value:
                result.partial.append(f"{location}: {label} {object_id}")
                result.add_todo(
                    "manual_rewrite",
                    f"{location}: {label} {member} cannot combine a direct replacement with "
                    f"{operation}"
                )
                return True, None
            entries = raw_entries if isinstance(raw_entries, list) else None
            if not entries or not all(_bounded_content_value(entry) for entry in entries):
                result.partial.append(f"{location}: {label} {object_id}")
                result.add_todo(
                    "manual_rewrite",
                    f"{location}: {label} {operation}.{member} must be a non-empty literal array"
                )
                return True, None
            if label == "vehicle_part":
                if not all(isinstance(entry, str) and safe_platform_id(entry)
                           for entry in entries):
                    result.partial.append(f"{location}: {label} {object_id}")
                    result.add_todo(
                        "manual_rewrite",
                        f"{location}: {label} {operation}.{member} needs safe literal ids"
                    )
                    return True, None
            else:
                allowed_fields = {
                    "x", "y", "part", "variant", "with_ammo",
                    "ammo_types", "ammo_quantity", "fuel", "tools",
                }
                for entry in entries:
                    if not isinstance(entry, dict) or \
                            set(entry).difference(allowed_fields) or \
                            not isinstance(entry.get("part"), str) or \
                            not safe_platform_id(entry["part"]) or \
                            not isinstance(entry.get("x", 0), int) or \
                            isinstance(entry.get("x", 0), bool) or \
                            not isinstance(entry.get("y", 0), int) or \
                            isinstance(entry.get("y", 0), bool):
                        result.partial.append(f"{location}: {label} {object_id}")
                        result.add_todo(
                            "manual_rewrite",
                            f"{location}: {label} {operation}.{member} contains an unsupported "
                            "or non-literal vehicle placement"
                        )
                        return True, None
            operations[operation][member] = copy.deepcopy(entries)
            typed_patch[f"{operation}_{member}"] = copy.deepcopy(entries)

    for member in allowed:
        extended = operations["extend"].get(member, [])
        deleted = operations["delete"].get(member, [])
        if label == "vehicle_part":
            if set(extended).intersection(deleted):
                result.partial.append(f"{location}: {label} {object_id}")
                result.add_todo(
                    "manual_rewrite",
                    f"{location}: {label} has conflicting extend/delete entries for {member}"
                )
                return True, None
        elif any(entry in deleted for entry in extended):
            result.partial.append(f"{location}: {label} {object_id}")
            result.add_todo(
                "manual_rewrite",
                f"{location}: {label} has conflicting extend/delete placements"
            )
            return True, None

    payload = {
        key: copy.deepcopy(raw)
        for key, raw in value.items()
        if key not in {"type", "//", "abstract", "copy-from", "extend", "delete"}
    }
    payload["copy_from"] = parent
    if typed_patch:
        payload["patch"] = typed_patch
    return True, normalize_generic_platform_payload(label, payload)


def render_generic_platform_content(
    source: SourceObject, result: MigrationResult, builder: str, label: str,
    *, inheritance_corpus: dict[str, dict[str, Any]] | None = None,
) -> str | None:
    """Lower a checked descriptor into an existing typed Platform builder.

    The world-content transaction already owns native parsers for these
    families.  This renderer only supplies a bounded Lua table; it does not
    create a JSON loader.  Legacy inheritance directives are flattened before
    rendering with ``resolve_generic_copy_from`` so the generated Lua contains
    the effective descriptor rather than parser-shaped keys.
    """
    value = source.value
    handled_typed_inheritance, typed_payload = typed_inheritance_payload(
        value,
        result,
        label=label,
        location=source.location,
        inheritance_corpus=inheritance_corpus,
    )
    if handled_typed_inheritance:
        if typed_payload is None:
            return None
        value = typed_payload
        source = SourceObject(source.path, source.index, typed_payload)
    elif any(key in value for key in ("copy-from", "extend", "delete")):
        if inheritance_corpus is None:
            object_id = stable_id(value, "<invalid id>")
            result.partial.append(f"{source.location}: {label} {object_id}")
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: {label} inheritance requires the migration corpus"
            )
            return None
        resolved, todos = resolve_generic_copy_from(
            value,
            inheritance_corpus,
            label=label,
            location=source.location,
        )
        if todos:
            object_id = stable_id(value, "<invalid id>")
            result.partial.append(f"{source.location}: {label} {object_id}")
            result.todos.extend(todos)
            return None
        value = resolved
        source = SourceObject(source.path, source.index, resolved)
    object_id = stable_id(value, f"anonymous_{source.index}")
    if label == "mission_definition":
        legacy_lifecycle = [
            key for key in ("start", "end", "fail", "goal_condition", "deadline")
            if key in value
        ]
        if legacy_lifecycle:
            # content.Mission accepts Lua phase handler IDs, not the native
            # mission_definition effect/condition objects. Its deadline table
            # also differs from native duration/expression values. Passing
            # these through the generic table loses behavior.
            result.partial.append(f"{source.location}: {label} {object_id}")
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: {label} {object_id} legacy fields "
                f"{', '.join(legacy_lifecycle)} cannot pass through "
                "content.Mission: phase/goal objects need Lua handlers and "
                "deadline values need a bounded conversion"
            )
            return None
    raw_id = value.get("id")
    if raw_id is None and isinstance(value.get("abstract"), str):
        # Abstract generic-factory parents are migration-time templates.  The
        # effective child receives their fields through copy-from, while
        # registering an empty-id native definition would be rejected by the
        # typed Platform constructor.
        result.converted.append(
            f"{source.location}: {label} abstract {value['abstract']} (template only)"
        )
        return (
            f"-- {label} abstract {lua_quote(value['abstract'])} "
            "is consumed by copy-from"
        )
    if not (
        isinstance(raw_id, str) and raw_id or
        isinstance(raw_id, list) and raw_id and
        all(isinstance(entry, str) and safe_platform_id(entry) for entry in raw_id)
    ):
        result.partial.append(f"{source.location}: {label} {object_id}")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: {label} {object_id} requires a stable string id"
        )
        return None
    identifiers = [raw_id] if isinstance(raw_id, str) else list(raw_id)
    payload = {
        key: copy.deepcopy(raw)
        for key, raw in value.items()
        if key not in {"type", "//", "copy-from", "extend", "delete"}
    }
    payload = normalize_generic_platform_payload(label, payload)
    if not _bounded_content_value(payload):
        result.partial.append(f"{source.location}: {label} {object_id}")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: {label} {object_id} descriptor exceeds the bounded Lua tree contract"
        )
        return None
    lines: list[str] = []
    for identifier in identifiers:
        definition_payload = copy.deepcopy(payload)
        definition_payload["id"] = identifier
        lines.extend((
            f"local definition = content.{builder}({_lua_literal(definition_payload)})",
            content_submit_expression(),
        ))
    result.converted.append(f"{source.location}: {label} {object_id}")
    return "\n".join(lines)


def report_missing_content_registrar(
    source: SourceObject, result: MigrationResult
) -> None:
    kind = source.value.get("type")
    object_id = stable_id(source.value, "<no stable id>")
    label = (
        f"{source.location}: {kind or '<missing type>'} {object_id} "
        "has no native Platform registrar"
    )
    result.partial.append(label)
    # A missing one-to-one JSON registrar is not by itself a reusable Platform
    # gap: passive JSON may remain, and a content owner must choose whether a
    # Lua authoring workflow is worth adding.
    result.add_todo("semantic_choice", label)


def render_blacklist(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    kind = {
        "ITEM_BLACKLIST": "item",
        "TRAIT_BLACKLIST": "trait",
        "MONSTER_BLACKLIST": "monster",
        "MONSTER_WHITELIST": "monster",
        "SCENARIO_BLACKLIST": "scenario",
        "profession_blacklist": "profession",
        "charge_removal_blacklist": "charge_removal",
        "temperature_removal_blacklist": "temperature_removal",
    }.get(value.get("type", ""))
    if kind is None:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: blacklist type needs review"
        )
        return None
    if kind not in ("item", "trait", "monster", "scenario", "profession",
                    "charge_removal", "temperature_removal"):
        result.partial.append(
            f"{source.location}: blacklist kind '{kind}' needs a native registrar"
        )
        # This is a content-owner decision, not evidence that a generic
        # Platform service is missing.
        result.add_todo(
            "semantic_choice",
            f"{source.location}: blacklist kind '{kind}' needs a native registrar"
        )
        return None
    todo_count = len(result.todos)
    # Blacklists are append-style registries: the native registrar forbids
    # edit/replace operations, so these definitions always submit through
    # content.add even in --replace mode.
    blacklist_submit = "content.add(definition)"
    whitelist = value.get("type") == "MONSTER_WHITELIST" or bool(
        value.get("whitelist")
    )
    if kind == "trait":
        entries_key = "traits"
    elif kind == "monster":
        entries_key = "monsters"
    elif kind in ("charge_removal", "temperature_removal"):
        entries_key = "list"
    elif kind == "profession":
        entries_key = "professions"
    elif kind == "scenario":
        entries_key = "scenarios"
    else:
        entries_key = "items"
    entries = value.get(entries_key, value.get("items", []))
    # An empty blacklist is a deliberate legacy value (e.g. the core
    # MONSTER_BLACKLIST starts with no entries) and must render as a
    # zero-entry definition, not as a review TODO.
    if not isinstance(entries, list):
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: blacklist entries need review"
        )
        return None
    lines = [
        "local definition = content.Blacklist {",
        f"    kind = {lua_quote(kind)},",
        f"    whitelist = {lua_boolean(whitelist)},",
        "}",
    ]
    for entry in entries:
        if isinstance(entry, str) and entry:
            lines.append(f"definition:entry({lua_quote(entry)})")
        else:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: blacklist entry needs review"
            )
            break
    status = (
        result.partial if len(result.todos) != todo_count else result.converted
    )
    status.append(f"{source.location}: blacklist {kind}")
    lines.extend((blacklist_submit, ""))
    return "\n".join(lines)


def render_map_extra(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    extra_id = value.get("id")
    if not safe_platform_id(extra_id):
        result.partial.append(f"{source.location}: map extra <invalid id>")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    name = value.get("name")
    if isinstance(name, dict):
        name = name.get("str")
    if not isinstance(name, str) or not name:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra {extra_id} name needs review"
        )
        name = extra_id
    lines = [
        "local definition = content.MapExtra {",
        f"    id = {lua_quote(extra_id)},",
        f"    name = {lua_quote(name)},",
    ]
    description = value.get("description")
    if isinstance(description, str) and description:
        lines.append(f"    description = {lua_quote(description)},")
    generator = value.get("generator")
    if isinstance(generator, dict):
        generator_id = generator.get("generator_id")
        if isinstance(generator_id, str) and generator_id:
            lines.append(f"    generator_id = {lua_quote(generator_id)},")
        else:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: map extra {extra_id} generator needs review"
            )
    elif "generator" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra {extra_id} generator needs review"
        )
    symbol = value.get("sym")
    if isinstance(symbol, str) and symbol:
        lines.append(f"    symbol = {lua_quote(symbol)},")
    elif "sym" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra {extra_id} symbol needs review"
        )
    color = value.get("color")
    if isinstance(color, str) and color:
        lines.append(f"    color = {lua_quote(color)},")
    elif "color" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra {extra_id} color needs review"
        )
    lines.append("}")
    flags = value.get("flags")
    if isinstance(flags, list) and all(
        isinstance(entry, str) and entry for entry in flags
    ):
        for flag in flags:
            lines.append(f"definition:flag({lua_quote(flag)})")
    elif "flags" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: map extra {extra_id} flags need review"
        )
    for member in ("min_max_zlevel", "autonote_visibility"):
        if member in value:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: map extra {extra_id} {member} needs review"
            )
    status = (
        result.partial if len(result.todos) != todo_count else result.converted
    )
    status.append(f"{source.location}: map extra {extra_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


def render_weather_generator(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    generator_id = value.get("id")
    if not safe_platform_id(generator_id):
        result.partial.append(
            f"{source.location}: weather generator <invalid id>"
        )
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: weather generator needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    lines = [
        "local definition = content.WeatherGenerator {",
        f"    id = {lua_quote(generator_id)},",
    ]
    for field_name, default in (
        ("base_temperature", 0.0), ("base_humidity", 0.0),
        ("base_pressure", 0.0), ("base_wind", 0.0),
    ):
        entry = value.get(field_name, default)
        if isinstance(entry, (int, float)) and not isinstance(entry, bool):
            lines.append(f"    {field_name} = {entry},")
        else:
            lines.append(f"    {field_name} = {default},")
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: weather generator {generator_id} {field_name} needs review"
            )
    for field_name in (
        "base_wind_distrib_peaks", "summer_temp_manual_mod",
        "spring_temp_manual_mod", "autumn_temp_manual_mod",
        "winter_temp_manual_mod", "spring_humidity_manual_mod",
        "summer_humidity_manual_mod", "autumn_humidity_manual_mod",
        "winter_humidity_manual_mod",
    ):
        entry = value.get(field_name, 0)
        if isinstance(entry, int) and not isinstance(entry, bool):
            lines.append(f"    {field_name} = {entry},")
        elif field_name in value:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: weather generator {generator_id} {field_name} needs review"
            )
    lines.append("}")
    for member, method in (("weather_black_list", "blacklisted_weather"),
                           ("weather_white_list", "whitelisted_weather")):
        entries = value.get(member)
        if isinstance(entries, list) and all(
            isinstance(entry, str) and entry for entry in entries
        ):
            for entry in entries:
                lines.append(f"definition:{method}({lua_quote(entry)})")
        elif member in value:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: weather generator {generator_id} {member} needs review"
            )
    for member in ("weather_types", "initial_weather"):
        if member in value:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: weather generator {generator_id} {member} needs review"
            )
    status = (
        result.partial if len(result.todos) != todo_count else result.converted
    )
    status.append(f"{source.location}: weather generator {generator_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


def render_migration(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    kind_map = {
        "MIGRATION": "item",
        "migration": "item",
        "item_migration": "item",
        "TRAIT_MIGRATION": "mutation",
        "spell_migration": "spell",
        "camp_migration": "camp",
        "mod_migration": "mod",
        "bionic_migration": "bionic",
        "effect_migration": "effect",
        "field_type_migration": "field_type",
        "oter_id_migration": "oter",
        "overmap_special_migration": "overmap_special",
        "proficiency_migration": "proficiency",
        "ter_furn_migration": "terrain",
        "trap_migration": "trap",
        "var_migration": "var",
        "vehicle_part_migration": "vehicle_part",
    }
    kind = kind_map.get(value.get("type", ""))
    if kind is None:
        result.partial.append(f"{source.location}: migration type needs review")
        # Passive JSON remains a valid input; no generic Platform capability is
        # demonstrated missing by an unregistered legacy migration kind.
        result.add_todo(
            "semantic_choice",
            f"{source.location}: migration type needs a native registrar"
        )
        return None
    todo_count = len(result.todos)
    # Migrations are append-style registries: the native registrar forbids
    # edit/replace operations, and its apply overwrites by from id, so these
    # definitions always submit through content.add even in --replace mode.
    migration_submit = "content.add(definition)"
    if kind == "terrain" or kind == "furniture":
        from_field = "from_ter" if kind == "terrain" else "from_furn"
        from_id = value.get(from_field)
        to_id = value.get("to_ter") if kind == "terrain" else value.get("to_furn")
        if kind == "terrain" and not isinstance(from_id, str):
            kind = "furniture"
            from_field = "from_furn"
            from_id = value.get(from_field)
            to_id = value.get("to_furn")
        if not isinstance(from_id, str) or not from_id:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: migration from id needs review"
            )
            from_id = ""
        if not isinstance(to_id, str) or not to_id:
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: migration to id needs review"
            )
            to_id = ""
    elif kind == "oter":
        pairs = value.get("oter_ids")
        if isinstance(pairs, dict) and pairs:
            lines = []
            for from_id, to_id in pairs.items():
                if not isinstance(from_id, str) or not isinstance(to_id, str):
                    result.add_todo(
                        "manual_rewrite",
                        f"{source.location}: migration oter_ids entry needs review"
                    )
                    continue
                # Each pair is wrapped in its own do/end block: a single
                # oter_ids object expands to hundreds of definitions and must
                # not exhaust the 200-local Lua limit.
                lines.extend(
                    (
                        "do",
                        "local definition = content.Migration {",
                        f"    kind = {lua_quote(kind)},",
                        f"    from = {lua_quote(from_id)},",
                        f"    to = {lua_quote(to_id)},",
                        "}",
                        migration_submit,
                        "end",
                        "",
                    )
                )
            status = (
                result.partial if len(result.todos) != todo_count
                else result.converted
            )
            status.append(f"{source.location}: migration {kind}")
            return "\n".join(lines)
        result.partial.append(
            f"{source.location}: migration oter_ids needs review"
        )
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: migration oter_ids needs review"
        )
        return None
    elif kind == "overmap_special":
        from_id = value.get("id")
        to_id = value.get("new_id", "")
    elif kind == "trap":
        from_id = value.get("from_trap")
        to_id = value.get("to_trap")
    elif kind == "field_type":
        from_id = value.get("from_field_type")
        to_id = value.get("to_field_type")
    elif kind in {"item", "mutation", "spell", "camp", "mod"}:
        from_id = value.get("id") or value.get("from") or value.get("from_id")
        to_id = value.get("replace") or value.get("to") or value.get("to_id") or ""
    else:
        from_id = value.get("from")
        to_id = value.get("to", "")
    if not isinstance(from_id, str) or not from_id:
        result.add_todo("manual_rewrite", f"{source.location}: migration from id needs review")
        from_id = ""
    if not isinstance(to_id, str):
        result.add_todo("manual_rewrite", f"{source.location}: migration to id needs review")
        to_id = ""
    # do/end wrapper keeps every definition from counting against the
    # 200-local limit in a file with hundreds of migration pairs.
    lines = [
        "do",
        "local definition = content.Migration {",
        f"    kind = {lua_quote(kind)},",
        f"    from = {lua_quote(from_id)},",
        f"    to = {lua_quote(to_id)},",
        "}",
        migration_submit,
        "end",
        "",
    ]
    status = (
        result.partial if len(result.todos) != todo_count else result.converted
    )
    status.append(f"{source.location}: migration {kind}")
    return "\n".join(lines)


def render_shopkeeper(source: SourceObject, result: MigrationResult) -> str | None:
    value = source.value
    rule_id = value.get("id")
    if not safe_platform_id(rule_id):
        result.partial.append(f"{source.location}: shopkeeper rule <invalid id>")
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: shopkeeper rule needs a stable native id"
        )
        return None
    todo_count = len(result.todos)
    kind = value.get("type")
    builder = {
        "shopkeeper_blacklist": "ShopkeeperBlacklist",
        "shopkeeper_whitelist": "ShopkeeperWhitelist",
        "shopkeeper_consumption_rates": "ShopkeeperConsumptionRates",
    }[kind]
    lines = [
        f"local definition = content.{builder} {{",
        f"    id = {lua_quote(rule_id)},",
    ]
    if kind == "shopkeeper_consumption_rates":
        default_rate = value.get("default_rate", 0)
        if isinstance(default_rate, int) and not isinstance(default_rate, bool):
            lines.append(f"    default_rate = {default_rate},")
        else:
            lines.append("    default_rate = 0,")
            result.add_todo(
                "manual_rewrite",
                f"{source.location}: shopkeeper rule {rule_id} default_rate needs review"
            )
    elif kind == "shopkeeper_whitelist" and isinstance(value.get("message"), str):
        lines.append(f"    message = {lua_quote(value['message'])},")
    lines.append("}")
    entries = value.get("entries")
    if isinstance(entries, list) and entries:
        for entry in entries:
            if not isinstance(entry, dict):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: shopkeeper rule {rule_id} entry needs review"
                )
                continue
            if "condition" in entry:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: shopkeeper rule {rule_id} entry condition needs review"
                )
            if "rate" in entry:
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: shopkeeper rule {rule_id} entry rate needs review"
                )
            item = entry.get("item", "")
            category = entry.get("category", "")
            item_group = entry.get("group", "")
            message = entry.get("message", "")
            fields = (item, category, item_group, message)
            if not all(isinstance(field, str) for field in fields):
                result.add_todo(
                    "manual_rewrite",
                    f"{source.location}: shopkeeper rule {rule_id} entry fields need review"
                )
                continue
            lines.append(
                f"definition:entry({lua_quote(item)}, {lua_quote(category)}, "
                f"{lua_quote(item_group)}, {lua_quote(message)})"
            )
    elif "entries" in value:
        result.add_todo(
            "manual_rewrite",
            f"{source.location}: shopkeeper rule {rule_id} entries need review"
        )
    status = (
        result.partial if len(result.todos) != todo_count else result.converted
    )
    status.append(f"{source.location}: shopkeeper rule {rule_id}")
    lines.extend((content_submit_expression(), ""))
    return "\n".join(lines)


