def lua_scalar_literal(value: Any) -> str | None:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, str):
        return lua_quote(value)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float) and math.isfinite(value):
        return lua_number(value)
    return None


def render_eoc_value_expression(
    value: Any, missing_default: str, actor_expression: str = "actor"
) -> str | None:
    literal = lua_scalar_literal(value)
    if literal is not None:
        return literal
    # JSON translation objects are still scalar values at the EOC boundary.
    # Preserve their text while discarding only metadata that has no runtime
    # meaning in a generated Lua variable payload; do not pass the object to a
    # JSON loader or emit arbitrary keys as executable code.
    if isinstance(value, dict) and "str" in value:
        if (
            set(value) <= {"str", "i18n", "//~"} and
            bounded_utf8_string(value.get("str"), 8192, allow_empty=True) and
            ("i18n" not in value or isinstance(value["i18n"], bool)) and
            ("//~" not in value or isinstance(value["//~"], str))
        ):
            return lua_quote(value["str"])
    if isinstance(value, dict) and set(value) == {"tripoint"}:
        coordinates = value.get("tripoint")
        if (
            isinstance(coordinates, list) and len(coordinates) == 3 and
            all(
                isinstance(entry, int) and not isinstance(entry, bool) and
                NATIVE_INT_MIN <= entry <= NATIVE_INT_MAX
                for entry in coordinates
            )
        ):
            return (
                "services.coords.tripoint_abs_ms(" +
                ", ".join(str(entry) for entry in coordinates) + ")"
            )
    if not isinstance(value, dict) or len(value) != 1:
        return None
    key, name = next(iter(value.items()))
    if key not in {"context_val", "u_val", "npc_val", "global_val", "var_val"}:
        return None
    if key == "context_val":
        # This path indexes the callback's Lua table directly and does not
        # call the bounded context-variable service.
        valid_name = lua_quotable_native_variable_string(name)
    elif key in {"u_val", "npc_val", "global_val"}:
        valid_name = lua_quotable_native_variable_string(name)
    else:
        valid_name = bounded_platform_context_variable_key(name)
    if not valid_name:
        return None
    quoted = lua_quote(name)
    if key == "context_val":
        return f"context.data[{quoted}]"
    if key == "global_val":
        return (
            "(service_value(services.variables.get_global(" + quoted + ")).value or " +
            missing_default + ")"
        )
    scope = {
        "u_val": "u",
        "npc_val": "npc",
        "var_val": "var",
    }[key]
    return (
        "(service_value(services.variables.resolve(context.data, "
        f"{actor_expression}, {lua_quote(scope)}, {quoted})).value or {missing_default})"
    )


@functools.lru_cache(maxsize=1)
def registered_native_event_types() -> frozenset[str]:
    """Return event names from the checked-in inventory generated from event.h."""
    inventory_path = (
        REPOSITORY_ROOT / "data" / "lua" / "reference" /
        "ccb_platform_native_inventory.json"
    )
    try:
        inventory = json.loads(inventory_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return frozenset()
    entries = inventory.get("event_types") if isinstance(inventory, dict) else None
    if not isinstance(entries, list):
        return frozenset()
    return frozenset(
        entry["type"] for entry in entries
        if isinstance(entry, dict) and isinstance(entry.get("type"), str) and
        bounded_utf8_string(entry["type"], 128, allow_empty=False)
    )


def _render_static_trigger_event_value(
    value: Any, depth: int, nodes: list[int]
) -> str | None:
    """Render bounded diag_value literals without Python/Lua coercion."""
    nodes[0] += 1
    if nodes[0] > 512 or depth > 8:
        return None
    if value is None:
        return "services.types.null"
    if isinstance(value, bool):
        # Native diag_value JSON does not accept JSON booleans.
        return None
    if isinstance(value, str):
        if depth > 0:
            try:
                if len(value.encode("utf-8")) > 8192:
                    return None
            except UnicodeEncodeError:
                return None
        return lua_quote(value)
    if isinstance(value, int):
        try:
            number = float(value)
        except OverflowError:
            return None
        return lua_number(number) if math.isfinite(number) else None
    if isinstance(value, float):
        return lua_number(value) if math.isfinite(value) else None
    if isinstance(value, list):
        if len(value) > 512:
            return None
        rendered = [
            _render_static_trigger_event_value(entry, depth + 1, nodes)
            for entry in value
        ]
        if any(entry is None for entry in rendered):
            return None
        return "{ " + ", ".join(rendered) + " }"
    if not isinstance(value, dict):
        return None
    if set(value) == {"tripoint"}:
        coordinates = value.get("tripoint")
        if (
            isinstance(coordinates, list) and len(coordinates) == 3 and
            all(
                isinstance(entry, int) and not isinstance(entry, bool) and
                NATIVE_INT_MIN <= entry <= NATIVE_INT_MAX
                for entry in coordinates
            )
        ):
            return (
                "services.coords.tripoint_abs_ms(" +
                ", ".join(str(entry) for entry in coordinates) + ")"
            )
        return None
    if (
        "str" in value and set(value) <= {"str", "i18n", "//~"} and
        bounded_utf8_string(value.get("str"), 8192, allow_empty=True) and
        ("i18n" not in value or isinstance(value["i18n"], bool)) and
        ("//~" not in value or isinstance(value["//~"], str))
    ):
        if value.get("i18n", False):
            return f"services.translate({lua_quote(value['str'])})"
        return lua_quote(value["str"])
    if set(value) == {"dbl"} and isinstance(value.get("dbl"), str):
        try:
            number = float(value["dbl"])
        except ValueError:
            return None
        return lua_number(number) if math.isfinite(number) else None
    return None


def _render_trigger_event_argument(
    value: Any, *, actor_expression: str | None,
    alpha_character_proven: bool, beta_expression: str | None,
    depth: int = 0, nodes: list[int] | None = None,
) -> str | None:
    """Render one value_or_var argument to native_events.emit's typed input."""
    if nodes is None:
        nodes = [0]
    static_value = _render_static_trigger_event_value(value, depth, nodes)
    if static_value is not None:
        return static_value
    if not isinstance(value, dict):
        return None
    variable_keys = {
        key for key in value
        if key in {"context_val", "u_val", "npc_val", "global_val"}
    }
    if len(variable_keys) != 1 or set(value) - variable_keys - {"default"}:
        return None
    key = next(iter(variable_keys))
    name = value.get(key)
    if not lua_quotable_native_variable_string(name):
        return None
    if key == "u_val" and (not alpha_character_proven or actor_expression is None):
        return None
    if key == "npc_val" and beta_expression is None:
        return None
    if "default" in value:
        default_expression = _render_static_trigger_event_value(
            value["default"], depth + 1, nodes
        )
        if default_expression is None:
            return None
    else:
        default_expression = "services.types.null"
    scope = {
        "context_val": "context",
        "u_val": "u",
        "npc_val": "npc",
        "global_val": "global",
    }[key]
    owner = actor_expression if key in {"u_val", "npc_val"} else "nil"
    participants = (
        ", { beta = " + beta_expression + " }"
        if key == "npc_val" and beta_expression is not None else ""
    )
    return (
        "(function() local resolved = service_value(services.variables.resolve("
        f"context.data, {owner}, {lua_quote(scope)}, {lua_quote(name)}{participants})); "
        f"if not resolved.exists then return {default_expression} end; "
        "if resolved.value == nil then return services.types.null end; "
        "return resolved.value end)()"
    )


def render_static_trigger_event(
    effect: dict[str, Any], *, actor_expression: str | None,
    alpha_character_proven: bool,
    beta_expression: str | None,
) -> tuple[list[str] | None, str | None]:
    """Lower the bounded native trigger_event value_or_var shape."""
    if set(effect) != {"trigger_event", "args"}:
        return None, "trigger_event requires only a registered event and an args array"
    event_name = effect.get("trigger_event")
    if (
        not isinstance(event_name, str) or
        not bounded_utf8_string(event_name, 128, allow_empty=False) or
        event_name not in registered_native_event_types()
    ):
        return None, "trigger_event name is not present in the native event registry"
    args = effect.get("args")
    if not isinstance(args, list) or len(args) > 64:
        return None, "trigger_event args must be a dense array with at most 64 entries"
    rendered_args: list[str] = []
    for entry in args:
        rendered = _render_trigger_event_argument(
            entry,
            actor_expression=actor_expression,
            alpha_character_proven=alpha_character_proven,
            beta_expression=beta_expression,
        )
        if rendered is None:
            return None, (
                "trigger_event argument needs a bounded native diag_value or a "
                "source-proven alpha/beta variable owner"
            )
        rendered_args.append(rendered)
    return [
        f"    services.native_events.emit({lua_quote(event_name)}, "
        "{ " + ", ".join(rendered_args) + " })"
    ], None


def render_eoc_string_expression(
    value: Any, actor_expression: str = "actor"
) -> str | None:
    if isinstance(value, str):
        return lua_quote(value)
    if isinstance(value, bool) or not isinstance(value, dict):
        return None
    if (
        set(value) == {"mutator", "mtype_id"} and
        value.get("mutator") == "mon_faction"
    ):
        monster_id = render_eoc_string_expression(
            value["mtype_id"], actor_expression
        )
        if monster_id is None:
            return None
        return (
            "(function() local definition = services.registry.get(\"monster\", " +
            monster_id + "); return definition and "
            "definition.default_faction.value or \"\" end)()"
        )
    if "str" in value and set(value) <= {"str", "i18n", "//~"}:
        if (
            bounded_utf8_string(value.get("str"), 8192, allow_empty=True) and
            ("i18n" not in value or isinstance(value["i18n"], bool)) and
            ("//~" not in value or isinstance(value["//~"], str))
        ):
            return lua_quote(value["str"])
    # String-valued EOC selectors commonly carry a bounded fallback alongside
    # a variable reference (``{global_val = "name", default = ""}``).  Keep
    # the fallback in the generated expression rather than rejecting the
    # otherwise typed variable lookup.  The numeric renderer already accepts
    # this shape; strings need the same semantics for place names, messages,
    # item ids, and dialogue topics.
    if "default" in value:
        variable_keys = {
            key for key in value
            if key in {"context_val", "u_val", "npc_val", "global_val", "var_val"}
        }
        if len(variable_keys) == 1 and set(value) == variable_keys | {"default"}:
            default = value.get("default")
            if not isinstance(default, str) or not bounded_utf8_string(
                default, 8192, allow_empty=True
            ):
                return None
            variable = {next(iter(variable_keys)): value[next(iter(variable_keys))]}
            rendered = render_eoc_value_expression(
                variable, lua_quote(default), actor_expression
            )
            return None if rendered is None else f"tostring(({rendered}) or {lua_quote(default)})"
    rendered = render_eoc_value_expression(value, lua_quote(""), actor_expression)
    return None if rendered is None else f"tostring(({rendered}) or {lua_quote('')})"


def render_eoc_numeric_expression(
    value: Any, missing_default: str, actor_expression: str = "actor"
) -> str | None:
    if isinstance(value, bool) or isinstance(value, str):
        return None
    if isinstance(value, (int, float)):
        return lua_scalar_literal(value)
    # Delegate native EOC math syntax to the bounded Platform expression
    # service.  This preserves the engine's variable/functions semantics for
    # expressions such as ``u_health()`` and ``rand(10)`` without introducing
    # a second parser in generated Lua.
    if isinstance(value, dict) and set(value) == {"math"}:
        expression = value.get("math")
        if (
            isinstance(expression, list) and len(expression) == 1 and
            isinstance(expression[0], str) and
            bounded_utf8_string(expression[0], 8192, allow_empty=False)
        ):
            return (
                "service_value(services.gameplay.math.evaluate("
                f"{lua_quote(expression[0])}, {actor_expression}, context.data))"
            )
    if isinstance(value, dict) and "default" in value:
        variable_keys = {
            key for key in value
            if key in {"context_val", "u_val", "npc_val", "global_val", "var_val"}
        }
        if len(variable_keys) == 1 and set(value) == variable_keys | {"default"}:
            default_literal = lua_scalar_literal(value.get("default"))
            if default_literal is None:
                return None
            variable = {next(iter(variable_keys)): value[next(iter(variable_keys))]}
            rendered = render_eoc_value_expression(
                variable, default_literal, actor_expression
            )
            if rendered is not None:
                return f"tonumber(({rendered}) or {default_literal})"
    rendered = render_eoc_value_expression(value, missing_default, actor_expression)
    return None if rendered is None else f"tonumber(({rendered}) or {missing_default})"


def render_mutation_id_expression(
    value: Any, known_mutation_ids: frozenset[str],
) -> str | None:
    """Render only a literal mutation ID found in source catalogs."""
    if safe_platform_id(value) and value in known_mutation_ids:
        return (
            'services.types.id("mutation", '
            f"{lua_quote(value)})"
        )
    return None


def render_mutation_category_expression(
    value: Any, known_category_ids: frozenset[str],
) -> str | None:
    """Render a category GameId, using nil for the native ANY sentinel."""
    if safe_platform_id(value) and value in known_category_ids:
        if value == "ANY":
            return "nil"
        return (
            'services.types.id("mutation_category", '
            f"{lua_quote(value)})"
        )
    return None


def render_mutation_chance_expression(value: Any) -> str | None:
    """Render only a static chance proven safe for the typed mutation API.

    Native EOC mutation evaluates a double and passes it to an int parameter,
    while the Platform API requires an integral value in its bounded range.
    A dynamic EOC value cannot prove that contract at migration time.
    """
    if isinstance(value, int) and not isinstance(value, bool):
        if 0 <= value <= MAX_MUTATION_RANDOM_CHANCE:
            return str(value)
        return None
    if isinstance(value, float) and math.isfinite(value):
        if value.is_integer() and 0 <= value <= MAX_MUTATION_RANDOM_CHANCE:
            return str(int(value))
        return None
    return None


def render_static_mutation_effect(
    effect: dict[str, Any],
    key: str,
    target_expression: str | None,
    known_mutation_ids: frozenset[str] = frozenset(),
    known_category_ids: frozenset[str] = frozenset(),
) -> list[str] | None:
    """Render one bounded u_/npc_ mutation effect through typed services."""
    if target_expression is None or key not in effect:
        return None
    if key in {"u_mutate", "npc_mutate"}:
        if set(effect) - {key, "use_vitamins"}:
            return None
        chance = render_mutation_chance_expression(effect[key])
        if chance is None:
            return None
        use_vitamins = effect.get("use_vitamins", True)
        if not isinstance(use_vitamins, bool):
            return None
        return [
            "    services.mutations.mutate(",
            f"        {target_expression}, {chance}, {lua_boolean(use_vitamins)})",
        ]
    if key in {"u_mutate_category", "npc_mutate_category"}:
        if set(effect) - {key, "use_vitamins", "true_random"}:
            return None
        category = render_mutation_category_expression(
            effect[key], known_category_ids
        )
        if category is None:
            return None
        use_vitamins = effect.get("use_vitamins", True)
        true_random = effect.get("true_random", False)
        if not isinstance(use_vitamins, bool) or not isinstance(true_random, bool):
            return None
        return [
            "    services.mutations.mutate_category(",
            f"        {target_expression}, {category}, "
            f"{lua_boolean(use_vitamins)}, {lua_boolean(true_random)})",
        ]
    if key in {"u_mutate_towards", "npc_mutate_towards"}:
        if set(effect) - {key, "category", "use_vitamins"}:
            return None
        # Native str_or_var's absent category evaluates to an empty ID. It is
        # not the Platform API's nil/ANY sentinel, so only migrate an explicit
        # valid category (including the explicit "ANY" sentinel).
        if "category" not in effect or effect["category"] is None:
            return None
        mutation = render_mutation_id_expression(
            effect[key], known_mutation_ids
        )
        category = render_mutation_category_expression(
            effect["category"], known_category_ids
        )
        if mutation is None or category is None:
            return None
        use_vitamins = effect.get("use_vitamins", True)
        if not isinstance(use_vitamins, bool):
            return None
        return [
            "    services.mutations.mutate_towards(",
            f"        {target_expression}, {mutation}, {category}, "
            f"{lua_boolean(use_vitamins)})",
        ]
    return None


def _effect_duration_expression(
    value: Any, target: str = "actor", alpha: str | None = None, beta: str | None = None,
) -> str | None:
    turns = parse_turns(value)
    if turns is not None:
        if not NATIVE_INT_MIN <= turns <= NATIVE_INT_MAX:
            return None
        return f'services.time.duration({turns}, "turn")'
    if isinstance(value, list):
        value = [parse_turns(endpoint) if parse_turns(endpoint) is not None else endpoint for endpoint in value]
    rendered = _effect_numeric_expression(value, target, alpha, beta)
    if rendered is None:
        return None
    # EOC duration conversion truncates toward zero. TimeDuration rejects
    # overflow; do not turn negative/long values into zero or one year.
    return (
        'services.time.duration((function(value) return value < 0 and math.ceil(value) '
        f'or math.floor(value) end)({rendered}), "turn")'
    )


def render_static_character_effect(
    effect: dict[str, Any],
    key: str,
    target_expression: str | None,
    *,
    target_kind: str | None = "character",
) -> list[str] | None:
    """Render one static u_/npc_add_effect without preserving EOC syntax."""
    if (
        target_expression is None or target_kind not in {"character", "monster", "creature"} or
        not safe_platform_id(effect.get(key))
    ):
        return None
    allowed_keys = {
        key, "duration", "intensity", "target_part", "force",
    }
    if set(effect) - allowed_keys:
        return None
    raw_duration = effect.get("duration")
    intensity = effect.get("intensity", 0)
    target_part = effect.get("target_part")
    force = effect.get("force", False)
    if target_part is not None and not safe_platform_id(target_part):
        return None
    if target_kind == "creature" and (
        target_part == "RANDOM" or isinstance(target_part, dict)
    ):
        # NPC_DEATH beta is the killer when present. Its kind is a runtime
        # Creature, and native add_effect treats RANDOM differently for a
        # monster talker than for a Character talker.
        return None
    if target_kind == "monster" and (
        target_part == "RANDOM" or isinstance(target_part, dict)
    ):
        # talker_monster::add_effect passes RANDOM through as a body-part ID;
        # it does not sample the avatar's random part like Character talkers.
        return None
    if not isinstance(force, bool):
        return None
    # Preserve zero duration: native application and later expiry are distinct.
    permanent = raw_duration == "PERMANENT"
    duration_expression = _effect_duration_expression(1 if permanent else raw_duration, target_expression)
    if duration_expression is None:
        return None
    if (
        not isinstance(intensity, int) or isinstance(intensity, bool) or
        not -NATIVE_MAX_EFFECT_INTENSITY <= intensity <= NATIVE_MAX_EFFECT_INTENSITY
    ):
        return None
    options: list[str] = []
    if target_part == "RANDOM":
        options.append("body_part = service_value(services.characters.random_body_part(services.characters.avatar(), true))")
    elif target_part is not None and target_part != "bp_null":
        options.append(
            "body_part = services.types.id(\"body_part\", "
            f"{lua_quote(target_part)})"
        )
    if permanent:
        options.append("permanent = true")
    if intensity:
        options.append(f"intensity = {intensity}")
    if force:
        options.append("force = true")
    result = [
        "    services.effects.add(",
        f"        {target_expression},",
        "        services.types.id(\"effect\", "
        f"{lua_quote(effect[key])}),",
    ]
    duration_literal = duration_expression
    if options:
        result.append(f"        {duration_literal}, {{ {', '.join(options)} }})")
    else:
        result.append(f"        {duration_literal})")
    return result


def render_static_character_morale(
    effect: dict[str, Any],
    key: str,
    target_expression: str | None,
) -> list[str] | None:
    """Render one static morale addition with native integer/time bounds.

    The source ID must name a registered morale type at runtime.  The shared
    ``safe_platform_id`` check validates text shape only; unknown native morale
    IDs are outside this lowering's equivalence claim.
    """
    if target_expression is None or not safe_platform_id(effect.get(key)):
        return None
    allowed_keys = {
        key, "bonus", "max_bonus", "duration", "decay_start", "capped",
    }
    if set(effect) - allowed_keys:
        return None
    bonus = effect.get("bonus")
    max_bonus = effect.get("max_bonus")
    bonus_range: list[int] | None = None
    if isinstance(bonus, list) and len(bonus) == 2 and all(
        isinstance(value, int) and not isinstance(value, bool) and
        -1000000000 <= value <= 1000000000 for value in bonus
    ):
        bonus_range = sorted(bonus)
        bonus = bonus_range[0]
    if (
        not isinstance(bonus, int) or isinstance(bonus, bool) or
        not NATIVE_INT_MIN <= bonus <= NATIVE_INT_MAX or
        not isinstance(max_bonus, int) or isinstance(max_bonus, bool) or
        not NATIVE_INT_MIN <= max_bonus <= NATIVE_INT_MAX
    ):
        return None
    options: list[str] = []
    for name in ("duration", "decay_start"):
        if name in effect:
            duration = parse_turns(effect[name])
            if duration is None or not 0 <= duration <= MAX_EFFECT_DURATION_TURNS:
                return None
            options.append(
                f"{name} = services.time.duration({duration}, \"turn\")"
            )
    capped = effect.get("capped", False)
    if not isinstance(capped, bool):
        return None
    if capped:
        options.append("capped = true")
    result: list[str] = []
    if bonus_range is not None:
        result.append(
            f"    local morale_bonus = services.random.int({bonus_range[0]}, {bonus_range[1]})"
        )
    result.extend([
        "    services.morale.add(",
        f"        {target_expression},",
        "        services.types.id(\"morale\", "
        f"{lua_quote(effect[key])}),",
        f"        {'morale_bonus' if bonus_range is not None else bonus}, {max_bonus}",
    ])
    if options:
        result[-1] += ", { " + ", ".join(options) + " })"
    else:
        result[-1] += ")"
    return result


def _effect_numeric_expression(
    value: Any, target: str, alpha: str | None, beta: str | None,
) -> str | None:
    if isinstance(value, list):
        if len(value) != 2 or any(isinstance(endpoint, list) for endpoint in value):
            return None
        for endpoint in value:
            literal = finite_number_literal(endpoint)
            if literal is not None and not -2147483648 <= math.trunc(literal) <= 2147483647:
                return None
        endpoints = [_effect_numeric_expression(endpoint, target, alpha, beta) for endpoint in value]
        if any(endpoint is None for endpoint in endpoints):
            return None
        # Native dbl_or_var calls integer rng: truncate toward zero before
        # ordering the endpoints. Keep runtime errors outside the random API's
        # supported bounds instead of silently clamping the distribution.
        return (
            '(function(lo, hi) lo = lo < 0 and math.ceil(lo) or math.floor(lo); '
            'hi = hi < 0 and math.ceil(hi) or math.floor(hi); '
            'return services.random.int(math.min(lo, hi), math.max(lo, hi)) end)('
            f'{endpoints[0]}, {endpoints[1]})'
        )
    if not isinstance(value, dict) or set(value) == {"math"}:
        return render_eoc_numeric_expression(value, "0", alpha or target)
    descriptor = dict(value)
    if "default" in descriptor:
        default = finite_number_literal(descriptor["default"])
        if default is None:
            return None
        descriptor["default"] = str(default)
    raw = render_participant_string_expression(descriptor, target, alpha, beta)
    return None if raw is None else f"(tonumber({raw}) or 0)"


def render_dynamic_character_effect(
    effect: dict[str, Any], key: str, target_expression: str | None,
    *, avatar_expression: str | None = None, npc_expression: str | None = None,
    target_kind: str | None = "character",
) -> list[str] | None:
    """Render variable-backed effect ids and durations."""
    if (
        target_expression is None or target_kind not in {"character", "monster", "creature"} or
        key not in effect or "duration" not in effect
    ):
        return None
    if set(effect) - {key, "duration", "intensity", "target_part", "force"}:
        return None
    alpha = avatar_expression or (target_expression if key.startswith("u_") else None)
    beta = npc_expression or (target_expression if key.startswith("npc_") else None)

    def identifier(value: Any, kind: str) -> str | None:
        if isinstance(value, dict):
            raw = render_participant_string_expression(value, target_expression, alpha, beta)
            return None if raw is None else f'services.types.id("{kind}", {raw})'
        return _dynamic_id_expression(value, kind, target_expression)

    def numeric(value: Any) -> str | None:
        return _effect_numeric_expression(value, target_expression, alpha, beta)

    effect_id = identifier(effect[key], "effect")
    permanent = effect.get("duration") == "PERMANENT"
    raw_duration = effect.get("duration", "1 turn")
    duration = _effect_duration_expression(1 if permanent else raw_duration, target_expression, alpha, beta)
    if effect_id is None or duration is None:
        return None
    intensity = numeric(effect.get("intensity", 0))
    if intensity is None:
        return None
    raw_intensity = effect.get("intensity", 0)
    if (
        isinstance(raw_intensity, (int, float)) and
        not isinstance(raw_intensity, bool) and
        (not math.isfinite(float(raw_intensity)) or
         not -NATIVE_MAX_EFFECT_INTENSITY <= int(raw_intensity) <= NATIVE_MAX_EFFECT_INTENSITY)
    ):
        return None
    target_part = effect.get("target_part")
    if target_kind == "creature" and (
        target_part == "RANDOM" or isinstance(target_part, dict)
    ):
        # Preserve the native Monster-vs-Character distinction for RANDOM.
        return None
    if target_kind == "monster" and (
        target_part == "RANDOM" or isinstance(target_part, dict)
    ):
        # A dynamic part can evaluate to RANDOM at runtime, whose native add
        # behavior differs for Monster and Character talkers.
        return None
    options: list[str] = []
    if target_part == "RANDOM":
        options.append("body_part = service_value(services.characters.random_body_part(services.characters.avatar(), true))")
    elif isinstance(target_part, dict):
        raw_part = render_participant_string_expression(target_part, target_expression, alpha, beta)
        if raw_part is None:
            return None
        options.append(f"body_part = {_effect_part_expression(raw_part)}")
    elif target_part is not None and target_part != "bp_null":
        part = identifier(target_part, "body_part")
        if part is None:
            return None
        options.append(f"body_part = {part}")
    if permanent:
        options.append("permanent = true")
    if intensity != "0":
        options.append(
            "intensity = (function(value) return value < 0 and math.ceil(value) "
            f"or math.floor(value) end)({intensity})"
        )
    force = effect.get("force", False)
    if not isinstance(force, bool):
        return None
    if force:
        options.append("force = true")
    suffix = ", { " + ", ".join(options) + " }" if options else ""
    return [
        "    service_value(services.effects.add(",
        f"        {target_expression}, {effect_id}, {duration}{suffix}))",
    ]


def _static_character_variable_descriptor(
    value: Any,
) -> tuple[str, str] | None:
    """Return an actor-variable descriptor for a bounded u_/npc_ var."""
    if not isinstance(value, dict) or len(value) != 1:
        return None
    key, name = next(iter(value.items()))
    if key not in {"u_val", "npc_val"}:
        return None
    if not bounded_utf8_string(name, 256):
        return None
    if any(ord(character) < 0x20 or ord(character) == 0x7F for character in name):
        return None
    return ("u" if key == "u_val" else "npc", name)


def _static_string_variable_descriptor(
    value: Any,
) -> tuple[str, str] | None:
    """Decode every bounded variable scope accepted by ``set_string_var``."""
    if not isinstance(value, dict) or len(value) != 1:
        return None
    key, name = next(iter(value.items()))
    scopes = {
        "u_val": "u",
        "npc_val": "npc",
        "global_val": "global",
        "context_val": "context",
        "var_val": "var",
    }
    if key not in scopes or not bounded_utf8_string(name, 256):
        return None
    if any(ord(character) < 0x20 or ord(character) == 0x7F for character in name):
        return None
    return scopes[key], name


def _coordinate_variable_descriptor(
    value: Any,
) -> tuple[str, str] | None:
    """Decode any scalar variable namespace that can carry a Tripoint.

    ``var_val`` follows the native bounded indirection service and is safe for
    callback-scoped reads/writes; the service rejects missing or malformed
    indirection instead of silently targeting an ambient variable.
    """
    if not isinstance(value, dict) or len(value) != 1:
        return None
    key, name = next(iter(value.items()))
    scopes = {
        "u_val": "u",
        "npc_val": "npc",
        "global_val": "global",
        "context_val": "context",
        "var_val": "var",
    }
    if key not in scopes or not bounded_utf8_string(name, 256):
        return None
    if any(ord(character) < 0x20 or ord(character) == 0x7F for character in name):
        return None
    return scopes[key], name


def _coordinate_numeric_expression(
    value: Any,
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
    require_integer: bool = False,
) -> str | None:
    """Render a bounded numeric coordinate adjustment with actor-correct vars."""
    actor_expression = "actor" if (avatar_actor_proven or npc_actor_proven) else "nil"
    if isinstance(value, list):
        if len(value) != 2:
            return None
        bounds = [
            _literal_integer_or_none(entry, -2147483648, 2147483647)
            for entry in value
        ]
        if any(bound is None for bound in bounds):
            return None
        lower, upper = sorted((int(bounds[0]), int(bounds[1])))
        return (
            str(lower) if lower == upper else
            f"services.random.int({lower}, {upper})"
        )
    if isinstance(value, dict) and len(value) == 1:
        key = next(iter(value))
        if key == "u_val":
            if not avatar_actor_proven:
                return None
            actor_expression = "actor"
        elif key == "npc_val":
            if not npc_actor_proven:
                return None
            actor_expression = "actor"
        elif key == "var_val":
            if not (avatar_actor_proven or npc_actor_proven):
                return None
            actor_expression = "actor"
    if require_integer:
        literal = _literal_integer_or_none(value, -2147483648, 2147483647)
        return None if literal is None else str(literal)
    rendered = render_eoc_numeric_expression(value, "0", actor_expression)
    if rendered is None:
        return None
    # Native dbl_or_var converts to int by truncating toward zero.  The
    # parentheses keep Lua from forwarding math.modf's fractional result;
    # the registered tripoint constructor rejects values outside native int.
    return f"(math.modf(({rendered})))"


def render_static_dimension_name(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Store the active dimension id in a proven Character variable."""
    if set(effect) != {"dimension_name"}:
        return None
    target = _coordinate_variable_descriptor(effect["dimension_name"])
    if target is None:
        return None
    dimension = "services.gameplay.environment.dimension()"
    if target[0] == "context":
        return [f"    context.data[{lua_quote(target[1])}] = {dimension}"]
    if target[0] == "global":
        return [
            "    services.variables.set_global(",
            f"        {lua_quote(target[1])}, {dimension})",
        ]
    if target[0] == "var":
        if not (avatar_actor_proven or npc_actor_proven):
            return None
        actor = "actor"
        return [
            "    service_value(services.variables.set_resolved(",
            f"        context.data, {actor}, \"var\", {lua_quote(target[1])}, {dimension}))",
        ]
    if target[0] == "u":
        if not avatar_actor_proven:
            return None
        handle = "actor"
    elif target[0] == "npc":
        if not npc_actor_proven:
            return None
        handle = "actor"
    else:
        return None
    return [
        "    services.variables.set(",
        f"        {handle}, {lua_quote(target[1])}, {dimension})",
    ]


def render_static_mirror_coordinates(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Keep fail-closed until var_info scope and value conversion are exact."""
    del effect, avatar_actor_proven, npc_actor_proven
    return None


def render_static_closest_city_effect(
    effect: dict[str, Any],
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Render closest_city for a proven actor-owned location variable.

    The legacy effect reads and writes the same var_info and also publishes
    city_name/city_size in dialogue context.  Keep dynamic/global/context
    var_info shapes fail-closed until the Lua runtime has an equivalent
    writable context-variable contract.
    """
    if "closest_city" not in effect:
        return None
    if set(effect) - {"closest_city", "known"}:
        return None
    target = _static_character_variable_descriptor(effect["closest_city"])
    if target is None:
        return None
    if target[0] == "u" and not avatar_actor_proven:
        return None
    if target[0] == "npc" and not npc_actor_proven:
        return None
    known = effect.get("known", True)
    if not isinstance(known, bool):
        return None
    return [
        "    local location = service_value(services.variables.get(",
        f"        actor, {lua_quote(target[1])}))",
        "    if location.exists then",
        "        local city = services.overmap.closest_city(",
        f"            location.value, {'true' if known else 'false'})",
        "        if city.ok then",
        "            services.variables.set(",
        f"                actor, {lua_quote(target[1])}, city.value.position)",
        "            context.data[\"city_name\"] = city.value.name",
        "            context.data[\"city_size\"] = city.value.size",
        "        end",
        "    end",
    ]


def render_static_teleport_effect(
    effect: dict[str, Any],
    monster_actor_proven: bool,
    avatar_actor_proven: bool = False,
    vehicle_actor_proven: bool = False,
    npc_actor_proven: bool = False,
    npc_actor_expression: str | None = None,
) -> list[str] | None:
    """Keep EOC teleport migration fail-closed without a proven target write.

    Native ``u_teleport`` reads a legacy variable as a tripoint, defaulting a
    missing value to the origin and allowing legacy conversions.  The typed
    Lua resolver represents a missing value with ``exists = false`` instead,
    so a global variable reference alone cannot be lowered equivalently.  A
    future migration needs a source-proven write with an exact coordinate
    type; the typed Platform service remains available to hand-written Lua.
    """
    del (
        effect,
        monster_actor_proven, vehicle_actor_proven, npc_actor_proven,
        npc_actor_expression, avatar_actor_proven,
    )
    return None


def render_static_npc_goal_effect(
    effect: dict[str, Any],
    key: str,
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Render a bounded literal overmap target for the NPC goal effect.

    The native mission-target parser accepts many dialogue/global variable and
    overmap-special shapes.  This slice deliberately accepts only a literal
    overmap terrain selector plus finite search/visibility/offset options and
    resolves it through the existing overmap search service before calling the
    typed NPC goal mutation.
    """
    if key not in {"u_set_goal", "npc_set_goal"} or set(effect) - {
        key, "true_eocs", "false_eocs",
    }:
        return None
    if effect.get("true_eocs") or effect.get("false_eocs"):
        return None
    if key == "u_set_goal":
        if not avatar_actor_proven:
            return None
    elif not npc_actor_proven:
        return None
    # Dynamic mission-target fields still need a dedicated resolver; literal
    # overmap-special matching is supported by the bounded search option.
    target = effect.get(key)
    if not isinstance(target, dict):
        return None
    allowed_target_fields = {
        "om_terrain", "om_terrain_match_type", "om_special",
        "reveal_radius", "origin_npc", "offset_x", "offset_y", "offset_z",
        "must_see", "cant_see", "random", "search_range", "min_distance",
        "z", "var", "om_terrain_replace",
    }
    if set(target) - allowed_target_fields:
        return None
    terrain = target.get("om_terrain")
    special = target.get("om_special")
    if (
        not safe_platform_id(terrain) or
        (special is not None and not safe_platform_id(special)) or
        any(
            field in target
            for field in (
                "om_terrain_match_type", "random", "z", "var",
                "om_terrain_replace",
            )
        )
    ):
        return None
    if target.get("origin_npc", False) is not False:
        return None
    if "reveal_radius" in target:
        reveal_radius = target["reveal_radius"]
        if (
            not isinstance(reveal_radius, int) or
            isinstance(reveal_radius, bool) or
            reveal_radius != 0
        ):
            return None
    for boolean_key in ("must_see", "cant_see"):
        if boolean_key in target and not isinstance(target[boolean_key], bool):
            return None
    if target.get("must_see", False) and target.get("cant_see", False):
        return None
    radius = target.get("search_range", 60)
    if (
        not isinstance(radius, int) or isinstance(radius, bool) or
        not 0 <= radius <= 60
    ):
        return None
    minimum_radius = target.get("min_distance", 0)
    if (
        not isinstance(minimum_radius, int) or
        isinstance(minimum_radius, bool) or
        not 0 <= minimum_radius <= radius
    ):
        return None
    offsets: list[int] = []
    for name in ("offset_x", "offset_y", "offset_z"):
        value = target.get(name, 0)
        if not isinstance(value, int) or isinstance(value, bool) or not -60 <= value <= 60:
            return None
        offsets.append(value)
    if key == "u_set_goal":
        # Native f_npc_goal resolves the alpha talker with get_npc().  In this
        # proven-avatar context that returns null, so the bounded effect is a
        # no-op.  Do not pass the avatar Character handle to an NPC service.
        return []
    actor = "actor"
    visibility = ""
    if "must_see" in target:
        visibility = ", seen = true" if target["must_see"] else ", seen = false"
    elif "cant_see" in target:
        visibility = ", seen = false" if target["cant_see"] else ", seen = true"
    offset_expression = ""
    if any(offsets):
        offset_expression = (
            f":add(services.coords.tripoint_abs_omt({offsets[0]}, "
            f"{offsets[1]}, {offsets[2]}))"
        )
    return [
        "    local origin = service_value(services.characters.snapshot(",
        f"        {actor})).creature.position:project_to(\"overmap_terrain\")",
        "    local target_page = services.overmap.search(origin, {",
        f"        types = {{ {{ terrain = {lua_quote(terrain)} }} }},",
        *([f"        special = {lua_quote(special)},"] if special is not None else []),
        f"        radius = {radius},",
        f"        minimum_radius = {minimum_radius},{visibility},",
        "        limit = 1,",
        "    })",
        "    if target_page.returned > 0 then",
        f"        local destination = target_page.items[1].position{offset_expression}",
        "        service_value(services.npcs.set_goal(",
        f"            {actor}, destination))",
        "    end",
    ]


def render_static_npc_guard_position_effect(
    effect: dict[str, Any],
    key: str,
    avatar_actor_proven: bool,
    npc_actor_proven: bool,
) -> list[str] | None:
    """Render same-actor/context typed coordinates for guard-post effects."""
    if key not in {"u_set_guard_pos", "npc_set_guard_pos"}:
        return None
    if set(effect) - {key, "unique_id"}:
        return None
    unique_id = effect.get("unique_id", False)
    if not isinstance(unique_id, bool):
        return None
    target = effect.get(key)
    actor_scope = "u" if key == "u_set_guard_pos" else "npc"
    if actor_scope == "u" and not avatar_actor_proven:
        return None
    if actor_scope == "npc" and not npc_actor_proven:
        return None
    if actor_scope == "u":
        # Native f_guard_pos resolves the alpha talker with get_npc().  In this
        # proven-avatar context the native effect is a no-op; retain that
        # behavior instead of passing a Character handle to an NPC service.
        if unique_id:
            descriptor = _coordinate_variable_descriptor(target)
            if descriptor is None or descriptor[0] != "global":
                return None
        elif (
            isinstance(target, dict) and
            set(target) == {"context_val"} and
            bounded_utf8_string(target.get("context_val"), 256)
        ):
            pass
        else:
            descriptor = _static_character_variable_descriptor(target)
            if descriptor is None or descriptor[0] != "u":
                return None
        return []
    if unique_id:
        descriptor = _coordinate_variable_descriptor(target)
        if descriptor is None or descriptor[0] != "global":
            return None
        return [
            "    local guard_npc = service_value(services.npcs.get(actor))",
            "    if guard_npc.unique_id ~= nil and guard_npc.unique_id ~= \"\" then",
            "        local destination_result = service_value(",
            "            services.variables.get_global(",
            f"                guard_npc.unique_id .. {lua_quote(descriptor[1])}))",
            "        if destination_result.exists and destination_result.value ~= nil then",
            "            service_value(services.npcs.set_guard_position(",
            "                actor, destination_result.value))",
            "        end",
            "    end",
        ]
    destination_lines: list[str]
    if (
        isinstance(target, dict) and
        set(target) == {"context_val"} and
        bounded_utf8_string(target.get("context_val"), 256)
    ):
        destination_lines = [
            "    local destination = context.data["
            f"{lua_quote(target['context_val'])}]",
            "    if destination ~= nil then",
        ]
    else:
        descriptor = _static_character_variable_descriptor(target)
        if descriptor is None or descriptor[0] != actor_scope:
            return None
        variable_handle = "actor"
        destination_lines = [
            "    local destination_result = service_value(services.variables.get(",
            f"        {variable_handle}, {lua_quote(descriptor[1])}))",
            "    if destination_result.exists then",
            "        local destination = destination_result.value",
        ]
    destination_lines.extend([
        "        service_value(services.npcs.set_guard_position(",
        "            actor, destination))",
        "    end",
    ])
    return destination_lines


def _contains_unproven_npc_variable_scope(value: Any) -> bool:
    if isinstance(value, dict):
        if "npc_val" in value or "var_val" in value:
            return True
        return any(
            _contains_unproven_npc_variable_scope(nested)
            for nested in value.values()
        )
    if isinstance(value, list):
        return any(
            _contains_unproven_npc_variable_scope(nested) for nested in value
        )
    return False


def render_static_assign_mission_effect(
    effect: dict[str, Any], avatar_actor_proven: bool,
) -> list[str] | None:
    """Reserve and assign an avatar mission through typed services."""
    if set(effect) - {"assign_mission", "deadline"}:
        return None
    if not avatar_actor_proven:
        return None
    avatar = "actor"
    mission_value = effect.get("assign_mission")
    if _contains_unproven_npc_variable_scope(mission_value):
        return None
    mission_id = _dynamic_id_expression(
        mission_value, "mission", avatar
    )
    if mission_id is None:
        return None
    deadline_expression: str | None = None
    if "deadline" in effect:
        deadline_number = finite_number_literal(effect["deadline"])
        if deadline_number is None:
            return None
        if deadline_number != 0:
            # Native time_duration::from_turns(double) narrows to int by
            # truncating toward zero.  Check the converted value, since values
            # between INT_MAX and INT_MAX + 1 (or INT_MIN - 1 and INT_MIN)
            # still convert to a representable native int.
            native_turns = math.trunc(float(deadline_number))
            if not NATIVE_INT_MIN <= native_turns <= NATIVE_INT_MAX:
                return None
            deadline_expression = str(native_turns)
    lines = [
        "    local reservation = service_value(services.missions.reserve(",
        f"        {mission_id}))",
        "    local token = reservation.token",
        "    service_value(services.missions.assign(actor, token))",
    ]
    if deadline_expression is not None:
        lines.extend([
            "    service_value(services.missions.set_deadline(",
            f"        token, services.time.point({deadline_expression})))",
        ])
    return lines


def _render_static_active_mission_match(
    mission_id: str, mutation: str,
) -> list[str]:
    """Scan every bounded native-order page and mutate only its first match."""
    return [
        "    do",
        f"        local mission_id = {lua_quote(mission_id)}",
        "        local mission_offset = 0",
        "        local mission_done = false",
        "        repeat",
        "            local mission_page = services.missions.active(actor, {",
        "                offset = mission_offset, limit = 256,",
        "            })",
        "            for _, mission_entry in ipairs(mission_page.items) do",
        "                if not mission_done and mission_entry.id.value == mission_id then",
        f"                    {mutation}",
        "                    mission_done = true",
        "                end",
        "            end",
        "            if not mission_done and mission_page.has_more and",
        "               mission_offset + mission_page.returned >= 1000000 then",
        '                error("active mission scan exceeded its bounded offset")',
        "            end",
        "            mission_offset = mission_offset + mission_page.returned",
        "        until mission_done or not mission_page.has_more",
        "    end",
    ]


def render_static_finish_mission_effect(
    effect: dict[str, Any], avatar_actor_proven: bool,
) -> list[str] | None:
    """Apply one native-order literal mission mutation to the avatar."""
    if (
        "finish_mission" not in effect or
        set(effect) - {"finish_mission", "success", "step"} or
        not avatar_actor_proven
    ):
        return None
    mission_id = effect["finish_mission"]
    if not safe_platform_id(mission_id):
        return None
    if "step" in effect:
        step = effect["step"]
        if (
            not isinstance(step, int) or isinstance(step, bool) or
            not 0 <= step <= 1000000
        ):
            return None
        mutation = (
            "service_value(services.missions.step_complete("
            f"actor, mission_entry.token, {step}))"
        )
    else:
        success = effect.get("success", False)
        if not isinstance(success, bool):
            return None
        mutation = (
            "service_value(services.missions.finish("
            "actor, mission_entry.token))"
            if success else
            "service_value(services.missions.fail("
            "actor, mission_entry.token))"
        )
    return _render_static_active_mission_match(
        mission_id, mutation
    )


def render_static_remove_active_mission_effect(
    effect: dict[str, Any], avatar_actor_proven: bool,
) -> list[str] | None:
    """Remove the first native-order active avatar mission of a literal type."""
    if (
        set(effect) != {"remove_active_mission"} or
        not avatar_actor_proven
    ):
        return None
    mission_id = effect["remove_active_mission"]
    if not safe_platform_id(mission_id):
        return None
    return _render_static_active_mission_match(
        mission_id,
        "service_value(services.missions.abandon("
        "actor, mission_entry.token))",
    )


def render_dialogue_mission_action_effect(effect: Any) -> LuaRaw | None:
    """Run a literal mission action in the native response effect phase."""
    if not isinstance(effect, dict):
        return None
    if "finish_mission" in effect:
        action = render_static_finish_mission_effect(effect, True)
    elif "remove_active_mission" in effect:
        action = render_static_remove_active_mission_effect(effect, True)
    else:
        return None
    if action is None:
        return None
    # Both native wrappers fetch get_avatar(), regardless of the current
    # dialogue speaker.  The success response's effect vector runs inside
    # talk_effect_t::apply; Platform on_action is inserted into that same
    # vector, while on_select would run after opinion and hostility handling.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success then return end",
        "    local actor = services.characters.avatar()",
        *action,
        "end",
    ]))


def render_dialogue_item_grant_action_effect(effect: Any) -> LuaRaw | None:
    """Grant one literal item through the active native TALK dialogue.

    The callback-scoped context preserves dialogue alpha, the beta-dependent
    popup, and the native response-effect phase. EOC callbacks and every
    parameterized/group form remain TODO until they carry the same exact
    dialogue and item-construction semantics.
    """
    if not isinstance(effect, dict) or set(effect) != {"u_spawn_item"}:
        return None
    item_id = effect["u_spawn_item"]
    if not safe_platform_id(item_id) or not bounded_utf8_string(
        item_id, PLATFORM_ID_MAX_BYTES, allow_empty=False
    ):
        return None
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    context:grant_item_to_speaker(services.types.id(",
        f"        \"item\", {lua_quote(item_id)}))",
        "end",
    ]))


def render_dialogue_stolen_item_action_effect(effect: Any) -> LuaRaw | None:
    """Run a native stolen-item resolution for a direct TALK response.

    The native string effects invoke their NPC functions on dialogue beta.
    Returning stolen items searches the current player's inventory. A direct
    response callback retains beta; EOC and compound response paths do not
    establish the same invocation order and remain for manual conversion.
    """
    services = {
        "drop_stolen_item": "drop_stolen_items",
        "remove_stolen_status": "clear_stolen_item_claim",
    }
    service = services.get(effect) if isinstance(effect, str) else None
    if service is None:
        return None
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    local beta = context:interlocutor()",
        '    if beta == nil or beta.kind ~= "creature" or beta.subtype ~= "npc" then return end',
        "    if not beta:is_valid() then return end",
        f"    service_value(services.npcs.{service}(beta))",
        "end",
    ]))


def render_dialogue_spend_cash_action_effect(effect: Any) -> LuaRaw | None:
    """Render an exact static beta-NPC payment in the native TALK action phase."""
    if not isinstance(effect, dict) or set(effect) != {"u_spend_cash"}:
        return None
    amount = effect["u_spend_cash"]
    if type(amount) is not int or amount < 0 or amount > NATIVE_INT_MAX:
        return None
    # Native TALK builds alpha from the active avatar and beta from talk_with.
    # `u_spend_cash` calls beta.buy_from(int); the NPC implementation delegates
    # to npc_trading::pay_npc, which is the same operation exposed by trade.pay.
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    local seller = context:interlocutor()",
        '    if seller == nil or seller.kind ~= "creature" or seller.subtype ~= "npc" then return end',
        "    if not seller:is_valid() then return end",
        "    local buyer = services.characters.avatar()",
        "    if buyer == nil or not buyer:is_valid() then return end",
        f"    service_value(services.trade.pay(seller, buyer, {amount}))",
        "end",
    ]))


def render_dialogue_sell_item_action_effect(
    response: Any, converted_condition: LuaRaw | None,
) -> LuaRaw | None:
    """Transfer one bounded static item in the native direct-TALK action phase.

    The typed transfer service preserves charge-first selection, beta faction
    ownership, recipient insertion, and the native popup text. Keep EOC vectors,
    nonzero debt, dynamic/fractional counts, unconverted conditions, and other
    response fields for manual conversion because they need additional native
    phase or actor context.
    """
    if not isinstance(response, dict):
        return None
    allowed_fields = {"text", "topic", "condition", "effect"}
    opinion = response.get("opinion")
    if "opinion" in response:
        allowed_fields.add("opinion")
        if (
            not isinstance(opinion, dict) or not opinion or
            set(opinion) - {"trust", "fear", "value", "anger", "owed", "sold"} or
            any(type(value) is not int or not NATIVE_INT_MIN <= value <= NATIVE_INT_MAX
                for value in opinion.values())
        ):
            return None
    if (
        set(response) - allowed_fields or
        not isinstance(response.get("text"), str) or
        "condition" in response and converted_condition is None
    ):
        return None
    action = render_static_sell_item_effect(
        response.get("effect"), "buyer", "seller",
    )
    if action is None:
        return None
    return LuaRaw("\n".join([
        "function(context, trial_success)",
        "    if not trial_success or not context:valid() then return end",
        "    local seller = context:interlocutor()",
        '    if seller == nil or seller.kind ~= "creature" or seller.subtype ~= "npc" then return end',
        "    if not seller:is_valid() then return end",
        "    local buyer = services.characters.avatar()",
        "    if buyer == nil or not buyer:is_valid() then return end",
        *action,
        "end",
    ]))


def render_static_offer_mission_effect(
    effect: dict[str, Any], npc_actor_proven: bool,
    npc_actor_expression: str | None = None,
) -> list[str] | None:
    """Offer one or more literal missions through an NPC provider handle."""
    if (
        not npc_actor_proven or npc_actor_expression is None or
        set(effect) != {"offer_mission"}
    ):
        return None
    raw = effect.get("offer_mission")
    mission_ids = [raw] if isinstance(raw, str) else raw
    if (
        not isinstance(mission_ids, list) or not mission_ids or
        len(mission_ids) > 64 or not all(safe_platform_id(value) for value in mission_ids)
    ):
        return None
    lines: list[str] = []
    for mission_id in mission_ids:
        lines.extend([
            "    service_value(services.npcs.missions.offer(",
            f"        {npc_actor_expression}, services.types.id(\"mission\", "
            f"{lua_quote(mission_id)})))",
        ])
    return lines


def render_static_add_mission_effect(
    effect: dict[str, Any], npc_actor_proven: bool,
    avatar_actor_proven: bool = False,
    npc_actor_expression: str | None = None,
) -> list[str] | None:
    """Assign one mission only when provider and owner are both explicit."""
    if (
        not npc_actor_proven or not avatar_actor_proven or
        npc_actor_expression is None or set(effect) != {"add_mission"}
    ):
        return None
    mission_id = _dynamic_id_expression(
        effect.get("add_mission"), "mission", "actor"
    )
    if mission_id is None:
        return None
    return [
        "    service_value(services.npcs.missions.add_assigned(",
        f"        {npc_actor_expression}, actor, {mission_id}))",
    ]


def render_static_camp_create_effect(
    effect: dict[str, Any],
) -> list[str] | None:
    """Lower only an explicit, source-backed Platform camp creation shape.

    This migration-only descriptor requires a literal faction/type/name and
    context handles that explicitly identify the manager and OMT position.
    Legacy camp-start UI effects do not prove those values and must remain
    TODOs rather than selecting a camp or avatar implicitly.
    """
    if not isinstance(effect, dict) or set(effect) != {
        "owner_faction", "manager_handle", "omt_position", "name", "type"
    }:
        return None
    owner_faction = effect.get("owner_faction")
    camp_type = effect.get("type")
    name = effect.get("name")
    if (
        not isinstance(owner_faction, str) or
        not safe_platform_id(owner_faction) or
        not isinstance(camp_type, str) or
        not safe_platform_id(camp_type) or
        not camp_type.startswith("faction_base_") or
        not isinstance(name, str) or
        not 0 < len(name) <= 25 or
        any(ord(char) < 0x20 or ord(char) == 0x7F for char in name)
    ):
        return None

    def explicit_context(value: Any) -> str | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        return f"context.data[{lua_quote(value['context_handle'])}]"

    manager = explicit_context(effect.get("manager_handle"))
    position = explicit_context(effect.get("omt_position"))
    if manager is None or position is None:
        return None
    return [
        "    service_value(services.camps.create(",
        f"        services.types.id(\"faction\", {lua_quote(owner_faction)}),",
        f"        {manager}, {position}, {lua_quote(name)}, {{",
        f"            type = {lua_quote(camp_type)},",
        "        }))",
    ]


def render_static_camp_expansion_create_effect(
    effect: dict[str, Any],
) -> list[str] | None:
    """Lower only an explicit camp expansion create descriptor."""
    if not isinstance(effect, dict) or set(effect) != {
        "camp_handle", "manager_handle", "omt_position", "type", "name"
    }:
        return None
    camp_type = effect.get("type")
    name = effect.get("name")
    if (
        not isinstance(camp_type, str) or
        not safe_platform_id(camp_type) or
        not camp_type.startswith("faction_base_") or
        not isinstance(name, str) or
        not 0 < len(name) <= 64 or
        any(ord(char) < 0x20 or ord(char) == 0x7F for char in name)
    ):
        return None

    def explicit_context(value: Any) -> str | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        return f"context.data[{lua_quote(value['context_handle'])}]"

    camp = explicit_context(effect.get("camp_handle"))
    manager = explicit_context(effect.get("manager_handle"))
    position = explicit_context(effect.get("omt_position"))
    if camp is None or manager is None or position is None:
        return None
    return [
        "    service_value(services.camps.expansions.create(",
        f"        {camp}, {manager}, {position},",
        f"        {lua_quote(camp_type)}, {lua_quote(name)}))",
    ]


def render_static_resource_work_effect(
    effect: dict[str, Any],
) -> list[str] | None:
    """Lower only an explicitly typed, source-backed resource-work shape.

    The legacy camp mission/UI effects do not carry camp, manager, or worker
    handles and therefore never reach this renderer.  The accepted shape is a
    narrow migration descriptor whose three ``*_handle`` values explicitly
    name typed handles already supplied in callback context.  Literal resource
    ids, amounts, food deltas, and duration are required; dynamic values and
    all implicit actor/position lookup remain TODOs.
    """
    if not isinstance(effect, dict):
        return None
    allowed = {
        "camp_handle", "manager_handle", "worker_handle",
        "resource_inputs", "resource_outputs", "food_input_kcal",
        "food_output_kcal", "duration_turns",
    }
    if set(effect) - allowed:
        return None

    def explicit_handle(value: Any) -> str | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        return f"context.data[{lua_quote(value['context_handle'])}]"

    camp = explicit_handle(effect.get("camp_handle"))
    manager = explicit_handle(effect.get("manager_handle"))
    worker = explicit_handle(effect.get("worker_handle"))
    if camp is None or manager is None or worker is None:
        return None

    def static_changes(value: Any) -> list[tuple[str, int]] | None:
        if value is None:
            return []
        if not isinstance(value, list) or len(value) > 64:
            return None
        result: list[tuple[str, int]] = []
        seen: set[str] = set()
        for entry in value:
            if (
                not isinstance(entry, dict) or set(entry) != {"id", "amount"} or
                not isinstance(entry.get("id"), str) or
                not safe_platform_id(entry["id"]) or
                not isinstance(entry.get("amount"), int) or
                isinstance(entry["amount"], bool) or
                not 0 < entry["amount"] <= 1000000000 or
                entry["id"] in seen
            ):
                return None
            seen.add(entry["id"])
            result.append((entry["id"], entry["amount"]))
        return result

    inputs = static_changes(effect.get("resource_inputs"))
    outputs = static_changes(effect.get("resource_outputs"))
    duration = effect.get("duration_turns")
    if (
        inputs is None or outputs is None or
        not isinstance(duration, int) or isinstance(duration, bool) or
        not 0 < duration <= 1000000
    ):
        return None

    invalid_literal = object()

    def static_food(name: str) -> int | None | object:
        value = effect.get(name)
        if value is None:
            return None
        if (
            not isinstance(value, int) or isinstance(value, bool) or
            not 0 < value <= 1000000000
        ):
            return invalid_literal
        return value

    food_input = static_food("food_input_kcal")
    food_output = static_food("food_output_kcal")
    if food_input is invalid_literal or food_output is invalid_literal:
        return None

    if not inputs and not outputs and food_input is None and food_output is None:
        return None

    def render_changes(field: str, changes: list[tuple[str, int]]) -> list[str]:
        if not changes:
            return [f"                {field} = {{}},"]
        return [
            f"                {field} = {{",
            *[
                "                    { id = services.types.id(\"item\", "
                f"{lua_quote(item_id)}), amount = {amount} }},"
                for item_id, amount in changes
            ],
            "                },",
        ]

    lines = [
        "    service_value(services.camps.tasks.create(",
        f"        {camp}, {manager}, {worker}, \"resource_work\", {{",
    ]
    if inputs:
        lines.extend(render_changes("resource_inputs", inputs))
    else:
        lines.append("                resource_inputs = {},")
    if outputs:
        lines.extend(render_changes("resource_outputs", outputs))
    else:
        lines.append("                resource_outputs = {},")
    if food_input is not None:
        lines.append(f"                food_input_kcal = {food_input},")
    if food_output is not None:
        lines.append(f"                food_output_kcal = {food_output},")
    lines.extend([
        f"                duration_turns = {duration},",
        "            }))",
    ])
    return lines


def render_static_recipe_work_effect(
    effect: dict[str, Any],
) -> list[str] | None:
    """Lower only a fully explicit, source-backed recipe-work request.

    This is a migration-only shape, not a decoder for legacy camp missions.
    Every actor, holder, and Item is supplied as an explicit callback-context
    handle, while recipe id, batch, duration, quantity, and tool role are
    literal values.  Dynamic holders, same-id searches, UI crafting tasks,
    and any missing proof remain TODOs at the caller.
    """
    if not isinstance(effect, dict):
        return None
    allowed = {
        "camp_handle", "manager_handle", "worker_handle", "recipe_id",
        "batch", "duration_turns", "source_holders", "destination_holder",
        "item_requests",
    }
    if set(effect) - allowed:
        return None

    def explicit_handle(value: Any) -> str | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        return f"context.data[{lua_quote(value['context_handle'])}]"

    camp = explicit_handle(effect.get("camp_handle"))
    manager = explicit_handle(effect.get("manager_handle"))
    worker = explicit_handle(effect.get("worker_handle"))
    recipe_id = effect.get("recipe_id")
    batch = effect.get("batch")
    duration = effect.get("duration_turns")
    if (
        camp is None or manager is None or worker is None or
        not isinstance(recipe_id, str) or not safe_platform_id(recipe_id) or
        not isinstance(batch, int) or isinstance(batch, bool) or
        not 0 < batch <= 1000 or
        not isinstance(duration, int) or isinstance(duration, bool) or
        not 0 < duration <= 1000000
    ):
        return None

    def explicit_holder(value: Any) -> tuple[str, tuple[str, str], str] | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"character_handle", "slot"}
        ):
            return None
        character = explicit_handle(value.get("character_handle"))
        slot = value.get("slot")
        if character is None or slot not in {"inventory", "worn", "wielded"}:
            return None
        key = (value["character_handle"]["context_handle"], slot)
        return (
            "{ kind = \"character\", character = " + character +
            f", slot = {lua_quote(slot)} }}",
            key,
            slot,
        )

    raw_sources = effect.get("source_holders")
    if not isinstance(raw_sources, list) or not raw_sources or len(raw_sources) > 16:
        return None
    source_holders: list[tuple[str, tuple[str, str], str]] = []
    source_keys: set[tuple[str, str]] = set()
    for value in raw_sources:
        holder = explicit_holder(value)
        if holder is None or holder[1] in source_keys:
            return None
        source_holders.append(holder)
        source_keys.add(holder[1])

    destination = explicit_holder(effect.get("destination_holder"))
    if destination is None or destination[2] != "inventory":
        return None

    raw_requests = effect.get("item_requests")
    if not isinstance(raw_requests, list) or not raw_requests or len(raw_requests) > 256:
        return None
    requests: list[tuple[str, str, int, bool]] = []
    seen_items: set[str] = set()
    for value in raw_requests:
        if (
            not isinstance(value, dict) or
            set(value) != {"item_handle", "source_holder", "quantity", "tool"}
        ):
            return None
        item_handle = explicit_handle(value.get("item_handle"))
        holder = explicit_holder(value.get("source_holder"))
        quantity = value.get("quantity")
        tool = value.get("tool")
        if (
            item_handle is None or holder is None or holder[1] not in source_keys or
            not isinstance(quantity, int) or isinstance(quantity, bool) or
            not 0 < quantity <= 1000000000 or not isinstance(tool, bool)
        ):
            return None
        item_key = value["item_handle"].get("context_handle")
        if item_key in seen_items:
            return None
        seen_items.add(item_key)
        requests.append((item_handle, holder[0], quantity, tool))

    lines = [
        "    local recipe_task = service_value(services.camps.tasks.create(",
        f"        {camp}, {manager}, {worker}, \"recipe_work\", {{",
        "            recipe_id = services.types.id(\"recipe\", "
        f"{lua_quote(recipe_id)}),",
        f"            batch = {batch},",
        f"            duration_turns = {duration},",
        "            source_holders = {",
        *[f"                {holder[0]}," for holder in source_holders],
        "            },",
        f"            destination_holder = {destination[0]},",
        "        }))",
        "    if recipe_task ~= nil and recipe_task.token ~= nil then",
        "        service_value(services.camps.tasks.start(",
        f"            {camp}, {manager}, {worker}, recipe_task.token, {{",
    ]
    lines.extend(
        "                { item = " + item_handle +
        ", source_holder = " + holder +
        f", quantity = {quantity}, tool = {'true' if tool else 'false'} }},"
        for item_handle, holder, quantity, tool in requests
    )
    lines.extend([
        "            }))",
        "    end",
    ])
    return lines


def render_static_upgrade_work_effect(
    effect: dict[str, Any],
) -> list[str] | None:
    """Lower only a fully explicit, source-backed upgrade-work request.

    The legacy ``Camp_Upgrade`` mission and camp UI do not prove a stable camp,
    authorized manager, worker, target generation, blueprint arguments, or
    exact Item holders.  Only a migration descriptor carrying every one of
    those identities may reach this renderer; all implicit/current/nearest
    selection remains a TODO at the caller.
    """
    if not isinstance(effect, dict):
        return None
    allowed = {
        "camp_handle", "manager_handle", "worker_handle", "upgrade_id",
        "blueprint_id", "target", "duration_turns", "source_holders",
        "destination_holder", "item_requests",
    }
    if set(effect) != allowed:
        return None

    def explicit_handle(value: Any) -> str | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        return f"context.data[{lua_quote(value['context_handle'])}]"

    camp = explicit_handle(effect.get("camp_handle"))
    manager = explicit_handle(effect.get("manager_handle"))
    worker = explicit_handle(effect.get("worker_handle"))
    upgrade_id = effect.get("upgrade_id")
    blueprint_id = effect.get("blueprint_id")
    duration = effect.get("duration_turns")
    if (
        camp is None or manager is None or worker is None or
        not safe_platform_id(upgrade_id) or
        not bounded_utf8_string(blueprint_id, 128) or
        not isinstance(duration, int) or isinstance(duration, bool) or
        not 0 < duration <= 1000000
    ):
        return None

    raw_target = effect.get("target")
    common_target_keys = {"kind", "position", "terrain", "mapgen_args"}
    if not isinstance(raw_target, dict) or set(raw_target) - (
        common_target_keys | {"generation", "expansion_handle"}
    ):
        return None
    target_kind = raw_target.get("kind")
    position = explicit_handle(raw_target.get("position"))
    terrain = raw_target.get("terrain")
    raw_mapgen_args = raw_target.get("mapgen_args")
    if (
        not isinstance(target_kind, str) or
        target_kind not in {"camp_core", "expansion"} or
        position is None or not safe_platform_id(terrain) or
        not isinstance(raw_mapgen_args, dict) or len(raw_mapgen_args) > 64
    ):
        return None

    generation = raw_target.get("generation")
    expansion = None
    if target_kind == "camp_core":
        if set(raw_target) != common_target_keys | {"generation"}:
            return None
        if (
            not isinstance(generation, int) or isinstance(generation, bool) or
            not 0 < generation <= 9223372036854775807
        ):
            return None
    else:
        if set(raw_target) != common_target_keys | {"expansion_handle"}:
            return None
        expansion = explicit_handle(raw_target.get("expansion_handle"))
        if expansion is None:
            return None

    mapgen_args: list[tuple[str, str, str]] = []
    if any(not isinstance(key, str) for key in raw_mapgen_args):
        return None
    for key in sorted(raw_mapgen_args):
        typed = raw_mapgen_args[key]
        if (
            not isinstance(key, str) or
            not bounded_utf8_string(key, 64) or
            not isinstance(typed, dict) or
            set(typed) != {"type", "value"}
        ):
            return None
        value_type = typed.get("type")
        value = typed.get("value")
        if value_type == "int":
            if (
                not isinstance(value, int) or isinstance(value, bool) or
                not -2147483648 <= value <= 2147483647
            ):
                return None
            rendered_value = str(value)
        elif value_type == "bool":
            if not isinstance(value, bool):
                return None
            rendered_value = "true" if value else "false"
        elif value_type == "string":
            if not bounded_utf8_string(value, 256, allow_empty=True):
                return None
            rendered_value = lua_quote(value)
        else:
            return None
        mapgen_args.append((key, value_type, rendered_value))

    def explicit_holder(value: Any) -> tuple[str, tuple[str, str], str] | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"character_handle", "slot"}
        ):
            return None
        character = explicit_handle(value.get("character_handle"))
        slot = value.get("slot")
        if (
            character is None or not isinstance(slot, str) or
            slot not in {"inventory", "worn", "wielded"}
        ):
            return None
        key = (value["character_handle"]["context_handle"], slot)
        return (
            "{ kind = \"character\", character = " + character +
            f", slot = {lua_quote(slot)} }}",
            key,
            slot,
        )

    raw_sources = effect.get("source_holders")
    if not isinstance(raw_sources, list) or not raw_sources or len(raw_sources) > 16:
        return None
    source_holders: list[tuple[str, tuple[str, str], str]] = []
    source_keys: set[tuple[str, str]] = set()
    for value in raw_sources:
        holder = explicit_holder(value)
        if holder is None or holder[1] in source_keys:
            return None
        source_holders.append(holder)
        source_keys.add(holder[1])

    destination = explicit_holder(effect.get("destination_holder"))
    if destination is None or destination[2] != "inventory":
        return None

    raw_requests = effect.get("item_requests")
    if not isinstance(raw_requests, list) or not raw_requests or len(raw_requests) > 256:
        return None
    requests: list[tuple[str, str, int, bool]] = []
    seen_items: set[str] = set()
    for value in raw_requests:
        if (
            not isinstance(value, dict) or
            set(value) != {"item_handle", "source_holder", "quantity", "tool"}
        ):
            return None
        item_handle = explicit_handle(value.get("item_handle"))
        holder = explicit_holder(value.get("source_holder"))
        quantity = value.get("quantity")
        tool = value.get("tool")
        if (
            item_handle is None or holder is None or holder[1] not in source_keys or
            not isinstance(quantity, int) or isinstance(quantity, bool) or
            not 0 < quantity <= 1000000000 or not isinstance(tool, bool)
        ):
            return None
        item_key = value["item_handle"].get("context_handle")
        if item_key in seen_items:
            return None
        seen_items.add(item_key)
        requests.append((item_handle, holder[0], quantity, tool))

    lines = [
        "    local upgrade_task = service_value(services.camps.tasks.create(",
        f"        {camp}, {manager}, {worker}, \"upgrade_work\", {{",
        "            upgrade_id = services.types.id(\"recipe\", "
        f"{lua_quote(upgrade_id)}),",
        f"            blueprint_id = {lua_quote(blueprint_id)},",
        "            target = {",
        f"                kind = {lua_quote(target_kind)},",
    ]
    if target_kind == "camp_core":
        lines.append(f"                generation = {generation},")
    else:
        lines.append(f"                expansion = {expansion},")
    lines.extend([
        f"                position = {position},",
        f"                terrain = {lua_quote(terrain)},",
    ])
    if mapgen_args:
        lines.append("                mapgen_args = {")
        lines.extend(
            f"                    [{lua_quote(key)}] = {{ type = {lua_quote(value_type)}, value = {value} }},"
            for key, value_type, value in mapgen_args
        )
        lines.append("                },")
    else:
        lines.append("                mapgen_args = {},")
    lines.extend([
        "            },",
        f"            duration_turns = {duration},",
        "            source_holders = {",
        *[f"                {holder[0]}," for holder in source_holders],
        "            },",
        f"            destination_holder = {destination[0]},",
        "        }))",
        "    if upgrade_task ~= nil and upgrade_task.token ~= nil then",
        "        service_value(services.camps.tasks.start(",
        f"            {camp}, {manager}, {worker}, upgrade_task.token, {{",
    ])
    lines.extend(
        "                { item = " + item_handle +
        ", source_holder = " + holder +
        f", quantity = {quantity}, tool = {'true' if tool else 'false'} }},"
        for item_handle, holder, quantity, tool in requests
    )
    lines.extend([
        "            }))",
        "    end",
    ])
    return lines


def render_static_companion_mission_effect(
    effect: dict[str, Any], npc_actor_proven: bool,
) -> list[str] | None:
    """Render a native companion-mission menu for a literal role."""
    if (
        not npc_actor_proven or set(effect) != {"companion_mission"} or
        not isinstance(effect.get("companion_mission"), str)
    ):
        return None
    role = effect["companion_mission"]
    if role not in {
        "SCAVENGER", "COMMUNE CROPS", "FOREMAN", "REFUGEE MERCHANT",
        "PLANT FIELD", "HARVEST FIELD",
    }:
        return None
    return [
        "    service_value(services.npcs.open_companion_missions(actor, "
        f"{lua_quote(role)}))",
    ]


def render_equipment_offer_selection(seller: str, allowance: str) -> str:
    """Build native random rejection sampling; settlement is a separate step."""
    return (
        "(function(seller, allowance) "
        "local offers = service_value(services.trade.selling_offers(seller)); "
        "local owed = service_value(services.npcs.get(seller)).opinion.owed; "
        "while #offers > 0 do "
        "local index = services.random.int(1, #offers); local offer = offers[index]; "
        "if offer.price < owed + allowance then return offer end; "
        "table.remove(offers, index); end; return nil end)("
        f"{seller}, {allowance})"
    )


def render_trial_modifier_reader(attribute: str) -> str | None:
    """Lower the native NPC/avatar parse_mod dispatch without inventing a talker."""
    npc_fields = {
        "ANGER": "opinion.anger", "FEAR": "opinion.fear",
        "TRUST": "opinion.trust", "VALUE": "opinion.value",
        "AGGRESSION": "personality.aggression", "ALTRUISM": "personality.altruism",
        "BRAVERY": "personality.bravery", "COLLECTOR": "personality.collector",
    }
    npc_value = avatar_value = "0"
    if attribute in npc_fields:
        npc_value = f"service_value(services.npcs.get(talker)).{npc_fields[attribute]}"
    elif attribute == "POS_FEAR":
        npc_value = "math.max(0, service_value(services.npcs.get(talker)).opinion.fear)"
    elif attribute == "MISSIONS":
        npc_value = "(math.modf(service_value(services.npcs.get(talker)).assigned_missions_value / 1000))"
    elif attribute == "NPC_INTIMIDATE":
        npc_value = "service_value(services.characters.intimidation(talker))"
    if attribute == "U_INTIMIDATE":
        avatar_value = "service_value(services.characters.intimidation(talker))"
    elif attribute in {"LOWFUNC_PSYCHOPATH", "HIGHFUNC_PSYCHOPATH"}:
        comparison = "<= 8" if attribute == "LOWFUNC_PSYCHOPATH" else ">= 16"
        avatar_value = (
            '(service_value(services.characters.has_flag(talker, services.types.id("json_flag", "PSYCHOPATH"))) '
            f"and service_value(services.characters.snapshot(talker)).stats.intelligence {comparison} and 1 or 0)"
        )
    for marker, prefix in (("npc_has_trait", "npc_has_trait: "), ("u_has_trait", "u_has_trait: ")):
        if marker not in attribute:
            continue
        # Native find() matches anywhere but substr() still uses this fixed byte offset.
        try:
            encoded = attribute.encode("utf-8")
            if len(encoded) < len(prefix):
                return None
            trait = encoded[len(prefix):].decode("utf-8")
        except UnicodeError:
            return None
        if (not bounded_utf8_string(trait, 256, allow_empty=True) or
                any(ord(char) < 32 or ord(char) == 127 for char in trait)):
            return None
        query = (
            '(function() local id = services.types.id("mutation", '
            f'{lua_quote(trait)}); return id:is_valid() and '
            'service_value(services.mutations.has(talker, id)) and 1 or 0 end)()'
        )
        if marker == "npc_has_trait":
            npc_value = query
        else:
            avatar_value = query
    if npc_value == avatar_value == "0":
        return "function(talker) return 0 end"
    return (
        'function(talker) if talker == nil then return 0 end; '
        f'if talker.subtype == "npc" then return {npc_value} '
        f'elseif talker.subtype == "avatar" then return {avatar_value} end; return 0 end'
    )


def render_equipment_modifier_allowance(
    modifiers: list[Any], alpha: str | None, beta: str,
) -> str | None:
    """Preserve modifier order, beta-then-alpha reads, and native signed-int bounds."""
    parsed: list[tuple[str, int, str | None]] = []
    needs_talkers = False
    for entry in modifiers:
        if (not isinstance(entry, list) or len(entry) != 2 or not isinstance(entry[0], str) or
                type(entry[1]) is not int or not -(2**31) <= entry[1] < 2**31):
            return None
        name, factor = entry
        reader = None if name == "TOTAL" else render_trial_modifier_reader(name)
        if name != "TOTAL" and reader is None:
            return None
        needs_talkers |= reader is not None and reader != "function(talker) return 0 end"
        parsed.append((name, factor, reader))
    if not needs_talkers:
        return "0"
    if alpha is None:
        return None
    lines = [
        "(function(alpha, beta)",
        'local function checked(value) if value < -2147483648 or value > 2147483647 then error("equipment allowance exceeds native integer range") end; return value end',
        "local allowance = 0",
    ]
    for name, factor, reader in parsed:
        if name == "TOTAL":
            lines.append(f"allowance = checked(allowance * {factor})")
        else:
            lines.extend([
                f"do local value = {reader}",
                f"local beta_value = checked(value(beta) * {factor})",
                f"local alpha_value = checked(value(alpha) * {factor})",
                "allowance = checked(allowance + checked(beta_value + alpha_value)); end",
            ])
    return "; ".join(lines + ["return allowance", f"end)({alpha}, {beta})"])


def render_static_give_equipment_effect(
    effect: dict[str, Any] | str, npc_actor_proven: bool,
    avatar_actor_proven: bool, *, npc_actor_expression: str | None = None,
    alpha_actor_expression: str | None = None,
    require_beta_npc: bool = False,
) -> list[str] | None:
    """Compose allowance gifts from exact native offers and settlement.

    State-dependent trial modifiers require both original talkers; the current
    avatar is only the gift recipient, not proof of the original alpha.
    """
    target = npc_actor_expression or ("actor" if npc_actor_proven else None)
    if target is None:
        return None
    if effect == "give_equipment":
        payload: Any = {}
    elif isinstance(effect, dict) and set(effect) == {"give_equipment"}:
        payload = effect["give_equipment"]
    else:
        return None
    if not isinstance(payload, dict) or set(payload) - {"allowance"}:
        return None
    allowance = payload.get("allowance", 0)
    if isinstance(allowance, list):
        allowance_expression = render_equipment_modifier_allowance(
            allowance, alpha_actor_expression, "provider")
        if allowance_expression is None:
            return None
    elif type(allowance) is int and -(2**31) <= allowance < 2**31:
        allowance_expression = str(allowance)
    else:
        return None
    selection = render_equipment_offer_selection("provider", "allowance")
    provider_guard = (
        'provider ~= nil and provider.kind == "creature" and provider.subtype == "npc"'
        if require_beta_npc else 'provider ~= nil and provider.subtype == "npc"'
    )
    return [
        "    do",
        f"        local provider = {target}",
        f"        if {provider_guard} then",
        f"            local allowance = {allowance_expression}",
        f"            local offer = {selection}",
        "            local provider_name = service_value(services.npcs.get(provider)).name",
        "            if offer == nil then",
        '                ccb.presentation.notice(services.format(services.translate("%s has nothing to give!"), {provider_name}))',
        "            else",
        "                local recipient = services.characters.avatar()",
        "                local quote = service_value(services.trade.quote(provider, recipient, {{",
        '                    direction = "seller_to_buyer", item = offer.item, quantity = offer.quantity,',
        "                    source_holder = offer.source_holder,",
        '                    destination_holder = {kind = "character", character = recipient, slot = "inventory"},',
        '                }}, {settlement = {strategy = "npc_allowance", currency = "cash", allowance = allowance}}))',
        '                local notice = services.format(services.translate("%1$s gives you a %2$s."), {provider_name, offer.item_name})',
        '                service_value(services.trade.commit(quote.token, {strategy = "npc_allowance", currency = "cash"}))',
        "                ccb.presentation.notice(notice)",
        '                service_value(services.effects.add(provider, services.types.id("effect", "asked_for_item"), services.time.duration(10800, "turn")))',
        "            end",
        "        end",
        "    end",
    ]


def render_static_follower_service_effect(
    effect: str, npc_actor_proven: bool, *, npc_actor_expression: str | None = None,
) -> list[str] | None:
    """Select from visible scene allies in native order, not the follower roster."""
    target = npc_actor_expression or ("actor" if npc_actor_proven else None)
    if target is None or effect not in {
        "bionic_install_allies", "bionic_remove_allies", "copy_npc_rules",
    }:
        return None
    if target != "actor":
        target = f"({target})"
    operation = {
        "bionic_install_allies": "install",
        "bionic_remove_allies": "remove",
    }.get(effect)
    lines = [
        f'    if {target} ~= nil and {target}.kind == "creature" and {target}.subtype == "npc" then',
        "        local followers = service_value(services.npcs.visible_allies())",
        "        local follower_choices = {}",
        "        local follower_handles = {}",
        "        for _, follower in ipairs(followers) do",
        "            local follower_id = tostring(follower.id)",
        "            follower_choices[#follower_choices + 1] = {",
        "                id = follower_id, label = follower.name, position = follower.position,",
        "            }",
        "            follower_handles[follower_id] = follower.handle",
        "        end",
        '        local selected_id = ccb.presentation.choose(services.translate("Select a follower"), follower_choices)',
        "        local selected_handle = selected_id and follower_handles[selected_id] or nil",
        "        if selected_handle ~= nil then",
    ]
    if operation is not None:
        lines.extend([
            "            service_value(services.npcs.medical.open_bionic_service(",
            f'                    {target}, "{operation}", selected_handle))',
        ])
    else:
        lines.extend([
            "            service_value(services.npcs.copy_ai_rules(",
            f"                    {target}, selected_handle))",
        ])
    lines.extend([
        "        end",
        "    end",
    ])
    return lines


