def render_static_add_debt_effect(
    effect: dict[str, Any], npc_actor_proven: bool,
) -> list[str] | None:
    """Render add_debt for a literal NPC-only modifier list."""
    if not npc_actor_proven or set(effect) != {"add_debt"}:
        return None
    raw = effect.get("add_debt")
    allowed = {
        "ANGER": "npc_state.opinion.anger",
        "FEAR": "npc_state.opinion.fear",
        "TRUST": "npc_state.opinion.trust",
        "VALUE": "npc_state.opinion.value",
        "POS_FEAR": "math.max(0, npc_state.opinion.fear)",
        "AGGRESSION": "npc_state.personality.aggression",
        "ALTRUISM": "npc_state.personality.altruism",
        "BRAVERY": "npc_state.personality.bravery",
        "COLLECTOR": "npc_state.personality.collector",
    }
    if not isinstance(raw, list) or not raw or len(raw) > 32:
        return None
    modifiers: list[tuple[str, int]] = []
    for entry in raw:
        if (
            not isinstance(entry, list) or len(entry) != 2 or
            not isinstance(entry[0], str) or entry[0] not in allowed or
            not isinstance(entry[1], int) or isinstance(entry[1], bool) or
            not -1000000 <= entry[1] <= 1000000
        ):
            if (
                isinstance(entry, list) and len(entry) == 2 and
                entry[0] == "TOTAL" and isinstance(entry[1], int) and
                not isinstance(entry[1], bool) and
                -1000000 <= entry[1] <= 1000000
            ):
                modifiers.append(("TOTAL", entry[1]))
                continue
            return None
        modifiers.append((entry[0], entry[1]))
    lines = [
        "    local npc_state = service_value(services.npcs.get(actor))",
        "    local debt = 0",
    ]
    for attribute, factor in modifiers:
        if attribute == "TOTAL":
            lines.append(f"    debt = debt * {factor}")
        else:
            lines.append(
                f"    debt = debt + ({allowed[attribute]}) * {factor}"
            )
    lines.extend([
        "    service_value(services.npcs.add_debt(actor, debt))",
    ])
    return lines


def render_static_remove_item_with_effect(
    effect: dict[str, Any], key: str, actor_proven: bool,
    actor_expression: str | None = "actor",
) -> list[str] | None:
    """Lower a static type removal through the exact Character inventory API.

    Native ``Character::remove_items_with`` matches the type recursively in
    inventory, worn items, and the wielded item.  A static item id and proven
    actor preserve that operation; dynamic ``str_or_var`` values stay TODO.
    Control bytes are excluded because ``services.types.id`` rejects them.
    """
    expected_actor_expressions = {
        "u_remove_item_with": {"actor", "alpha"},
        "npc_remove_item_with": {"beta"},
    }
    if (
        key not in {"u_remove_item_with", "npc_remove_item_with"} or
        not isinstance(effect, dict) or
        not actor_proven or actor_expression is None or
        actor_expression not in expected_actor_expressions[key] or
        set(effect) != {key} or
        not bounded_platform_id(effect.get(key))
    ):
        return None
    item_type = effect[key]
    if any(
        ord(character) < 0x20 or ord(character) == 0x7F
        for character in item_type
    ):
        return None
    return [
        "    service_value(services.inventory.remove_type(",
        f'        {actor_expression}, services.types.id("item", {lua_quote(item_type)})))',
    ]


def render_static_equipment_effect(
    effect: Any, avatar_actor_proven: bool, npc_actor_proven: bool,
    actor_expression: str | None = "actor",
) -> list[str] | None:
    """Lower only an explicit, same-event equipment transaction.

    Equipment changes are intentionally stricter than the legacy EOC/UI
    actions.  A type id, selector, or current-item read is not an Item
    identity.  The accepted migration descriptor therefore carries an exact
    callback-context Item handle and the explicit source plus displacement or
    destination holder required by ``services.equipment``.
    """
    if not isinstance(effect, dict) or len(effect) != 1:
        return None
    key = next(iter(effect))
    operation_names = {
        "wield": "wield",
        "wear": "wear",
        "takeoff": "unequip",
        "unequip": "unequip",
        "u_wield": "wield",
        "u_wear": "wear",
        "u_takeoff": "unequip",
        "u_unequip": "unequip",
        "npc_wield": "wield",
        "npc_wear": "wear",
        "npc_takeoff": "unequip",
        "npc_unequip": "unequip",
    }
    operation = operation_names.get(key)
    if operation is None:
        return None
    if key.startswith("u_"):
        actor_proven = avatar_actor_proven
    elif key.startswith("npc_"):
        actor_proven = npc_actor_proven
    else:
        actor_proven = avatar_actor_proven or npc_actor_proven
    if not actor_proven or actor_expression is None:
        return None

    descriptor = effect[key]
    if not isinstance(descriptor, dict):
        return None
    required = (
        {"item_handle", "source_holder", "displaced_destination"}
        if operation != "unequip" else
        {"item_handle", "destination_holder"}
    )
    if set(descriptor) != required:
        return None

    def explicit_handle(value: Any) -> tuple[str, str] | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"context_handle"} or
            not bounded_utf8_string(value.get("context_handle"), 128)
        ):
            return None
        name = value["context_handle"]
        return f"context.data[{lua_quote(name)}]", name

    def explicit_holder(value: Any) -> tuple[str, str, str] | None:
        if (
            not isinstance(value, dict) or
            set(value) != {"character_handle", "slot"}
        ):
            return None
        character = explicit_handle(value.get("character_handle"))
        slot = value.get("slot")
        if (
            character is None or slot not in {"inventory", "worn", "wielded"}
        ):
            return None
        return (
            "{ kind = \"character\", character = " + character[0] +
            f", slot = {lua_quote(slot)} }}",
            character[1],
            slot,
        )

    item = explicit_handle(descriptor.get("item_handle"))
    if item is None:
        return None
    if operation == "unequip":
        destination = explicit_holder(descriptor.get("destination_holder"))
        if destination is None or destination[2] != "inventory":
            return None
        return [
            "    service_value(services.equipment.unequip(",
            f"        {actor_expression}, {item[0]}, {destination[0]}))",
        ]

    source = explicit_holder(descriptor.get("source_holder"))
    destination = explicit_holder(
        descriptor.get("displaced_destination")
    )
    if (
        source is None or destination is None or
        destination[2] != "inventory"
    ):
        return None
    return [
        f"    service_value(services.equipment.{operation}(",
        f"        {actor_expression}, {item[0]}, {source[0]}, {destination[0]}))",
    ]


